insert into public.bible_verses (version, book_abbrev, chapter, verse, text) values
('acf','mt',1,1,'Livro da geração de Jesus Cristo, filho de Davi, filho de Abraão.'),
('acf','mt',1,2,'Abraão gerou a Isaque; e Isaque gerou a Jacó; e Jacó gerou a Judá e a seus irmãos;'),
('acf','mt',1,3,'E Judá gerou, de Tamar, a Perez e a Zerá; e Perez gerou a Esrom; e Esrom gerou a Arão;'),
('acf','mt',1,4,'E Arão gerou a Aminadabe; e Aminadabe gerou a Naassom; e Naassom gerou a Salmom;'),
('acf','mt',1,5,'E Salmom gerou, de Raabe, a Boaz; e Boaz gerou de Rute a Obede; e Obede gerou a Jessé;'),
('acf','mt',1,6,'E Jessé gerou ao rei Davi; e o rei Davi gerou a Salomão da que foi mulher de Urias.'),
('acf','mt',1,7,'E Salomão gerou a Roboão; e Roboão gerou a Abias; e Abias gerou a Asa;'),
('acf','mt',1,8,'E Asa gerou a Josafá; e Josafá gerou a Jorão; e Jorão gerou a Uzias;'),
('acf','mt',1,9,'E Uzias gerou a Jotão; e Jotão gerou a Acaz; e Acaz gerou a Ezequias;'),
('acf','mt',1,10,'E Ezequias gerou a Manassés; e Manassés gerou a Amom; e Amom gerou a Josias;'),
('acf','mt',1,11,'E Josias gerou a Jeconias e a seus irmãos na deportação para babilônia.'),
('acf','mt',1,12,'E, depois da deportação para a babilônia, Jeconias gerou a Salatiel; e Salatiel gerou a Zorobabel;'),
('acf','mt',1,13,'E Zorobabel gerou a Abiúde; e Abiúde gerou a Eliaquim; e Eliaquim gerou a Azor;'),
('acf','mt',1,14,'E Azor gerou a Sadoque; e Sadoque gerou a Aquim; e Aquim gerou a Eliúde;'),
('acf','mt',1,15,'E Eliúde gerou a Eleazar; e Eleazar gerou a Matã; e Matã gerou a Jacó;'),
('acf','mt',1,16,'E Jacó gerou a José, marido de Maria, da qual nasceu JESUS, que se chama o Cristo.'),
('acf','mt',1,17,'De sorte que todas as gerações, desde Abraão até Davi, são catorze gerações; e desde Davi até a deportação para a babilônia, catorze gerações; e desde a deportação para a babilônia até Cristo, catorze gerações.'),
('acf','mt',1,18,'Ora, o nascimento de Jesus Cristo foi assim: Que estando Maria, sua mãe, desposada com José, antes de se ajuntarem, achou-se ter concebido do Espírito Santo.'),
('acf','mt',1,19,'Então José, seu marido, como era justo, e a não queria infamar, intentou deixá-la secretamente.'),
('acf','mt',1,20,'E, projetando ele isto, eis que em sonho lhe apareceu um anjo do Senhor, dizendo: José, filho de Davi, não temas receber a Maria, tua mulher, porque o que nela está gerado é do Espírito Santo;'),
('acf','mt',1,21,'E dará à luz um filho e chamarás o seu nome JESUS; porque ele salvará o seu povo dos seus pecados.'),
('acf','mt',1,22,'Tudo isto aconteceu para que se cumprisse o que foi dito da parte do Senhor, pelo profeta, que diz;'),
('acf','mt',1,23,'Eis que a virgem conceberá, e dará à luz um filho, E chamá-lo-ão pelo nome de EMANUEL, Que traduzido é: Deus conosco.'),
('acf','mt',1,24,'E José, despertando do sono, fez como o anjo do Senhor lhe ordenara, e recebeu a sua mulher;'),
('acf','mt',1,25,'E não a conheceu até que deu à luz seu filho, o primogênito; e pôs-lhe por nome Jesus.'),
('acf','mt',2,1,'E, tendo nascido Jesus em Belém de Judéia, no tempo do rei Herodes, eis que uns magos vieram do oriente a Jerusalém,'),
('acf','mt',2,2,'Dizendo: Onde está aquele que é nascido rei dos judeus? porque vimos a sua estrela no oriente, e viemos a adorá-lo.'),
('acf','mt',2,3,'E o rei Herodes, ouvindo isto, perturbou-se, e toda Jerusalém com ele.'),
('acf','mt',2,4,'E, congregados todos os príncipes dos sacerdotes, e os escribas do povo, perguntou-lhes onde havia de nascer o Cristo.'),
('acf','mt',2,5,'E eles lhe disseram: Em Belém de Judéia; porque assim está escrito pelo profeta:'),
('acf','mt',2,6,'E tu, Belém, terra de Judá,De modo nenhum és a menor entre as capitais de Judá;porque de ti sairá o Guia que há de apascentar o meu povo Israel.'),
('acf','mt',2,7,'Então Herodes, chamando secretamente os magos, inquiriu exatamente deles acerca do tempo em que a estrela lhes aparecera.'),
('acf','mt',2,8,'E, enviando-os a Belém, disse: Ide, e perguntai diligentemente pelo menino e, quando o achardes, participai-mo, para que também eu vá e o adore.'),
('acf','mt',2,9,'E, tendo eles ouvido o rei, partiram; e eis que a estrela, que tinham visto no oriente, ia adiante deles, até que, chegando, se deteve sobre o lugar onde estava o menino.'),
('acf','mt',2,10,'E, vendo eles a estrela, regoziram-se muito com grande alegria.'),
('acf','mt',2,11,'E, entrando na casa, acharam o menino com Maria sua mãe e, prostrando-se, o adoraram; e abrindo os seus tesouros, ofertaram-lhe dádivas: ouro, incenso e mirra.'),
('acf','mt',2,12,'E, sendo por divina revelação avisados num sonho para que não voltassem para junto de Herodes, partiram para a sua terra por outro caminho.'),
('acf','mt',2,13,'E, tendo eles se retirado, eis que o anjo do Senhor apareceu a José num sonho, dizendo: Levanta-te, e toma o menino e sua mãe, e foge para o Egito, e demora-te lá até que eu te diga; porque Herodes há de procurar o menino para o matar.'),
('acf','mt',2,14,'E, levantando-se ele, tomou o menino e sua mãe, de noite, e foi para o Egito.'),
('acf','mt',2,15,'E esteve lá, até à morte de Herodes, para que se cumprisse o que foi dito da parte do Senhor pelo profeta, que diz: Do Egito chamei o meu Filho.'),
('acf','mt',2,16,'Então Herodes, vendo que tinha sido iludido pelos magos, irritou-se muito, e mandou matar todos os meninos que havia em Belém, e em todos os seus contornos, de dois anos para baixo, segundo o tempo que diligentemente inquirira dos magos.'),
('acf','mt',2,17,'Então se cumpriu o que foi dito pelo profeta Jeremias, que diz:'),
('acf','mt',2,18,'Em Ramá se ouviu uma voz, Lamentação, choro e grande pranto: Raquel chorando os seus filhos, E não quer ser consolada, porque já não existem.'),
('acf','mt',2,19,'Morto, porém, Herodes, eis que o anjo do Senhor apareceu num sonho a José no Egito,'),
('acf','mt',2,20,'Dizendo: Levanta-te, e toma o menino e sua mãe, e vai para a terra de Israel; porque já estão mortos os que procuravam a morte do menino.'),
('acf','mt',2,21,'Então ele se levantou, e tomou o menino e sua mãe, e foi para a terra de Israel.'),
('acf','mt',2,22,'E, ouvindo que Arquelau reinava na Judéia em lugar de Herodes, seu pai, receou ir para lá; mas avisado num sonho, por divina revelação, foi para as partes da Galiléia.'),
('acf','mt',2,23,'E chegou, e habitou numa cidade chamada Nazaré, para que se cumprisse o que fora dito pelos profetas: Ele será chamado Nazareno.'),
('acf','mt',3,1,'E, naqueles dias, apareceu João o Batista pregando no deserto da Judéia,'),
('acf','mt',3,2,'E dizendo: Arrependei-vos, porque é chegado o reino dos céus.'),
('acf','mt',3,3,'Porque este é o anunciado pelo profeta Isaías, que disse:Voz do que clama no deserto:Preparai o caminho do Senhor,Endireitai as suas veredas.'),
('acf','mt',3,4,'E este João tinha as suas vestes de pelos de camelo, e um cinto de couro em torno de seus lombos; e alimentava-se de gafanhotos e de mel silvestre.'),
('acf','mt',3,5,'Então ia ter com ele Jerusalém, e toda a Judéia, e toda a província adjacente ao Jordão;'),
('acf','mt',3,6,'E eram por ele batizados no rio Jordão, confessando os seus pecados.'),
('acf','mt',3,7,'E, vendo ele muitos dos fariseus e dos saduceus, que vinham ao seu batismo, dizia-lhes: Raça de víboras, quem vos ensinou a fugir da ira futura?'),
('acf','mt',3,8,'Produzi, pois, frutos dignos de arrependimento;'),
('acf','mt',3,9,'E não presumais, de vós mesmos, dizendo: Temos por pai a Abraão; porque eu vos digo que, mesmo destas pedras, Deus pode suscitar filhos a Abraão.'),
('acf','mt',3,10,'E também agora está posto o machado à raiz das árvores; toda a árvore, pois, que não produz bom fruto, é cortada e lançada no fogo.'),
('acf','mt',3,11,'E eu, em verdade, vos batizo com água, para o arrependimento; mas aquele que vem após mim é mais poderoso do que eu; cujas alparcas não sou digno de levar; ele vos batizará com o Espírito Santo, e com fogo.'),
('acf','mt',3,12,'Em sua mão tem a pá, e limpará a sua eira, e recolherá no celeiro o seu trigo, e queimará a palha com fogo que nunca se apagará.'),
('acf','mt',3,13,'Então veio Jesus da Galiléia ter com João, junto do Jordão, para ser batizado por ele.'),
('acf','mt',3,14,'Mas João opunha-se-lhe, dizendo: Eu careço de ser batizado por ti, e vens tu a mim?'),
('acf','mt',3,15,'Jesus, porém, respondendo, disse-lhe: Deixa por agora, porque assim nos convém cumprir toda a justiça. Então ele o permitiu.'),
('acf','mt',3,16,'E, sendo Jesus batizado, saiu logo da água, e eis que se lhe abriram os céus, e viu o Espírito de Deus descendo como pomba e vindo sobre ele.'),
('acf','mt',3,17,'E eis que uma voz dos céus dizia: Este é o meu Filho amado, em quem me comprazo.'),
('acf','mt',4,1,'Então foi conduzido Jesus pelo Espírito ao deserto, para ser tentado pelo diabo.'),
('acf','mt',4,2,'E, tendo jejuado quarenta dias e quarenta noites, depois teve fome;'),
('acf','mt',4,3,'E, chegando-se a ele o tentador, disse: Se tu és o Filho de Deus, manda que estas pedras se tornem em pães.'),
('acf','mt',4,4,'Ele, porém, respondendo, disse: Está escrito: Nem só de pão viverá o homem, mas de toda a palavra que sai da boca de Deus.'),
('acf','mt',4,5,'Então o diabo o transportou à cidade santa, e colocou-o sobre o pináculo do templo,'),
('acf','mt',4,6,'E disse-lhe: Se tu és o Filho de Deus, lança-te de aqui abaixo; porque está escrito: Que aos seus anjos dará ordens a teu respeito, E tomar-te-ão nas mãos, Para que nunca tropeces com o teu pé em alguma pedra.'),
('acf','mt',4,7,'Disse-lhe Jesus: Também está escrito: Não tentarás o Senhor teu Deus.'),
('acf','mt',4,8,'Novamente o transportou o diabo a um monte muito alto; e mostrou-lhe todos os reinos do mundo, e a glória deles.'),
('acf','mt',4,9,'E disse-lhe: Tudo isto te darei se, prostrado, me adorares.'),
('acf','mt',4,10,'Então disse-lhe Jesus: Vai-te, Satanás, porque está escrito: Ao Senhor teu Deus adorarás, e só a ele servirás.'),
('acf','mt',4,11,'Então o diabo o deixou; e, eis que chegaram os anjos, e o serviam.'),
('acf','mt',4,12,'Jesus, porém, ouvindo que João estava preso, voltou para a Galiléia;'),
('acf','mt',4,13,'E, deixando Nazaré, foi habitar em Cafarnaum, cidade marítima, nos confins de Zebulom e Naftali;'),
('acf','mt',4,14,'Para que se cumprisse o que foi dito pelo profeta Isaías, que diz:'),
('acf','mt',4,15,'A terra de Zebulom, e a terra de Naftali, Junto ao caminho do mar, além do Jordão, A Galiléia das nações;'),
('acf','mt',4,16,'O povo, que estava assentado em trevas, Viu uma grande luz; aos que estavam assentados na região e sombra da morte,A luz raiou.'),
('acf','mt',4,17,'Desde então começou Jesus a pregar, e a dizer: Arrependei-vos, porque é chegado o reino dos céus.'),
('acf','mt',4,18,'E Jesus, andando junto ao mar da Galiléia, viu a dois irmãos, Simão, chamado Pedro, e André, seu irmão, os quais lançavam as redes ao mar, porque eram pescadores;'),
('acf','mt',4,19,'E disse-lhes: Vinde após mim, e eu vos farei pescadores de homens.'),
('acf','mt',4,20,'Então eles, deixando logo as redes, seguiram-no.'),
('acf','mt',4,21,'E, adiantando-se dali, viu outros dois irmãos, Tiago, filho de Zebedeu, e João, seu irmão, num barco com seu pai, Zebedeu, consertando as redes;'),
('acf','mt',4,22,'E chamou-os; eles, deixando imediatamente o barco e seu pai, seguiram-no.'),
('acf','mt',4,23,'E percorria Jesus toda a Galiléia, ensinando nas suas sinagogas e pregando o evangelho do reino, e curando todas as enfermidades e moléstias entre o povo.'),
('acf','mt',4,24,'E a sua fama correu por toda a Síria, e traziam-lhe todos os que padeciam, acometidos de várias enfermidades e tormentos, os endemoninhados, os lunáticos, e os paralíticos, e ele os curava.'),
('acf','mt',4,25,'E seguia-o uma grande multidão da Galiléia, de Decápolis, de Jerusalém, da Judéia, e de além do Jordão.'),
('acf','mt',5,1,'E Jesus, vendo a multidão, subiu a um monte, e, assentando-se, aproximaram-se dele os seus discípulos;'),
('acf','mt',5,2,'E, abrindo a sua boca, os ensinava, dizendo:'),
('acf','mt',5,3,'Bem-aventurados os pobres de espírito, porque deles é o reino dos céus;'),
('acf','mt',5,4,'Bem-aventurados os que choram, porque eles serão consolados;'),
('acf','mt',5,5,'Bem-aventurados os mansos, porque eles herdarão a terra;'),
('acf','mt',5,6,'Bem-aventurados os que têm fome e sede de justiça, porque eles serão fartos;'),
('acf','mt',5,7,'Bem-aventurados os misericordiosos, porque eles alcançarão misericórdia;'),
('acf','mt',5,8,'Bem-aventurados os limpos de coração, porque eles verão a Deus;'),
('acf','mt',5,9,'Bem-aventurados os pacificadores, porque eles serão chamados filhos de Deus;'),
('acf','mt',5,10,'Bem-aventurados os que sofrem perseguição por causa da justiça, porque deles é o reino dos céus;'),
('acf','mt',5,11,'Bem-aventurados sois vós, quando vos injuriarem e perseguirem e, mentindo, disserem todo o mal contra vós por minha causa.'),
('acf','mt',5,12,'Exultai e alegrai-vos, porque é grande o vosso galardão nos céus; porque assim perseguiram os profetas que foram antes de vós.'),
('acf','mt',5,13,'Vós sois o sal da terra; e se o sal for insípido, com que se há de salgar? Para nada mais presta senão para se lançar fora, e ser pisado pelos homens.'),
('acf','mt',5,14,'Vós sois a luz do mundo; não se pode esconder uma cidade edificada sobre um monte;'),
('acf','mt',5,15,'Nem se acende a candeia e se coloca debaixo do alqueire, mas no velador, e dá luz a todos que estão na casa.'),
('acf','mt',5,16,'Assim resplandeça a vossa luz diante dos homens, para que vejam as vossas boas obras e glorifiquem a vosso Pai, que está nos céus.'),
('acf','mt',5,17,'Não cuideis que vim destruir a lei ou os profetas: não vim abrogar, mas cumprir.'),
('acf','mt',5,18,'Porque em verdade vos digo que, até que o céu e a terra passem, nem um jota ou um til jamais passará da lei, sem que tudo seja cumprido.'),
('acf','mt',5,19,'Qualquer, pois, que violar um destes mandamentos, por menor que seja, e assim ensinar aos homens, será chamado o menor no reino dos céus; aquele, porém, que os cumprir e ensinar será chamado grande no reino dos céus.'),
('acf','mt',5,20,'Porque vos digo que, se a vossa justiça não exceder a dos escribas e fariseus, de modo nenhum entrareis no reino dos céus.'),
('acf','mt',5,21,'Ouvistes que foi dito aos antigos: Não matarás; mas qualquer que matar será réu de juízo.'),
('acf','mt',5,22,'Eu, porém, vos digo que qualquer que, sem motivo, se encolerizar contra seu irmão, será réu de juízo; e qualquer que disser a seu irmão: Raca, será réu do sinédrio; e qualquer que lhe disser: Louco, será réu do fogo do inferno.'),
('acf','mt',5,23,'Portanto, se trouxeres a tua oferta ao altar, e aí te lembrares de que teu irmão tem alguma coisa contra ti,'),
('acf','mt',5,24,'Deixa ali diante do altar a tua oferta, e vai reconciliar-te primeiro com teu irmão e, depois, vem e apresenta a tua oferta.'),
('acf','mt',5,25,'Concilia-te depressa com o teu adversário, enquanto estás no caminho com ele, para que não aconteça que o adversário te entregue ao juiz, e o juiz te entregue ao oficial, e te encerrem na prisão.'),
('acf','mt',5,26,'Em verdade te digo que de maneira nenhuma sairás dali enquanto não pagares o último ceitil.'),
('acf','mt',5,27,'Ouvistes que foi dito aos antigos: Não cometerás adultério.'),
('acf','mt',5,28,'Eu, porém, vos digo, que qualquer que atentar numa mulher para a cobiçar, já em seu coração cometeu adultério com ela.'),
('acf','mt',5,29,'Portanto, se o teu olho direito te escandalizar, arranca-o e atira-o para longe de ti; pois te é melhor que se perca um dos teus membros do que seja todo o teu corpo lançado no inferno.'),
('acf','mt',5,30,'E, se a tua mão direita te escandalizar, corta-a e atira-a para longe de ti, porque te é melhor que um dos teus membros se perca do que seja todo o teu corpo lançado no inferno.'),
('acf','mt',5,31,'Também foi dito: Qualquer que deixar sua mulher, dê-lhe carta de divórcio.'),
('acf','mt',5,32,'Eu, porém, vos digo que qualquer que repudiar sua mulher, a não ser por causa de fornicação, faz que ela cometa adultério, e qualquer que casar com a repudiada comete adultério.'),
('acf','mt',5,33,'Outrossim, ouvistes que foi dito aos antigos: Não perjurarás, mas cumprirás os teus juramentos ao Senhor.'),
('acf','mt',5,34,'Eu, porém, vos digo que de maneira nenhuma jureis; nem pelo céu, porque é o trono de Deus;'),
('acf','mt',5,35,'Nem pela terra, porque é o escabelo de seus pés; nem por Jerusalém, porque é a cidade do grande Rei;'),
('acf','mt',5,36,'Nem jurarás pela tua cabeça, porque não podes tornar um cabelo branco ou preto.'),
('acf','mt',5,37,'Seja, porém, o vosso falar: Sim, sim; Não, não; porque o que passa disto é de procedência maligna.'),
('acf','mt',5,38,'Ouvistes que foi dito: Olho por olho, e dente por dente.'),
('acf','mt',5,39,'Eu, porém, vos digo que não resistais ao mau; mas, se qualquer te bater na face direita, oferece-lhe também a outra;'),
('acf','mt',5,40,'E, ao que quiser pleitear contigo, e tirar-te a túnica, larga-lhe também a capa;'),
('acf','mt',5,41,'E, se qualquer te obrigar a caminhar uma milha, vai com ele duas.'),
('acf','mt',5,42,'Dá a quem te pedir, e não te desvies daquele que quiser que lhe emprestes.'),
('acf','mt',5,43,'Ouvistes que foi dito: Amarás o teu próximo, e odiarás o teu inimigo.'),
('acf','mt',5,44,'Eu, porém, vos digo: Amai a vossos inimigos, bendizei os que vos maldizem, fazei bem aos que vos odeiam, e orai pelos que vos maltratam e vos perseguem; para que sejais filhos do vosso Pai que está nos céus;'),
('acf','mt',5,45,'Porque faz que o seu sol se levante sobre maus e bons, e a chuva desça sobre justos e injustos.'),
('acf','mt',5,46,'Pois, se amardes os que vos amam, que galardão tereis? Não fazem os publicanos também o mesmo?'),
('acf','mt',5,47,'E, se saudardes unicamente os vossos irmãos, que fazeis de mais? Não fazem os publicanos também assim?'),
('acf','mt',5,48,'Sede vós pois perfeitos, como é perfeito o vosso Pai que está nos céus.'),
('acf','mt',6,1,'Guardai-vos de fazer a vossa esmola diante dos homens, para serdes vistos por eles; aliás, não tereis galardão junto de vosso Pai, que está nos céus.'),
('acf','mt',6,2,'Quando, pois, deres esmola, não faças tocar trombeta diante de ti, como fazem os hipócritas nas sinagogas e nas ruas, para serem glorificados pelos homens. Em verdade vos digo que já receberam o seu galardão.'),
('acf','mt',6,3,'Mas, quando tu deres esmola, não saiba a tua mão esquerda o que faz a tua direita;'),
('acf','mt',6,4,'Para que a tua esmola seja dada em secreto; e teu Pai, que vê em secreto, ele mesmo te recompensará publicamente.'),
('acf','mt',6,5,'E, quando orares, não sejas como os hipócritas; pois se comprazem em orar em pé nas sinagogas, e às esquinas das ruas, para serem vistos pelos homens. Em verdade vos digo que já receberam o seu galardão.'),
('acf','mt',6,6,'Mas tu, quando orares, entra no teu aposento e, fechando a tua porta, ora a teu Pai que está em secreto; e teu Pai, que vê em secreto, te recompensará publicamente.'),
('acf','mt',6,7,'E, orando, não useis de vãs repetições, como os gentios, que pensam que por muito falarem serão ouvidos.'),
('acf','mt',6,8,'Não vos assemelheis, pois, a eles; porque vosso Pai sabe o que vos é necessário, antes de vós lho pedirdes.'),
('acf','mt',6,9,'Portanto, vós orareis assim: Pai nosso, que estás nos céus, santificado seja o teu nome;'),
('acf','mt',6,10,'Venha o teu reino, seja feita a tua vontade, assim na terra como no céu;'),
('acf','mt',6,11,'O pão nosso de cada dia nos dá hoje;'),
('acf','mt',6,12,'E perdoa-nos as nossas dívidas, assim como nós perdoamos aos nossos devedores;'),
('acf','mt',6,13,'E não nos conduzas à tentação; mas livra-nos do mal; porque teu é o reino, e o poder, e a glória, para sempre. Amém.'),
('acf','mt',6,14,'Porque, se perdoardes aos homens as suas ofensas, também vosso Pai celestial vos perdoará a vós;'),
('acf','mt',6,15,'Se, porém, não perdoardes aos homens as suas ofensas, também vosso Pai vos não perdoará as vossas ofensas.'),
('acf','mt',6,16,'E, quando jejuardes, não vos mostreis contristados como os hipócritas; porque desfiguram os seus rostos, para que aos homens pareça que jejuam. Em verdade vos digo que já receberam o seu galardão.'),
('acf','mt',6,17,'Tu, porém, quando jejuares, unge a tua cabeça, e lava o teu rosto,'),
('acf','mt',6,18,'Para não pareceres aos homens que jejuas, mas a teu Pai, que está em secreto; e teu Pai, que vê em secreto, te recompensará publicamente.'),
('acf','mt',6,19,'Não ajunteis tesouros na terra, onde a traça e a ferrugem tudo consomem, e onde os ladrões minam e roubam;'),
('acf','mt',6,20,'Mas ajuntai tesouros no céu, onde nem a traça nem a ferrugem consomem, e onde os ladrões não minam nem roubam.'),
('acf','mt',6,21,'Porque onde estiver o vosso tesouro, aí estará também o vosso coração.'),
('acf','mt',6,22,'A candeia do corpo são os olhos; de sorte que, se os teus olhos forem bons, todo o teu corpo terá luz;'),
('acf','mt',6,23,'Se, porém, os teus olhos forem maus, o teu corpo será tenebroso. Se, portanto, a luz que em ti há são trevas, quão grandes serão tais trevas!'),
('acf','mt',6,24,'Ninguém pode servir a dois senhores; porque ou há de odiar um e amar o outro, ou se dedicará a um e desprezará o outro. Não podeis servir a Deus e a Mamom.'),
('acf','mt',6,25,'Por isso vos digo: Não andeis cuidadosos quanto à vossa vida, pelo que haveis de comer ou pelo que haveis de beber; nem quanto ao vosso corpo, pelo que haveis de vestir. Não é a vida mais do que o mantimento, e o corpo mais do que o vestuário?'),
('acf','mt',6,26,'Olhai para as aves do céu, que nem semeiam, nem segam, nem ajuntam em celeiros; e vosso Pai celestial as alimenta. Não tendes vós muito mais valor do que elas?'),
('acf','mt',6,27,'E qual de vós poderá, com todos os seus cuidados, acrescentar um côvado à sua estatura?'),
('acf','mt',6,28,'E, quanto ao vestuário, por que andais solícitos? Olhai para os lírios do campo, como eles crescem; não trabalham nem fiam;'),
('acf','mt',6,29,'E eu vos digo que nem mesmo Salomão, em toda a sua glória, se vestiu como qualquer deles.'),
('acf','mt',6,30,'Pois, se Deus assim veste a erva do campo, que hoje existe, e amanhã é lançada no forno, não vos vestirá muito mais a vós, homens de pouca fé?'),
('acf','mt',6,31,'Não andeis, pois, inquietos, dizendo: Que comeremos, ou que beberemos, ou com que nos vestiremos?'),
('acf','mt',6,32,'Porque todas estas coisas os gentios procuram. Decerto vosso Pai celestial bem sabe que necessitais de todas estas coisas;'),
('acf','mt',6,33,'Mas, buscai primeiro o reino de Deus, e a sua justiça, e todas estas coisas vos serão acrescentadas.'),
('acf','mt',6,34,'Não vos inquieteis, pois, pelo dia de amanhã, porque o dia de amanhã cuidará de si mesmo. Basta a cada dia o seu mal.'),
('acf','mt',7,1,'Não julgueis, para que não sejais julgados.'),
('acf','mt',7,2,'Porque com o juízo com que julgardes sereis julgados, e com a medida com que tiverdes medido vos hão de medir a vós.'),
('acf','mt',7,3,'E por que reparas tu no argueiro que está no olho do teu irmão, e não vês a trave que está no teu olho?'),
('acf','mt',7,4,'Ou como dirás a teu irmão: Deixa-me tirar o argueiro do teu olho, estando uma trave no teu?'),
('acf','mt',7,5,'Hipócrita, tira primeiro a trave do teu olho, e então cuidarás em tirar o argueiro do olho do teu irmão.'),
('acf','mt',7,6,'Não deis aos cães as coisas santas, nem deiteis aos porcos as vossas pérolas, não aconteça que as pisem com os pés e, voltando-se, vos despedacem.'),
('acf','mt',7,7,'Pedi, e dar-se-vos-á; buscai, e encontrareis; batei, e abrir-se-vos-á.'),
('acf','mt',7,8,'Porque, aquele que pede, recebe; e, o que busca, encontra; e, ao que bate, abrir-se-lhe-á.'),
('acf','mt',7,9,'E qual dentre vós é o homem que, pedindo-lhe pão o seu filho, lhe dará uma pedra?'),
('acf','mt',7,10,'E, pedindo-lhe peixe, lhe dará uma serpente?'),
('acf','mt',7,11,'Se vós, pois, sendo maus, sabeis dar boas coisas aos vossos filhos, quanto mais vosso Pai, que está nos céus, dará bens aos que lhe pedirem?'),
('acf','mt',7,12,'Portanto, tudo o que vós quereis que os homens vos façam, fazei-lho também vós, porque esta é a lei e os profetas.'),
('acf','mt',7,13,'Entrai pela porta estreita; porque larga é a porta, e espaçoso o caminho que conduz à perdição, e muitos são os que entram por ela;'),
('acf','mt',7,14,'E porque estreita é a porta, e apertado o caminho que leva à vida, e poucos há que a encontrem.'),
('acf','mt',7,15,'Acautelai-vos, porém, dos falsos profetas, que vêm até vós vestidos como ovelhas, mas, interiormente, são lobos devoradores.'),
('acf','mt',7,16,'Por seus frutos os conhecereis. Porventura colhem-se uvas dos espinheiros, ou figos dos abrolhos?'),
('acf','mt',7,17,'Assim, toda a árvore boa produz bons frutos, e toda a árvore má produz frutos maus.'),
('acf','mt',7,18,'Não pode a árvore boa dar maus frutos; nem a árvore má dar frutos bons.'),
('acf','mt',7,19,'Toda a árvore que não dá bom fruto corta-se e lança-se no fogo.'),
('acf','mt',7,20,'Portanto, pelos seus frutos os conhecereis.'),
('acf','mt',7,21,'Nem todo o que me diz: Senhor, Senhor! entrará no reino dos céus, mas aquele que faz a vontade de meu Pai, que está nos céus.'),
('acf','mt',7,22,'Muitos me dirão naquele dia: Senhor, Senhor, não profetizamos nós em teu nome? e em teu nome não expulsamos demônios? e em teu nome não fizemos muitas maravilhas?'),
('acf','mt',7,23,'E então lhes direi abertamente: Nunca vos conheci; apartai-vos de mim, vós que praticais a iniqüidade.'),
('acf','mt',7,24,'Todo aquele, pois, que escuta estas minhas palavras, e as pratica, assemelhá-lo-ei ao homem prudente, que edificou a sua casa sobre a rocha;'),
('acf','mt',7,25,'E desceu a chuva, e correram rios, e assopraram ventos, e combateram aquela casa, e não caiu, porque estava edificada sobre a rocha.'),
('acf','mt',7,26,'E aquele que ouve estas minhas palavras, e não as cumpre, compará-lo-ei ao homem insensato, que edificou a sua casa sobre a areia;'),
('acf','mt',7,27,'E desceu a chuva, e correram rios, e assopraram ventos, e combateram aquela casa, e caiu, e foi grande a sua queda.'),
('acf','mt',7,28,'E aconteceu que, concluindo Jesus este discurso, a multidão se admirou da sua doutrina;'),
('acf','mt',7,29,'Porquanto os ensinava como tendo autoridade; e não como os escribas.'),
('acf','mt',8,1,'E, descendo ele do monte, seguiu-o uma grande multidão.'),
('acf','mt',8,2,'E, eis que veio um leproso, e o adorou, dizendo: Senhor, se quiseres, podes tornar-me limpo.'),
('acf','mt',8,3,'E Jesus, estendendo a mão, tocou-o, dizendo: Quero; sê limpo. E logo ficou purificado da lepra.'),
('acf','mt',8,4,'Disse-lhe então Jesus: Olha, não o digas a alguém, mas vai, mostra-te ao sacerdote, e apresenta a oferta que Moisés determinou, para lhes servir de testemunho.'),
('acf','mt',8,5,'E, entrando Jesus em Cafarnaum, chegou junto dele um centurião, rogando-lhe,'),
('acf','mt',8,6,'E dizendo: Senhor, o meu criado jaz em casa, paralítico, e violentamente atormentado.'),
('acf','mt',8,7,'E Jesus lhe disse: Eu irei, e lhe darei saúde.'),
('acf','mt',8,8,'E o centurião, respondendo, disse: Senhor, não sou digno de que entres debaixo do meu telhado, mas dize somente uma palavra, e o meu criado há de sarar.'),
('acf','mt',8,9,'Pois também eu sou homem sob autoridade, e tenho soldados às minhas ordens; e digo a este: Vai, e ele vai; e a outro: Vem, e ele vem; e ao meu criado: Faze isto, e ele o faz.'),
('acf','mt',8,10,'E maravilhou-se Jesus, ouvindo isto, e disse aos que o seguiam: Em verdade vos digo que nem mesmo em Israel encontrei tanta fé.'),
('acf','mt',8,11,'Mas eu vos digo que muitos virão do oriente e do ocidente, e assentar-se-ão à mesa com Abraão, e Isaque, e Jacó, no reino dos céus;'),
('acf','mt',8,12,'E os filhos do reino serão lançados nas trevas exteriores; ali haverá pranto e ranger de dentes.'),
('acf','mt',8,13,'Então disse Jesus ao centurião: Vai, e como creste te seja feito. E naquela mesma hora o seu criado sarou.'),
('acf','mt',8,14,'E Jesus, entrando em casa de Pedro, viu a sogra deste acamada, e com febre.'),
('acf','mt',8,15,'E tocou-lhe na mão, e a febre a deixou; e levantou-se, e serviu-os.'),
('acf','mt',8,16,'E, chegada a tarde, trouxeram-lhe muitos endemoninhados, e ele com a sua palavra expulsou deles os espíritos, e curou todos os que estavam enfermos;'),
('acf','mt',8,17,'Para que se cumprisse o que fora dito pelo profeta Isaías, que diz: Ele tomou sobre si as nossas enfermidades, e levou as nossas doenças.'),
('acf','mt',8,18,'E Jesus, vendo em torno de si uma grande multidão, ordenou que passassem para o outro lado;'),
('acf','mt',8,19,'E, aproximando-se dele um escriba, disse-lhe: Mestre, aonde quer que fores, eu te seguirei.'),
('acf','mt',8,20,'E disse Jesus: As raposas têm covis, e as aves do céu têm ninhos, mas o Filho do homem não tem onde reclinar a cabeça.'),
('acf','mt',8,21,'E outro de seus discípulos lhe disse: Senhor, permite-me que primeiramente vá sepultar meu pai.'),
('acf','mt',8,22,'Jesus, porém, disse-lhe: Segue-me, e deixa os mortos sepultar os seus mortos.'),
('acf','mt',8,23,'E, entrando ele no barco, seus discípulos o seguiram;'),
('acf','mt',8,24,'E eis que no mar se levantou uma tempestade, tão grande que o barco era coberto pelas ondas; ele, porém, estava dormindo.'),
('acf','mt',8,25,'E os seus discípulos, aproximando-se, o despertaram, dizendo: Senhor, salva-nos! que perecemos.'),
('acf','mt',8,26,'E ele disse-lhes: Por que temeis, homens de pouca fé? Então, levantando-se, repreendeu os ventos e o mar, e seguiu-se uma grande bonança.'),
('acf','mt',8,27,'E aqueles homens se maravilharam, dizendo: Que homem é este, que até os ventos e o mar lhe obedecem?'),
('acf','mt',8,28,'E, tendo chegado ao outro lado, à província dos gergesenos, saíram-lhe ao encontro dois endemoninhados, vindos dos sepulcros; tão ferozes eram que ninguém podia passar por aquele caminho.'),
('acf','mt',8,29,'E eis que clamaram, dizendo: Que temos nós contigo, Jesus, Filho de Deus? Vieste aqui atormentar-nos antes do tempo?'),
('acf','mt',8,30,'E andava pastando distante deles uma manada de muitos porcos.'),
('acf','mt',8,31,'E os demônios rogaram-lhe, dizendo: Se nos expulsas, permite-nos que entremos naquela manada de porcos.'),
('acf','mt',8,32,'E ele lhes disse: Ide. E, saindo eles, se introduziram na manada dos porcos; e eis que toda aquela manada de porcos se precipitou no mar por um despenhadeiro, e morreram nas águas.'),
('acf','mt',8,33,'Os porqueiros fugiram e, chegando à cidade, divulgaram tudo o que acontecera aos endemoninhados.'),
('acf','mt',8,34,'E eis que toda aquela cidade saiu ao encontro de Jesus e, vendo-o, rogaram-lhe que se retirasse dos seus termos.'),
('acf','mt',9,1,'E, entrando no barco, passou para o outro lado, e chegou à sua cidade. E eis que lhe trouxeram um paralítico, deitado numa cama.'),
('acf','mt',9,2,'E Jesus, vendo a fé deles, disse ao paralítico: Filho, tem bom ânimo, perdoados te são os teus pecados.'),
('acf','mt',9,3,'E eis que alguns dos escribas diziam entre si: Ele blasfema.'),
('acf','mt',9,4,'Mas Jesus, conhecendo os seus pensamentos, disse: Por que pensais mal em vossos corações?'),
('acf','mt',9,5,'Pois, qual é mais fácil? dizer: Perdoados te são os teus pecados; ou dizer: Levanta-te e anda?'),
('acf','mt',9,6,'Ora, para que saibais que o Filho do homem tem na terra autoridade para perdoar pecados (disse então ao paralítico): Levanta-te, toma a tua cama, e vai para tua casa.'),
('acf','mt',9,7,'E, levantando-se, foi para sua casa.'),
('acf','mt',9,8,'E a multidão, vendo isto, maravilhou-se, e glorificou a Deus, que dera tal poder aos homens.'),
('acf','mt',9,9,'E Jesus, passando adiante dali, viu assentado na alfândega um homem, chamado Mateus, e disse-lhe: Segue-me. E ele, levantando-se, o seguiu.'),
('acf','mt',9,10,'E aconteceu que, estando ele em casa sentado à mesa, chegaram muitos publicanos e pecadores, e sentaram-se juntamente com Jesus e seus discípulos.'),
('acf','mt',9,11,'E os fariseus, vendo isto, disseram aos seus discípulos: Por que come o vosso Mestre com os publicanos e pecadores?'),
('acf','mt',9,12,'Jesus, porém, ouvindo, disse-lhes: Não necessitam de médico os sãos, mas, sim, os doentes.'),
('acf','mt',9,13,'Ide, porém, e aprendei o que significa: Misericórdia quero, e não sacrifício. Porque eu nào vim a chamar os justos, mas os pecadores, ao arrependimento.'),
('acf','mt',9,14,'Então, chegaram ao pé dele os discípulos de João, dizendo: Por que jejuamos nós e os fariseus muitas vezes, e os teus discípulos não jejuam?'),
('acf','mt',9,15,'E disse-lhes Jesus: Podem porventura andar tristes os filhos das bodas, enquanto o esposo está com eles? Dias, porém, virão, em que lhes será tirado o esposo, e então jejuarão.'),
('acf','mt',9,16,'Ninguém deita remendo de pano novo em roupa velha, porque semelhante remendo rompe a roupa, e faz-se maior a rotura.'),
('acf','mt',9,17,'Nem se deita vinho novo em odres velhos; aliás rompem-se os odres, e entorna-se o vinho, e os odres estragam-se; mas deita-se vinho novo em odres novos, e assim ambos se conservam.'),
('acf','mt',9,18,'Dizendo-lhes ele estas coisas, eis que chegou um chefe, e o adorou, dizendo: Minha filha faleceu agora mesmo; mas vem, impõe-lhe a tua mão, e ela viverá.'),
('acf','mt',9,19,'E Jesus, levantando-se, seguiu-o, ele e os seus discípulos.'),
('acf','mt',9,20,'E eis que uma mulher que havia já doze anos padecia de um fluxo de sangue, chegando por detrás dele, tocou a orla de sua roupa;'),
('acf','mt',9,21,'Porque dizia consigo: Se eu tão-somente tocar a sua roupa, ficarei sã.'),
('acf','mt',9,22,'E Jesus, voltando-se, e vendo-a, disse: Tem ânimo, filha, a tua fé te salvou. E imediatamente a mulher ficou sã.'),
('acf','mt',9,23,'E Jesus, chegando à casa daquele chefe, e vendo os instrumentistas, e o povo em alvoroço,'),
('acf','mt',9,24,'Disse-lhes: Retirai-vos, que a menina não está morta, mas dorme. E riam-se dele.'),
('acf','mt',9,25,'E, logo que o povo foi posto fora, entrou Jesus, e pegou-lhe na mão, e a menina levantou-se.'),
('acf','mt',9,26,'E espalhou-se aquela notícia por todo aquele país.'),
('acf','mt',9,27,'E, partindo Jesus dali, seguiram-no dois cegos, clamando, e dizendo: Tem compaixão de nós, filho de Davi.'),
('acf','mt',9,28,'E, quando chegou à casa, os cegos se aproximaram dele; e Jesus disse-lhes: Credes vós que eu possa fazer isto? Disseram-lhe eles: Sim, Senhor.'),
('acf','mt',9,29,'Tocou então os olhos deles, dizendo: Seja-vos feito segundo a vossa fé.'),
('acf','mt',9,30,'E os olhos se lhes abriram. E Jesus ameaçou-os, dizendo: Olhai que ninguém o saiba.'),
('acf','mt',9,31,'Mas, tendo eles saído, divulgaram a sua fama por toda aquela terra.'),
('acf','mt',9,32,'E, havendo-se eles retirado, trouxeram-lhe um homem mudo e endemoninhado.'),
('acf','mt',9,33,'E, expulso o demônio, falou o mudo; e a multidão se maravilhou, dizendo: Nunca tal se viu em Israel.'),
('acf','mt',9,34,'Mas os fariseus diziam: Ele expulsa os demônios pelo príncipe dos demônios.'),
('acf','mt',9,35,'E percorria Jesus todas as cidades e aldeias, ensinando nas sinagogas deles, e pregando o evangelho do reino, e curando todas as enfermidades e moléstias entre o povo.'),
('acf','mt',9,36,'E, vendo as multidões, teve grande compaixão delas, porque andavam cansadas e desgarradas, como ovelhas que não têm pastor.'),
('acf','mt',9,37,'Então, disse aos seus discípulos: A seara é realmente grande, mas poucos os ceifeiros.'),
('acf','mt',9,38,'Rogai, pois, ao Senhor da seara, que mande ceifeiros para a sua seara.'),
('acf','mt',10,1,'E, chamando os seus doze discípulos, deu-lhes poder sobre os espíritos imundos, para os expulsarem, e para curarem toda a enfermidade e todo o mal.'),
('acf','mt',10,2,'Ora, os nomes dos doze apóstolos são estes: O primeiro, Simão, chamado Pedro, e André, seu irmão; Tiago, filho de Zebedeu, e João, seu irmão;'),
('acf','mt',10,3,'Filipe e Bartolomeu; Tomé e Mateus, o publicano; Tiago, filho de Alfeu, e Lebeu, apelidado Tadeu;'),
('acf','mt',10,4,'Simão, o Cananita, e Judas Iscariotes, aquele que o traiu.'),
('acf','mt',10,5,'Jesus enviou estes doze, e lhes ordenou, dizendo: Não ireis pelo caminho dos gentios, nem entrareis em cidade de samaritanos;'),
('acf','mt',10,6,'Mas ide antes às ovelhas perdidas da casa de Israel;'),
('acf','mt',10,7,'E, indo, pregai, dizendo: É chegado o reino dos céus.'),
('acf','mt',10,8,'Curai os enfermos, limpai os leprosos, ressuscitai os mortos, expulsai os demônios; de graça recebestes, de graça dai.'),
('acf','mt',10,9,'Não possuais ouro, nem prata, nem cobre, em vossos cintos,'),
('acf','mt',10,10,'Nem alforges para o caminho, nem duas túnicas, nem alparcas, nem bordões; porque digno é o operário do seu alimento.'),
('acf','mt',10,11,'E, em qualquer cidade ou aldeia em que entrardes, procurai saber quem nela seja digno, e hospedai-vos aí, até que vos retireis.'),
('acf','mt',10,12,'E, quando entrardes nalguma casa, saudai-a;'),
('acf','mt',10,13,'E, se a casa for digna, desça sobre ela a vossa paz; mas, se não for digna, torne para vós a vossa paz.'),
('acf','mt',10,14,'E, se ninguém vos receber, nem escutar as vossas palavras, saindo daquela casa ou cidade, sacudi o pó dos vossos pés.'),
('acf','mt',10,15,'Em verdade vos digo que, no dia do juízo, haverá menos rigor para o país de Sodoma e Gomorra do que para aquela cidade.'),
('acf','mt',10,16,'Eis que vos envio como ovelhas ao meio de lobos; portanto, sede prudentes como as serpentes e inofensivos como as pombas.'),
('acf','mt',10,17,'Acautelai-vos, porém, dos homens; porque eles vos entregarão aos sinédrios, e vos açoitarão nas suas sinagogas;'),
('acf','mt',10,18,'E sereis até conduzidos à presença dos governadores, e dos reis, por causa de mim, para lhes servir de testemunho a eles, e aos gentios.'),
('acf','mt',10,19,'Mas, quando vos entregarem, não vos dê cuidado como, ou o que haveis de falar, porque naquela mesma hora vos será ministrado o que haveis de dizer.'),
('acf','mt',10,20,'Porque não sois vós quem falará, mas o Espírito de vosso Pai é que fala em vós.'),
('acf','mt',10,21,'E o irmão entregará à morte o irmão, e o pai o filho; e os filhos se levantarão contra os pais, e os matarão.'),
('acf','mt',10,22,'E odiados de todos sereis por causa do meu nome; mas aquele que perseverar até ao fim, esse será salvo.'),
('acf','mt',10,23,'Quando pois vos perseguirem nesta cidade, fugi para outra; porque em verdade vos digo que não acabareis de percorrer as cidades de Israel sem que venha o Filho do homem.'),
('acf','mt',10,24,'Não é o discípulo mais do que o mestre, nem o servo mais do que o seu senhor.'),
('acf','mt',10,25,'Basta ao discípulo ser como seu mestre, e ao servo como seu senhor. Se chamaram Belzebu ao pai de família, quanto mais aos seus domésticos?'),
('acf','mt',10,26,'Portanto, não os temais; porque nada há encoberto que não haja de revelar-se, nem oculto que não haja de saber-se.'),
('acf','mt',10,27,'O que vos digo em trevas dizei-o em luz; e o que escutais ao ouvido pregai-o sobre os telhados.'),
('acf','mt',10,28,'E não temais os que matam o corpo e não podem matar a alma; temei antes aquele que pode fazer perecer no inferno a alma e o corpo.'),
('acf','mt',10,29,'Não se vendem dois passarinhos por um ceitil? e nenhum deles cairá em terra sem a vontade de vosso Pai.'),
('acf','mt',10,30,'E até mesmo os cabelos da vossa cabeça estão todos contados.'),
('acf','mt',10,31,'Não temais, pois; mais valeis vós do que muitos passarinhos.'),
('acf','mt',10,32,'Portanto, qualquer que me confessar diante dos homens, eu o confessarei diante de meu Pai, que está nos céus.'),
('acf','mt',10,33,'Mas qualquer que me negar diante dos homens, eu o negarei também diante de meu Pai, que está nos céus.'),
('acf','mt',10,34,'Não cuideis que vim trazer a paz à terra; não vim trazer paz, mas espada;'),
('acf','mt',10,35,'Porque eu vim pôr em dissensão o homem contra seu pai, e a filha contra sua mãe, e a nora contra sua sogra;'),
('acf','mt',10,36,'E assim os inimigos do homem serão os seus familiares.'),
('acf','mt',10,37,'Quem ama o pai ou a mãe mais do que a mim não é digno de mim; e quem ama o filho ou a filha mais do que a mim não é digno de mim.'),
('acf','mt',10,38,'E quem não toma a sua cruz, e não segue após mim, não é digno de mim.'),
('acf','mt',10,39,'Quem achar a sua vida perdê-la-á; e quem perder a sua vida, por amor de mim, achá-la-á.'),
('acf','mt',10,40,'Quem vos recebe, a mim me recebe; e quem me recebe a mim, recebe aquele que me enviou.'),
('acf','mt',10,41,'Quem recebe um profeta em qualidade de profeta, receberá galardão de profeta; e quem recebe um justo na qualidade de justo, receberá galardão de justo.'),
('acf','mt',10,42,'E qualquer que tiver dado só que seja um copo de água fria a um destes pequenos, em nome de discípulo, em verdade vos digo que de modo algum perderá o seu galardão.'),
('acf','mt',11,1,'E aconteceu que, acabando Jesus de dar instruções aos seus doze discípulos, partiu dali a ensinar e a pregar nas cidades deles.'),
('acf','mt',11,2,'E João, ouvindo no cárcere falar dos feitos de Cristo, enviou dois dos seus discípulos,'),
('acf','mt',11,3,'A dizer-lhe: És tu aquele que havia de vir, ou esperamos outro?'),
('acf','mt',11,4,'E Jesus, respondendo, disse-lhes: Ide, e anunciai a João as coisas que ouvis e vedes:'),
('acf','mt',11,5,'Os cegos vêem, e os coxos andam; os leprosos são limpos, e os surdos ouvem; os mortos são ressuscitados, e aos pobres é anunciado o evangelho.'),
('acf','mt',11,6,'E bem-aventurado é aquele que não se escandalizar em mim.'),
('acf','mt',11,7,'E, partindo eles, começou Jesus a dizer às turbas, a respeito de João: Que fostes ver no deserto? uma cana agitada pelo vento?'),
('acf','mt',11,8,'Sim, que fostes ver? um homem ricamente vestido? Os que trajam ricamente estão nas casas dos reis.'),
('acf','mt',11,9,'Mas, então que fostes ver? um profeta? Sim, vos digo eu, e muito mais do que profeta;'),
('acf','mt',11,10,'Porque é este de quem está escrito:Eis que diante da tua face envio o meu anjo,que preparará diante de ti o teu caminho.'),
('acf','mt',11,11,'Em verdade vos digo que, entre os que de mulher têm nascido, não apareceu alguém maior do que João o Batista; mas aquele que é o menor no reino dos céus é maior do que ele.'),
('acf','mt',11,12,'E, desde os dias de João o Batista até agora, se faz violência ao reino dos céus, e pela força se apoderam dele.'),
('acf','mt',11,13,'Porque todos os profetas e a lei profetizaram até João.'),
('acf','mt',11,14,'E, se quereis dar crédito, é este o Elias que havia de vir.'),
('acf','mt',11,15,'Quem tem ouvidos para ouvir, ouça.'),
('acf','mt',11,16,'Mas, a quem assemelharei esta geração? É semelhante aos meninos que se assentam nas praças, e clamam aos seus companheiros,'),
('acf','mt',11,17,'E dizem: Tocamo-vos flauta, e não dançastes; cantamo-vos lamentações, e não chorastes.'),
('acf','mt',11,18,'Porquanto veio João, não comendo nem bebendo, e dizem: Tem demônio.'),
('acf','mt',11,19,'Veio o Filho do homem, comendo e bebendo, e dizem: Eis aí um homem comilão e beberrão, amigo dos publicanos e pecadores. Mas a sabedoria é justificada por seus filhos.'),
('acf','mt',11,20,'Então começou ele a lançar em rosto às cidades onde se operou a maior parte dos seus prodígios o não se haverem arrependido, dizendo:'),
('acf','mt',11,21,'Ai de ti, Corazim! ai de ti, Betsaida! porque, se em Tiro e em Sidom fossem feitos os prodígios que em vós se fizeram, há muito que se teriam arrependido, com saco e com cinza.'),
('acf','mt',11,22,'Por isso eu vos digo que haverá menos rigor para Tiro e Sidom, no dia do juízo, do que para vós.'),
('acf','mt',11,23,'E tu, Cafarnaum, que te ergues até ao céu, serás abatida até ao inferno; porque, se em Sodoma tivessem sido feitos os prodígios que em ti se operaram, teria ela permanecido até hoje.'),
('acf','mt',11,24,'Eu vos digo, porém, que haverá menos rigor para os de Sodoma, no dia do juízo, do que para ti.'),
('acf','mt',11,25,'Naquele tempo, respondendo Jesus, disse: Graças te dou, ó Pai, Senhor do céu e da terra, que ocultaste estas coisas aos sábios e entendidos, e as revelaste aos pequeninos.'),
('acf','mt',11,26,'Sim, ó Pai, porque assim te aprouve.'),
('acf','mt',11,27,'Todas as coisas me foram entregues por meu Pai, e ninguém conhece o Filho, senão o Pai; e ninguém conhece o Pai, senão o Filho, e aquele a quem o Filho o quiser revelar.'),
('acf','mt',11,28,'Vinde a mim, todos os que estais cansados e oprimidos, e eu vos aliviarei.'),
('acf','mt',11,29,'Tomai sobre vós o meu jugo, e aprendei de mim, que sou manso e humilde de coração; e encontrareis descanso para as vossas almas.'),
('acf','mt',11,30,'Porque o meu jugo é suave e o meu fardo é leve.'),
('acf','mt',12,1,'Naquele tempo passou Jesus pelas searas, em um sábado; e os seus discípulos, tendo fome, começaram a colher espigas, e a comer.'),
('acf','mt',12,2,'E os fariseus, vendo isto, disseram-lhe: Eis que os teus discípulos fazem o que não é lícito fazer num sábado.'),
('acf','mt',12,3,'Ele, porém, lhes disse: Não tendes lido o que fez Davi, quando teve fome, ele e os que com ele estavam?'),
('acf','mt',12,4,'Como entrou na casa de Deus, e comeu os pães da proposição, que não lhe era lícito comer, nem aos que com ele estavam, mas só aos sacerdotes?'),
('acf','mt',12,5,'Ou não tendes lido na lei que, aos sábados, os sacerdotes no templo violam o sábado, e ficam sem culpa?'),
('acf','mt',12,6,'Pois eu vos digo que está aqui quem é maior do que o templo.'),
('acf','mt',12,7,'Mas, se vós soubésseis o que significa: Misericórdia quero, e não sacrifício, não condenaríeis os inocentes.'),
('acf','mt',12,8,'Porque o Filho do homem até do sábado é Senhor.'),
('acf','mt',12,9,'E, partindo dali, chegou à sinagoga deles.'),
('acf','mt',12,10,'E, estava ali um homem que tinha uma das mãos mirrada; e eles, para o acusarem, o interrogaram, dizendo: É lícito curar nos sábados?'),
('acf','mt',12,11,'E ele lhes disse: Qual dentre vós será o homem que tendo uma ovelha, se num sábado ela cair numa cova, não lançará mão dela, e a levantará?'),
('acf','mt',12,12,'Pois, quanto mais vale um homem do que uma ovelha? É, por conseqüência, lícito fazer bem nos sábados.'),
('acf','mt',12,13,'Então disse àquele homem: Estende a tua mão. E ele a estendeu, e ficou sã como a outra.'),
('acf','mt',12,14,'E os fariseus, tendo saído, formaram conselho contra ele, para o matarem.'),
('acf','mt',12,15,'Jesus, sabendo isso, retirou-se dali, e acompanharam-no grandes multidões, e ele curou a todas.'),
('acf','mt',12,16,'E recomendava-lhes rigorosamente que o não descobrissem,'),
('acf','mt',12,17,'Para que se cumprisse o que fora dito pelo profeta Isaías, que diz:'),
('acf','mt',12,18,'Eis aqui o meu servo, que escolhi,o meu amado, em quem a minha alma se compraz;porei sobre ele o meu espírito,e anunciará aos gentios o juízo.'),
('acf','mt',12,19,'Não contenderá, nem clamará,Nem alguém ouvirá pelas ruas a sua voz;'),
('acf','mt',12,20,'Não esmagará a cana quebrada,enão apagará o morrão que fumega,até que faça triunfar o juízo;'),
('acf','mt',12,21,'E no seu nome os gentios esperarão.'),
('acf','mt',12,22,'Trouxeram-lhe, então, um endemoninhado cego e mudo; e, de tal modo o curou, que o cego e mudo falava e via.'),
('acf','mt',12,23,'E toda a multidão se admirava e dizia: Não é este o Filho de Davi?'),
('acf','mt',12,24,'Mas os fariseus, ouvindo isto, diziam: Este não expulsa os demônios senão por Belzebu, príncipe dos demônios.'),
('acf','mt',12,25,'Jesus, porém, conhecendo os seus pensamentos, disse-lhes: Todo o reino dividido contra si mesmo é devastado; e toda a cidade, ou casa, dividida contra si mesma não subsistirá.'),
('acf','mt',12,26,'E, se Satanás expulsa a Satanás, está dividido contra si mesmo; como subsistirá, pois, o seu reino?'),
('acf','mt',12,27,'E, se eu expulso os demônios por Belzebu, por quem os expulsam então vossos filhos? Portanto, eles mesmos serão os vossos juízes.'),
('acf','mt',12,28,'Mas, se eu expulso os demônios pelo Espírito de Deus, logo é chegado a vós o reino de Deus.'),
('acf','mt',12,29,'Ou, como pode alguém entrar na casa do homem valente, e furtar os seus bens, se primeiro não maniatar o valente, saqueando então a sua casa?'),
('acf','mt',12,30,'Quem não é comigo é contra mim; e quem comigo não ajunta, espalha.'),
('acf','mt',12,31,'Portanto, eu vos digo: Todo o pecado e blasfêmia se perdoará aos homens; mas a blasfêmia contra o Espírito não será perdoada aos homens.'),
('acf','mt',12,32,'E, se qualquer disser alguma palavra contra o Filho do homem, ser-lhe-á perdoado; mas, se alguém falar contra o Espírito Santo, não lhe será perdoado, nem neste século nem no futuro.'),
('acf','mt',12,33,'Ou fazei a árvore boa, e o seu fruto bom, ou fazei a árvore má, e o seu fruto mau; porque pelo fruto se conhece a árvore.'),
('acf','mt',12,34,'Raça de víboras, como podeis vós dizer boas coisas, sendo maus? Pois do que há em abundância no coração, disso fala a boca.'),
('acf','mt',12,35,'O homem bom tira boas coisas do bom tesouro do seu coração, e o homem mau do mau tesouro tira coisas más.'),
('acf','mt',12,36,'Mas eu vos digo que de toda a palavra ociosa que os homens disserem hão de dar conta no dia do juízo.'),
('acf','mt',12,37,'Porque por tuas palavras serás justificado, e por tuas palavras serás condenado.'),
('acf','mt',12,38,'Então alguns dos escribas e dos fariseus tomaram a palavra, dizendo: Mestre, quiséramos ver da tua parte algum sinal.'),
('acf','mt',12,39,'Mas ele lhes respondeu, e disse: Uma geração má e adúltera pede um sinal, porém, não se lhe dará outro sinal senão o sinal do profeta Jonas;'),
('acf','mt',12,40,'Pois, como Jonas esteve três dias e três noites no ventre da baleia, assim estará o Filho do homem três dias e três noites no seio da terra.'),
('acf','mt',12,41,'Os ninivitas ressurgirão no juízo com esta geração, e a condenarão, porque se arrependeram com a pregação de Jonas. E eis que está aqui quem é maior do que Jonas.'),
('acf','mt',12,42,'A rainha do sul se levantará no dia do juízo com esta geração, e a condenará; porque veio dos confins da terra para ouvir a sabedoria de Salomão. E eis que está aqui quem é maior do que Salomão.'),
('acf','mt',12,43,'E, quando o espírito imundo tem saído do homem, anda por lugares áridos, buscando repouso, e não o encontra.'),
('acf','mt',12,44,'Então diz: Voltarei para a minha casa, de onde saí. E, voltando, acha-a desocupada, varrida e adornada.'),
('acf','mt',12,45,'Então vai, e leva consigo outros sete espíritos piores do que ele e, entrando, habitam ali; e são os últimos atos desse homem piores do que os primeiros. Assim acontecerá também a esta geração má.'),
('acf','mt',12,46,'E, falando ele ainda à multidão, eis que estavam fora sua mãe e seus irmãos, pretendendo falar-lhe.'),
('acf','mt',12,47,'E disse-lhe alguém: Eis que estão ali fora tua mãe e teus irmãos, que querem falar-te.'),
('acf','mt',12,48,'Ele, porém, respondendo, disse ao que lhe falara: Quem é minha mãe? E quem são meus irmãos?'),
('acf','mt',12,49,'E, estendendo a sua mão para os seus discípulos, disse: Eis aqui minha mãe e meus irmãos;'),
('acf','mt',12,50,'Porque, qualquer que fizer a vontade de meu Pai que está nos céus, este é meu irmão, e irmã e mãe.'),
('acf','mt',13,1,'Tendo Jesus saído de casa, naquele dia, estava assentado junto ao mar;'),
('acf','mt',13,2,'E ajuntou-se muita gente ao pé dele, de sorte que, entrando num barco, se assentou; e toda a multidão estava em pé na praia.'),
('acf','mt',13,3,'E falou-lhe de muitas coisas por parábolas, dizendo: Eis que o semeador saiu a semear.'),
('acf','mt',13,4,'E, quando semeava, uma parte da semente caiu ao pé do caminho, e vieram as aves, e comeram-na;'),
('acf','mt',13,5,'E outra parte caiu em pedregais, onde não havia terra bastante, e logo nasceu, porque não tinha terra funda;'),
('acf','mt',13,6,'Mas, vindo o sol, queimou-se, e secou-se, porque não tinha raiz.'),
('acf','mt',13,7,'E outra caiu entre espinhos, e os espinhos cresceram e sufocaram-na.'),
('acf','mt',13,8,'E outra caiu em boa terra, e deu fruto: um a cem, outro a sessenta e outro a trinta.'),
('acf','mt',13,9,'Quem tem ouvidos para ouvir, ouça.'),
('acf','mt',13,10,'E, acercando-se dele os discípulos, disseram-lhe: Por que lhes falas por parábolas?'),
('acf','mt',13,11,'Ele, respondendo, disse-lhes: Porque a vós é dado conhecer os mistérios do reino dos céus, mas a eles não lhes é dado;'),
('acf','mt',13,12,'Porque àquele que tem, se dará, e terá em abundância; mas àquele que não tem, até aquilo que tem lhe será tirado.'),
('acf','mt',13,13,'Por isso lhes falo por parábolas; porque eles, vendo, não vêem; e, ouvindo, não ouvem nem compreendem.'),
('acf','mt',13,14,'E neles se cumpre a profecia de Isaías, que diz:Ouvindo, ouvireis, mas não compreendereis,e, vendo, vereis, mas não percebereis.'),
('acf','mt',13,15,'Porque o coração deste povo está endurecido,E ouviram de mau grado com seus ouvidos,E fecharam seus olhos;Para que não vejam com os olhos,E ouçam com os ouvidos,e compreendam com o coração,e se convertam,e eu os cure.'),
('acf','mt',13,16,'Mas, bem-aventurados os vossos olhos, porque vêem, e os vossos ouvidos, porque ouvem.'),
('acf','mt',13,17,'Porque em verdade vos digo que muitos profetas e justos desejaram ver o que vós vedes, e não o viram; e ouvir o que vós ouvis, e não o ouviram.'),
('acf','mt',13,18,'Escutai vós, pois, a parábola do semeador.'),
('acf','mt',13,19,'Ouvindo alguém a palavra do reino, e não a entendendo, vem o maligno, e arrebata o que foi semeado no seu coração; este é o que foi semeado ao pé do caminho.'),
('acf','mt',13,20,'O que foi semeado em pedregais é o que ouve a palavra, e logo a recebe com alegria;'),
('acf','mt',13,21,'Mas não tem raiz em si mesmo, antes é de pouca duração; e, chegada a angústia e a perseguição, por causa da palavra, logo se ofende;'),
('acf','mt',13,22,'E o que foi semeado entre espinhos é o que ouve a palavra, mas os cuidados deste mundo, e a sedução das riquezas sufocam a palavra, e fica infrutífera;'),
('acf','mt',13,23,'Mas, o que foi semeado em boa terra é o que ouve e compreende a palavra; e dá fruto, e um produz cem, outro sessenta, e outro trinta.'),
('acf','mt',13,24,'Propôs-lhes outra parábola, dizendo: O reino dos céus é semelhante ao homem que semeia a boa semente no seu campo;'),
('acf','mt',13,25,'Mas, dormindo os homens, veio o seu inimigo, e semeou joio no meio do trigo, e retirou-se.'),
('acf','mt',13,26,'E, quando a erva cresceu e frutificou, apareceu também o joio.'),
('acf','mt',13,27,'E os servos do pai de família, indo ter com ele, disseram-lhe: Senhor, não semeaste tu, no teu campo, boa semente? Por que tem, então, joio?'),
('acf','mt',13,28,'E ele lhes disse: Um inimigo é quem fez isso. E os servos lhe disseram: Queres pois que vamos arrancá-lo?'),
('acf','mt',13,29,'Ele, porém, lhes disse: Não; para que, ao colher o joio, não arranqueis também o trigo com ele.'),
('acf','mt',13,30,'Deixai crescer ambos juntos até à ceifa; e, por ocasião da ceifa, direi aos ceifeiros: Colhei primeiro o joio, e atai-o em molhos para o queimar; mas, o trigo, ajuntai-o no meu celeiro.'),
('acf','mt',13,31,'Outra parábola lhes propôs, dizendo: O reino dos céus é semelhante ao grão de mostarda que o homem, pegando nele, semeou no seu campo;'),
('acf','mt',13,32,'O qual é, realmente, a menor de todas as sementes; mas, crescendo, é a maior das plantas, e faz-se uma árvore, de sorte que vêm as aves do céu, e se aninham nos seus ramos.'),
('acf','mt',13,33,'Outra parábola lhes disse: O reino dos céus é semelhante ao fermento, que uma mulher toma e introduz em três medidas de farinha, até que tudo esteja levedado.'),
('acf','mt',13,34,'Tudo isto disse Jesus, por parábolas à multidão, e nada lhes falava sem parábolas;'),
('acf','mt',13,35,'Para que se cumprisse o que fora dito pelo profeta, que disse: Abrirei em parábolas a minha boca; Publicarei coisas ocultas desde a fundação do mundo.'),
('acf','mt',13,36,'Então, tendo despedido a multidão, foi Jesus para casa. E chegaram ao pé dele os seus discípulos, dizendo: Explica-nos a parábola do joio do campo.'),
('acf','mt',13,37,'E ele, respondendo, disse-lhes: O que semeia a boa semente, é o Filho do homem;'),
('acf','mt',13,38,'O campo é o mundo; e a boa semente são os filhos do reino; e o joio são os filhos do maligno;'),
('acf','mt',13,39,'O inimigo, que o semeou, é o diabo; e a ceifa é o fim do mundo; e os ceifeiros são os anjos.'),
('acf','mt',13,40,'Assim como o joio é colhido e queimado no fogo, assim será na consumação deste mundo.'),
('acf','mt',13,41,'Mandará o Filho do homem os seus anjos, e eles colherão do seu reino tudo o que causa escândalo, e os que cometem iniqüidade.'),
('acf','mt',13,42,'E lançá-los-ão na fornalha de fogo; ali haverá pranto e ranger de dentes.'),
('acf','mt',13,43,'Então os justos resplandecerão como o sol, no reino de seu Pai. Quem tem ouvidos para ouvir, ouça.'),
('acf','mt',13,44,'Também o reino dos céus é semelhante a um tesouro escondido num campo, que um homem achou e escondeu; e, pelo gozo dele, vai, vende tudo quanto tem, e compra aquele campo.'),
('acf','mt',13,45,'Outrossim o reino dos céus é semelhante ao homem, negociante, que busca boas pérolas;'),
('acf','mt',13,46,'E, encontrando uma pérola de grande valor, foi, vendeu tudo quanto tinha, e comprou-a.'),
('acf','mt',13,47,'Igualmente o reino dos céus é semelhante a uma rede lançada ao mar, e que apanha toda a qualidade de peixes.'),
('acf','mt',13,48,'E, estando cheia, a puxam para a praia; e, assentando-se, apanham para os cestos os bons; os ruins, porém, lançam fora.'),
('acf','mt',13,49,'Assim será na consumação dos séculos: virão os anjos, e separarão os maus de entre os justos,'),
('acf','mt',13,50,'E lançá-los-ão na fornalha de fogo; ali haverá pranto e ranger de dentes.'),
('acf','mt',13,51,'E disse-lhes Jesus: Entendestes todas estas coisas? Disseram-lhe eles: Sim, Senhor.'),
('acf','mt',13,52,'E ele disse-lhes: Por isso, todo o escriba instruído acerca do reino dos céus é semelhante a um pai de família, que tira do seu tesouro coisas novas e velhas.'),
('acf','mt',13,53,'E aconteceu que Jesus, concluindo estas parábolas, se retirou dali.'),
('acf','mt',13,54,'E, chegando à sua pátria, ensinava-os na sinagoga deles, de sorte que se maravilhavam, e diziam: De onde veio a este a sabedoria, e estas maravilhas?'),
('acf','mt',13,55,'Não é este o filho do carpinteiro? e não se chama sua mãe Maria, e seus irmãos Tiago, e José, e Simão, e Judas?'),
('acf','mt',13,56,'E não estão entre nós todas as suas irmãs? De onde lhe veio, pois, tudo isto?'),
('acf','mt',13,57,'E escandalizavam-se nele. Jesus, porém, lhes disse: Não há profeta sem honra, a não ser na sua pátria e na sua casa.'),
('acf','mt',13,58,'E não fez ali muitas maravilhas, por causa da incredulidade deles.'),
('acf','mt',14,1,'Naquele tempo ouviu Herodes, o tetrarca, a fama de Jesus,'),
('acf','mt',14,2,'E disse aos seus criados: Este é João o Batista; ressuscitou dos mortos, e por isso estas maravilhas operam nele.'),
('acf','mt',14,3,'Porque Herodes tinha prendido João, e tinha-o maniatado e encerrado no cárcere, por causa de Herodias, mulher de seu irmão Filipe;'),
('acf','mt',14,4,'Porque João lhe dissera: Não te é lícito possuí-la.'),
('acf','mt',14,5,'E, querendo matá-lo, temia o povo; porque o tinham como profeta.'),
('acf','mt',14,6,'Festejando-se, porém, o dia natalício de Herodes, dançou a filha de Herodias diante dele, e agradou a Herodes.'),
('acf','mt',14,7,'Por isso prometeu, com juramento, dar-lhe tudo o que pedisse;'),
('acf','mt',14,8,'E ela, instruída previamente por sua mãe, disse: Dá-me aqui, num prato, a cabeça de João o Batista.'),
('acf','mt',14,9,'E o rei afligiu-se, mas, por causa do juramento, e dos que estavam à mesa com ele, ordenou que se lhe desse.'),
('acf','mt',14,10,'E mandou degolar João no cárcere.'),
('acf','mt',14,11,'E a sua cabeça foi trazida num prato, e dada à jovem, e ela a levou a sua mãe.'),
('acf','mt',14,12,'E chegaram os seus discípulos, e levaram o corpo, e o sepultaram; e foram anunciá-lo a Jesus.'),
('acf','mt',14,13,'E Jesus, ouvindo isto, retirou-se dali num barco, para um lugar deserto, apartado; e, sabendo-o o povo, seguiu-o a pé desde as cidades.'),
('acf','mt',14,14,'E, Jesus, saindo, viu uma grande multidão, e possuído de íntima compaixão para com ela, curou os seus enfermos.'),
('acf','mt',14,15,'E, sendo chegada a tarde, os seus discípulos aproximaram-se dele, dizendo: O lugar é deserto, e a hora é já avançada; despede a multidão, para que vão pelas aldeias, e comprem comida para si.'),
('acf','mt',14,16,'Jesus, porém, lhes disse: Não é mister que vão; dai-lhes vós de comer.'),
('acf','mt',14,17,'Então eles lhe disseram: Não temos aqui senão cinco pães e dois peixes.'),
('acf','mt',14,18,'E ele disse: Trazei-mos aqui.'),
('acf','mt',14,19,'E, tendo mandado que a multidão se assentasse sobre a erva, tomou os cinco pães e os dois peixes, e, erguendo os olhos ao céu, os abençoou, e, partindo os pães, deu-os aos discípulos, e os discípulos à multidão.'),
('acf','mt',14,20,'E comeram todos, e saciaramse; e levantaram dos pedaços, que sobejaram, doze alcofas cheias.'),
('acf','mt',14,21,'E os que comeram foram quase cinco mil homens, além das mulheres e crianças.'),
('acf','mt',14,22,'E logo ordenou Jesus que os seus discípulos entrassem no barco, e fossem adiante para o outro lado, enquanto despedia a multidão.'),
('acf','mt',14,23,'E, despedida a multidão, subiu ao monte para orar, à parte. E, chegada já a tarde, estava ali só.'),
('acf','mt',14,24,'E o barco estava já no meio do mar, açoitado pelas ondas; porque o vento era contrário;'),
('acf','mt',14,25,'Mas, à quarta vigília da noite, dirigiu-se Jesus para eles, andan-do por cima do mar.'),
('acf','mt',14,26,'E os discípulos, vendo-o an-dando sobre o mar, assustaram-se, dizendo: É um fantasma. E gritaram com medo.'),
('acf','mt',14,27,'Jesus, porém, lhes falou logo, dizendo: Tende bom ânimo, sou eu, não temais.'),
('acf','mt',14,28,'E respondeu-lhe Pedro, e disse: Senhor, se és tu, manda-me ir ter contigo por cima das águas.'),
('acf','mt',14,29,'E ele disse: Vem. E Pedro, descendo do barco, andou sobre as águas para ir ter com Jesus.'),
('acf','mt',14,30,'Mas, sentindo o vento forte, teve medo; e, começando a ir para o fundo, clamou, dizendo: Senhor, salva-me!'),
('acf','mt',14,31,'E logo Jesus, estendendo a mão, segurou-o, e disse-lhe: Homem de pouca fé, por que duvidaste?'),
('acf','mt',14,32,'E, quando subiram para o barco, acalmou o vento.'),
('acf','mt',14,33,'Então aproximaram-se os que estavam no barco, e adoraram-no, dizendo: És verdadeiramente o Filho de Deus.'),
('acf','mt',14,34,'E, tendo passado para o outro lado, chegaram à terra de Genesaré.'),
('acf','mt',14,35,'E, quando os homens daquele lugar o conheceram, mandaram por todas aquelas terras em redor e trouxeram-lhe todos os que estavam enfermos.'),
('acf','mt',14,36,'E rogavam-lhe que ao menos eles pudessem tocar a orla da sua roupa; e todos os que a tocavam ficavam sãos.'),
('acf','mt',15,1,'Então chegaram ao pé de Jesus uns escribas e fariseus de Jerusalém, dizendo:'),
('acf','mt',15,2,'Por que transgridem os teus discípulos a tradição dos anciãos? pois não lavam as mãos quando comem pão.'),
('acf','mt',15,3,'Ele, porém, respondendo, disse-lhes: Por que transgredis vós, também, o mandamento de Deus pela vossa tradição?'),
('acf','mt',15,4,'Porque Deus ordenou, dizendo: Honra a teu pai e a tua mãe; e: Quem maldisser ao pai ou à mãe, certamente morrerá.'),
('acf','mt',15,5,'Mas vós dizeis: Qualquer que disser ao pai ou à mãe: É oferta ao Senhor o que poderias aproveitar de mim; esse não precisa honrar nem a seu pai nem a sua mãe,'),
('acf','mt',15,6,'E assim invalidastes, pela vossa tradição, o mandamento de Deus.'),
('acf','mt',15,7,'Hipócritas, bem profetizou Isaías a vosso respeito, dizendo:'),
('acf','mt',15,8,'Este povo se aproxima de mim com a sua boca e me honra com os seus lábios, mas o seu coração está longe de mim.'),
('acf','mt',15,9,'Mas, em vão me adoram, ensinando doutrinas que são preceitos dos homens.'),
('acf','mt',15,10,'E, chamando a si a multidão, disse-lhes: Ouvi, e entendei:'),
('acf','mt',15,11,'O que contamina o homem não é o que entra na boca, mas o que sai da boca, isso é o que contamina o homem.'),
('acf','mt',15,12,'Então, acercando-se dele os seus discípulos, disseram-lhe: Sabes que os fariseus, ouvindo essas palavras, se escandalizaram?'),
('acf','mt',15,13,'Ele, porém, respondendo, disse: Toda a planta, que meu Pai celestial não plantou, será arrancada.'),
('acf','mt',15,14,'Deixai-os; são cegos condutores de cegos. Ora, se um cego guiar outro cego, ambos cairão na cova.'),
('acf','mt',15,15,'E Pedro, tomando a palavra, disse-lhe: Explica-nos essa parábola.'),
('acf','mt',15,16,'Jesus, porém, disse: Até vós mesmos estais ainda sem entender?'),
('acf','mt',15,17,'Ainda não compreendeis que tudo o que entra pela boca desce para o ventre, e é lançado fora?'),
('acf','mt',15,18,'Mas, o que sai da boca, procede do coração, e isso contamina o homem.'),
('acf','mt',15,19,'Porque do coração procedem os maus pensamentos, mortes, adultérios, fornicação, furtos, falsos testemunhos e blasfêmias.'),
('acf','mt',15,20,'São estas coisas que contaminam o homem; mas comer sem lavar as mãos, isso não contamina o homem.'),
('acf','mt',15,21,'E, partindo Jesus dali, foi para as partes de Tiro e de Sidom.'),
('acf','mt',15,22,'E eis que uma mulher cananéia, que saíra daquelas cercanias, clamou, dizendo: Senhor, Filho de Davi, tem misericórdia de mim, que minha filha está miseravelmente endemoninhada.'),
('acf','mt',15,23,'Mas ele não lhe respondeu palavra. E os seus discípulos, chegando ao pé dele, rogaram-lhe, dizendo: Despede-a, que vem gritando atrás de nós.'),
('acf','mt',15,24,'E ele, respondendo, disse: Eu não fui enviado senão às ovelhas perdidas da casa de Israel.'),
('acf','mt',15,25,'Então chegou ela, e adorou-o, dizendo: Senhor, socorre-me!'),
('acf','mt',15,26,'Ele, porém, respondendo, disse: Não é bom pegar no pão dos filhos e deitá-lo aos cachorrinhos.'),
('acf','mt',15,27,'E ela disse: Sim, Senhor, mas também os cachorrinhos comem das migalhas que caem da mesa dos seus senhores.'),
('acf','mt',15,28,'Então respondeu Jesus, e disse-lhe: Ó mulher, grande é a tua fé! Seja isso feito para contigo como tu desejas. E desde aquela hora a sua filha ficou sã.'),
('acf','mt',15,29,'Partindo Jesus dali, chegou ao pé do mar da Galiléia, e, subindo a um monte, assentou-se lá.'),
('acf','mt',15,30,'E veio ter com ele grandes multidões, que traziam coxos, cegos, mudos, aleijados, e outros muitos, e os puseram aos pés de Jesus, e ele os sarou,'),
('acf','mt',15,31,'De tal sorte, que a multidão se maravilhou vendo os mudos a falar, os aleijados sãos, os coxos a andar, e os cegos a ver; e glorificava o Deus de Israel.'),
('acf','mt',15,32,'E Jesus, chamando os seus discípulos, disse: Tenho compaixão da multidão, porque já está comigo há três dias, e não tem o que comer; e não quero despedi-la em jejum, para que não desfaleça no caminho.'),
('acf','mt',15,33,'E os seus discípulos disseram-lhe: De onde nos viriam, num deserto, tantos pães, para saciar tal multidão?'),
('acf','mt',15,34,'E Jesus disse-lhes: Quantos pães tendes? E eles disseram: Sete, e uns poucos de peixinhos.'),
('acf','mt',15,35,'Então mandou à multidão que se assentasse no chão,'),
('acf','mt',15,36,'E, tomando os sete pães e os peixes, e dando graças, partiu-os, e deu-os aos seus discípulos, e os discípulos à multidão.'),
('acf','mt',15,37,'E todos comeram e se saciaram; e levantaram, do que sobejou, sete cestos cheios de pedaços.'),
('acf','mt',15,38,'Ora, os que tinham comido eram quatro mil homens, além de mulheres e crianças.'),
('acf','mt',15,39,'E, tendo despedido a multidão, entrou no barco, e dirigiu-se ao território de Magadã.'),
('acf','mt',16,1,'E, chegando-se os fariseus e os saduceus, para o tentarem, pediram-lhe que lhes mostrasse algum sinal do céu.'),
('acf','mt',16,2,'Mas ele, respondendo, disse-lhes: Quando é chegada a tarde, dizeis: Haverá bom tempo, porque o céu está rubro.'),
('acf','mt',16,3,'E, pela manhã: Hoje haverá tempestade, porque o céu está de um vermelho sombrio. Hipócritas, sabeis discernir a face do céu, e não conheceis os sinais dos tempos?'),
('acf','mt',16,4,'Uma geração má e adúltera pede um sinal, e nenhum sinal lhe será dado, senão o sinal do profeta Jonas. E, deixando-os, retirou-se.'),
('acf','mt',16,5,'E, passando seus discípulos para o outro lado, tinham-se esquecido de trazer pão.'),
('acf','mt',16,6,'E Jesus disse-lhes: Adverti, e acautelai-vos do fermento dos fariseus e saduceus.'),
('acf','mt',16,7,'E eles arrazoavam entre si, dizendo: É porque não trouxemos pão.'),
('acf','mt',16,8,'E Jesus, percebendo isso, disse: Por que arrazoais entre vós, homens de pouca fé, sobre o não terdes trazido pão?'),
('acf','mt',16,9,'Não compreendeis ainda, nem vos lembrais dos cinco pães para cinco mil homens, e de quantas alcofas levantastes?'),
('acf','mt',16,10,'Nem dos sete pães para quatro mil, e de quantos cestos levantastes?'),
('acf','mt',16,11,'Como não compreendestes que não vos falei a respeito do pão, mas que vos guardásseis do fermento dos fariseus e saduceus?'),
('acf','mt',16,12,'Então compreenderam que não dissera que se guardassem do fermento do pão, mas da doutrina dos fariseus.'),
('acf','mt',16,13,'E, chegando Jesus às partes de Cesaréia de Filipe, interrogou os seus discípulos, dizendo: Quem dizem os homens ser o Filho do homem?'),
('acf','mt',16,14,'E eles disseram: Uns, João o Batista; outros, Elias; e outros, Jeremias, ou um dos profetas.'),
('acf','mt',16,15,'Disse-lhes ele: E vós, quem dizeis que eu sou?'),
('acf','mt',16,16,'E Simão Pedro, respondendo, disse: Tu és o Cristo, o Filho do Deus vivo.'),
('acf','mt',16,17,'E Jesus, respondendo, disse-lhe: Bem-aventurado és tu, Simão Barjonas, porque to não revelou a carne e o sangue, mas meu Pai, que está nos céus.'),
('acf','mt',16,18,'Pois também eu te digo que tu és Pedro, e sobre esta pedra edificarei a minha igreja, e as portas do inferno não prevalecerão contra ela;'),
('acf','mt',16,19,'E eu te darei as chaves do reino dos céus; e tudo o que ligares na terra será ligado nos céus, e tudo o que desligares na terra será desligado nos céus.'),
('acf','mt',16,20,'Então mandou aos seus discípulos que a ninguém dissessem que ele era Jesus o Cristo.'),
('acf','mt',16,21,'Desde então começou Jesus a mostrar aos seus discípulos que convinha ir a Jerusalém, e padecer muitas coisas dos anciãos, e dos principais dos sacerdotes, e dos escribas, e ser morto, e ressuscitar ao terceiro dia.'),
('acf','mt',16,22,'E Pedro, tomando-o de parte, começou a repreendê-lo, dizendo: Senhor, tem compaixão de ti; de modo nenhum te acontecerá isso.'),
('acf','mt',16,23,'Ele, porém, voltando-se, disse a Pedro: Para trás de mim, Satanás, que me serves de escândalo; porque não compreendes as coisas que são de Deus, mas só as que são dos homens.'),
('acf','mt',16,24,'Então disse Jesus aos seus discípulos: Se alguém quiser vir após mim, renuncie-se a si mesmo, tome sobre si a sua cruz, e siga-me;'),
('acf','mt',16,25,'Porque aquele que quiser salvar a sua vida, perdê-la-á, e quem perder a sua vida por amor de mim, achá-la-á.'),
('acf','mt',16,26,'Pois que aproveita ao homem ganhar o mundo inteiro, se perder a sua alma? Ou que dará o homem em recompensa da sua alma?'),
('acf','mt',16,27,'Porque o Filho do homem virá na glória de seu Pai, com os seus anjos; e então dará a cada um segundo as suas obras.'),
('acf','mt',16,28,'Em verdade vos digo que alguns há, dos que aqui estão, que não provarão a morte até que vejam vir o Filho do homem no seu reino.'),
('acf','mt',17,1,'Seis dias depois, tomou Jesus consigo a Pedro, e a Tiago, e a João, seu irmão, e os conduziu em particular a um alto monte,'),
('acf','mt',17,2,'E transfigurou-se diante deles; e o seu rosto resplandeceu como o sol, e as suas vestes se tornaram brancas como a luz.'),
('acf','mt',17,3,'E eis que lhes apareceram Moisés e Elias, falando com ele.'),
('acf','mt',17,4,'E Pedro, tomando a palavra, disse a Jesus: Senhor, bom é estarmos aqui; se queres, façamos aqui três tabernáculos, um para ti, um para Moisés, e um para Elias.'),
('acf','mt',17,5,'E, estando ele ainda a falar, eis que uma nuvem luminosa os cobriu. E da nuvem saiu uma voz que dizia: Este é o meu amado Filho, em quem me comprazo; escutai-o.'),
('acf','mt',17,6,'E os discípulos, ouvindo isto, caíram sobre os seus rostos, e tiveram grande medo.'),
('acf','mt',17,7,'E, aproximando-se Jesus, tocou-lhes, e disse: Levantai-vos, e não tenhais medo.'),
('acf','mt',17,8,'E, erguendo eles os olhos, ninguém viram senão unicamente a Jesus.'),
('acf','mt',17,9,'E, descendo eles do monte, Jesus lhes ordenou, dizendo: A ninguém conteis a visão, até que o Filho do homem seja ressuscitado dentre os mortos.'),
('acf','mt',17,10,'E os seus discípulos o interrogaram, dizendo: Por que dizem então os escribas que é mister que Elias venha primeiro?'),
('acf','mt',17,11,'E Jesus, respondendo, disse-lhes: Em verdade Elias virá primeiro, e restaurará todas as coisas;'),
('acf','mt',17,12,'Mas digo-vos que Elias já veio, e não o conheceram, mas fizeram-lhe tudo o que quiseram. Assim farão eles também padecer o Filho do homem.'),
('acf','mt',17,13,'Então entenderam os discípulos que lhes falara de João o Batista.'),
('acf','mt',17,14,'E, quando chegaram à multidão, aproximou-se-lhe um homem, pondo-se de joelhos diante dele, e dizendo:'),
('acf','mt',17,15,'Senhor, tem misericórdia de meu filho, que é lunático e sofre muito; pois muitas vezes cai no fogo, e muitas vezes na água;'),
('acf','mt',17,16,'E trouxe-o aos teus discípulos; e não puderam curá-lo.'),
('acf','mt',17,17,'E Jesus, respondendo, disse: Ó geração incrédula e perversa! até quando estarei eu convosco, e até quando vos sofrerei? Trazeimo aqui.'),
('acf','mt',17,18,'E, repreendeu Jesus o demônio, que saiu dele, e desde aquela hora o menino sarou.'),
('acf','mt',17,19,'Então os discípulos, aproximando-se de Jesus em particular, disseram: Por que não pudemos nós expulsá-lo?'),
('acf','mt',17,20,'E Jesus lhes disse: Por causa de vossa incredulidade; porque em verdade vos digo que, se tiverdes fé como um grão de mostarda, direis a este monte: Passa daqui para acolá, e há de passar; e nada vos será impossível.'),
('acf','mt',17,21,'Mas esta casta de demônios não se expulsa senão pela oração e pelo jejum.'),
('acf','mt',17,22,'Ora, achando-se eles na Galiléia, disse-lhes Jesus: O Filho do homem será entregue nas mãos dos homens;'),
('acf','mt',17,23,'E matá-lo-ão, e ao terceiro dia ressuscitará. E eles se entristeceram muito.'),
('acf','mt',17,24,'E, chegando eles a Cafarnaum, aproximaram-se de Pedro os que cobravam as dracmas, e disseram: O vosso mestre não paga as dracmas?'),
('acf','mt',17,25,'Disse ele: Sim. E, entrando em casa, Jesus se lhe antecipou, dizendo: Que te parece, Simão? De quem cobram os reis da terra os tributos, ou o censo? Dos seus filhos, ou dos alheios?'),
('acf','mt',17,26,'Disse-lhe Pedro: Dos alheios. Disse-lhe Jesus: Logo, estão livres os filhos.'),
('acf','mt',17,27,'Mas, para que os não escandalizemos, vai ao mar, lança o anzol, tira o primeiro peixe que subir, e abrindo-lhe a boca, encontrarás um estáter; toma-o, e dá-o por mim e por ti.'),
('acf','mt',18,1,'Naquela mesma hora chegaram os discípulos ao pé de Jesus, dizendo: Quem é o maior no reino dos céus?'),
('acf','mt',18,2,'E Jesus, chamando um menino, o pôs no meio deles,'),
('acf','mt',18,3,'E disse: Em verdade vos digo que, se não vos converterdes e não vos fizerdes como meninos, de modo algum entrareis no reino dos céus.'),
('acf','mt',18,4,'Portanto, aquele que se tornar humilde como este menino, esse é o maior no reino dos céus.'),
('acf','mt',18,5,'E qualquer que receber em meu nome um menino, tal como este, a mim me recebe.'),
('acf','mt',18,6,'Mas, qualquer que escandalizar um destes pequeninos, que crêem em mim, melhor lhe fora que se lhe pendurasse ao pescoço uma mó de azenha, e se submergisse na profundeza do mar.'),
('acf','mt',18,7,'Ai do mundo, por causa dos escândalos; porque é mister que venham escândalos, mas ai daquele homem por quem o escândalo vem!'),
('acf','mt',18,8,'Portanto, se a tua mão ou o teu pé te escandalizar, corta-o, e atira-o para longe de ti; melhor te é entrar na vida coxo, ou aleijado, do que, tendo duas mãos ou dois pés, seres lançado no fogo eterno.'),
('acf','mt',18,9,'E, se o teu olho te escandalizar, arranca-o, e atira-o para longe de ti; melhor te é entrar na vida com um só olho, do que, tendo dois olhos, seres lançado no fogo do inferno.'),
('acf','mt',18,10,'Vede, não desprezeis algum destes pequeninos, porque eu vos digo que os seus anjos nos céus sempre vêem a face de meu Pai que está nos céus.'),
('acf','mt',18,11,'Porque o Filho do homem veio salvar o que se tinha perdido.'),
('acf','mt',18,12,'Que vos parece? Se algum homem tiver cem ovelhas, e uma delas se desgarrar, não irá pelos montes, deixando as noventa e nove, em busca da que se desgarrou?'),
('acf','mt',18,13,'E, se porventura achá-la, em verdade vos digo que maior prazer tem por aquela do que pelas noventa e nove que se não desgarraram.'),
('acf','mt',18,14,'Assim, também, não é vontade de vosso Pai, que está nos céus, que um destes pequeninos se perca.'),
('acf','mt',18,15,'Ora, se teu irmão pecar contra ti, vai, e repreende-o entre ti e ele só; se te ouvir, ganhaste a teu irmão;'),
('acf','mt',18,16,'Mas, se não te ouvir, leva ainda contigo um ou dois, para que pela boca de duas ou três testemunhas toda a palavra seja confirmada.'),
('acf','mt',18,17,'E, se não as escutar, dize-o à igreja; e, se também não escutar a igreja, considera-o como um gentio e publicano.'),
('acf','mt',18,18,'Em verdade vos digo que tudo o que ligardes na terra será ligado no céu, e tudo o que desligardes na terra será desligado no céu.'),
('acf','mt',18,19,'Também vos digo que, se dois de vós concordarem na terra acerca de qualquer coisa que pedirem, isso lhes será feito por meu Pai, que está nos céus.'),
('acf','mt',18,20,'Porque, onde estiverem dois ou três reunidos em meu nome, aí estou eu no meio deles.'),
('acf','mt',18,21,'Então Pedro, aproximando-se dele, disse: Senhor, até quantas vezes pecará meu irmão contra mim, e eu lhe perdoarei? Até sete?'),
('acf','mt',18,22,'Jesus lhe disse: Não te digo que até sete; mas, até setenta vezes sete.'),
('acf','mt',18,23,'Por isso o reino dos céus pode comparar-se a um certo rei que quis fazer contas com os seus servos;'),
('acf','mt',18,24,'E, começando a fazer contas, foi-lhe apresentado um que lhe devia dez mil talentos;'),
('acf','mt',18,25,'E, não tendo ele com que pagar, o seu senhor mandou que ele, e sua mulher e seus filhos fossem vendidos, com tudo quanto tinha, para que a dívida se lhe pagasse.'),
('acf','mt',18,26,'Então aquele servo, prostrando-se, o reverenciava, dizendo: Senhor, sê generoso para comigo, e tudo te pagarei.'),
('acf','mt',18,27,'Então o Senhor daquele servo, movido de íntima compaixão, soltou-o e perdoou-lhe a dívida.'),
('acf','mt',18,28,'Saindo, porém, aquele servo, encontrou um dos seus conservos, que lhe devia cem dinheiros, e, lançando mão dele, sufocava-o, dizendo: Paga-me o que me deves.'),
('acf','mt',18,29,'Então o seu companheiro, prostrando-se a seus pés, rogava-lhe, dizendo: Sê generoso para comigo, e tudo te pagarei.'),
('acf','mt',18,30,'Ele, porém, não quis, antes foi encerrá-lo na prisão, até que pagasse a dívida.'),
('acf','mt',18,31,'Vendo, pois, os seus conservos o que acontecia, contristaram-se muito, e foram declarar ao seu senhor tudo o que se passara.'),
('acf','mt',18,32,'Então o seu senhor, chamando-o à sua presença, disse-lhe: Servo malvado, perdoei-te toda aquela dívida, porque me suplicaste.'),
('acf','mt',18,33,'Não devias tu, igualmente, ter compaixão do teu companheiro, como eu também tive misericórdia de ti?'),
('acf','mt',18,34,'E, indignado, o seu senhor o entregou aos atormentadores, até que pagasse tudo o que lhe devia.'),
('acf','mt',18,35,'Assim vos fará, também, meu Pai celestial, se do coração não perdoardes, cada um a seu irmão, as suas ofensas.'),
('acf','mt',19,1,'E aconteceu que, concluindo Jesus estes discursos, saiu da Galiléia, e dirigiu- se aos confins da Judéia, além do Jordão;'),
('acf','mt',19,2,'E seguiram-no grandes multidões, e curou-as ali.'),
('acf','mt',19,3,'Então chegaram ao pé dele os fariseus, tentando-o, e dizendo-lhe: É lícito ao homem repudiar sua mulher por qualquer motivo?'),
('acf','mt',19,4,'Ele, porém, respondendo, disse-lhes: Não tendes lido que aquele que os fez no princípio macho e fêmea os fez,'),
('acf','mt',19,5,'E disse: Portanto, deixará o homem pai e mãe, e se unirá a sua mulher, e serão dois numa só carne?'),
('acf','mt',19,6,'Assim não são mais dois, mas uma só carne. Portanto, o que Deus ajuntou não o separe o homem.'),
('acf','mt',19,7,'Disseram-lhe eles: Então, por que mandou Moisés dar-lhe carta de divórcio, e repudiá-la?'),
('acf','mt',19,8,'Disse-lhes ele: Moisés, por causa da dureza dos vossos corações, vos permitiu repudiar vossas mulheres; mas ao princípio não foi assim.'),
('acf','mt',19,9,'Eu vos digo, porém, que qualquer que repudiar sua mulher, não sendo por causa de fornicação, e casar com outra, comete adultério; e o que casar com a repudiada também comete adultério.'),
('acf','mt',19,10,'Disseram-lhe seus discípulos: Se assim é a condição do homem relativamente à mulher, não convém casar.'),
('acf','mt',19,11,'Ele, porém, lhes disse: Nem todos podem receber esta palavra, mas só aqueles a quem foi concedido.'),
('acf','mt',19,12,'Porque há eunucos que assim nasceram do ventre da mãe; e há eunucos que foram castrados pelos homens; e há eunucos que se castraram a si mesmos, por causa do reino dos céus. Quem pode receber isto, receba-o.'),
('acf','mt',19,13,'Trouxeram-lhe, então, alguns meninos, para que sobre eles pusesse as mãos, e orasse; mas os discípulos os repreendiam.'),
('acf','mt',19,14,'Jesus, porém, disse: Deixai os meninos, e não os estorveis de vir a mim; porque dos tais é o reino dos céus.'),
('acf','mt',19,15,'E, tendo-lhes imposto as mãos, partiu dali.'),
('acf','mt',19,16,'E eis que, aproximando-se dele um jovem, disse-lhe: Bom Mestre, que bem farei para conseguir a vida eterna?'),
('acf','mt',19,17,'E ele disse-lhe: Por que me chamas bom? Não há bom senão um só, que é Deus. Se queres, porém, entrar na vida, guarda os mandamentos.'),
('acf','mt',19,18,'Disse-lhe ele: Quais? E Jesus disse: Não matarás, não cometerás adultério, não furtarás, não dirás falso testemunho;'),
('acf','mt',19,19,'Honra teu pai e tua mãe, e amarás o teu próximo como a ti mesmo.'),
('acf','mt',19,20,'Disse-lhe o jovem: Tudo isso tenho guardado desde a minha mocidade; que me falta ainda?'),
('acf','mt',19,21,'Disse-lhe Jesus: Se queres ser perfeito, vai, vende tudo o que tens e dá-o aos pobres, e terás um tesouro no céu; e vem, e segue-me.'),
('acf','mt',19,22,'E o jovem, ouvindo esta palavra, retirou-se triste, porque possuía muitas propriedades.'),
('acf','mt',19,23,'Disse então Jesus aos seus discípulos: Em verdade vos digo que é difícil entrar um rico no reino dos céus.'),
('acf','mt',19,24,'E, outra vez vos digo que é mais fácil passar um camelo pelo fundo de uma agulha do que entrar um rico no reino de Deus.'),
('acf','mt',19,25,'Os seus discípulos, ouvindo isto, admiraram-se muito, dizendo: Quem poderá pois salvar-se?'),
('acf','mt',19,26,'E Jesus, olhando para eles, disse-lhes: Aos homens é isso impossível, mas a Deus tudo é possível.'),
('acf','mt',19,27,'Então Pedro, tomando a palavra, disse-lhe: Eis que nós deixamos tudo, e te seguimos; que receberemos?'),
('acf','mt',19,28,'E Jesus disse-lhes: Em verdade vos digo que vós, que me seguistes, quando, na regeneração, o Filho do homem se assentar no trono da sua glória, também vos assentareis sobre doze tronos, para julgar as doze tribos de Israel.'),
('acf','mt',19,29,'E todo aquele que tiver deixado casas, ou irmãos, ou irmãs, ou pai, ou mãe, ou mulher, ou filhos, ou terras, por amor de meu nome, receberá cem vezes tanto, e herdará a vida eterna.'),
('acf','mt',19,30,'Porém, muitos primeiros serão os derradeiros, e muitos derradeiros serão os primeiros.'),
('acf','mt',20,1,'Porque o reino dos céus é semelhante a um homem, pai de família, que saiu de madrugada a assalariar trabalhadores para a sua vinha.'),
('acf','mt',20,2,'E, ajustando com os trabalhadores a um dinheiro por dia, mandou-os para a sua vinha.'),
('acf','mt',20,3,'E, saindo perto da hora terceira, viu outros que estavam ociosos na praça,'),
('acf','mt',20,4,'E disse-lhes: Ide vós também para a vinha, e dar-vos-ei o que for justo. E eles foram.'),
('acf','mt',20,5,'Saindo outra vez, perto da hora sexta e nona, fez o mesmo.'),
('acf','mt',20,6,'E, saindo perto da hora undécima, encontrou outros que estavam ociosos, e perguntou- lhes: Por que estais ociosos todo o dia?'),
('acf','mt',20,7,'Disseram-lhe eles: Porque ninguém nos assalariou. Diz-lhes ele: Ide vós também para a vinha, e recebereis o que for justo.'),
('acf','mt',20,8,'E, aproximando-se a noite, diz o senhor da vinha ao seu mordomo: Chama os trabalhadores, e paga-lhes o jornal, começando pelos derradeiros, até aos primeiros.'),
('acf','mt',20,9,'E, chegando os que tinham ido perto da hora undécima, receberam um dinheiro cada um.'),
('acf','mt',20,10,'Vindo, porém, os primeiros, cuidaram que haviam de receber mais; mas do mesmo modo receberam um dinheiro cada um.'),
('acf','mt',20,11,'E, recebendo-o, murmuravam contra o pai de família,'),
('acf','mt',20,12,'Dizendo: Estes derradeiros trabalharam só uma hora, e tu os igualaste conosco, que suportamos a fadiga e a calma do dia.'),
('acf','mt',20,13,'Mas ele, respondendo, disse a um deles: Amigo, não te faço agravo; não ajustaste tu comigo um dinheiro?'),
('acf','mt',20,14,'Toma o que é teu, e retira-te; eu quero dar a este derradeiro tanto como a ti.'),
('acf','mt',20,15,'Ou não me é lícito fazer o que quiser do que é meu? Ou é mau o teu olho porque eu sou bom?'),
('acf','mt',20,16,'Assim os derradeiros serão primeiros, e os primeiros derradeiros; porque muitos são chamados, mas poucos escolhidos.'),
('acf','mt',20,17,'E, subindo Jesus a Jerusalém, chamou à parte os seus doze discípulos, e no caminho disse-lhes:'),
('acf','mt',20,18,'Eis que vamos para Jerusalém, e o Filho do homem será entregue aos príncipes dos sacerdotes, e aos escribas, e condená-lo-ão à morte.'),
('acf','mt',20,19,'E o entregarão aos gentios para que dele escarneçam, e o açoitem e crucifiquem, e ao terceiro dia ressuscitará.'),
('acf','mt',20,20,'Então se aproximou dele a mãe dos filhos de Zebedeu, com seus filhos, adorando-o, e fazendo-lhe um pedido.'),
('acf','mt',20,21,'E ele diz-lhe: Que queres? Ela respondeu: Dize que estes meus dois filhos se assentem, um à tua direita e outro à tua esquerda, no teu reino.'),
('acf','mt',20,22,'Jesus, porém, respondendo, disse: Não sabeis o que pedis. Podeis vós beber o cálice que eu hei de beber, e ser batizados com o batismo com que eu sou batizado? Dizem-lhe eles: Podemos.'),
('acf','mt',20,23,'E diz-lhes ele: Na verdade bebereis o meu cálice e sereis batizados com o batismo com que eu sou batizado, mas o assentar-se à minha direita ou à minha esquerda não me pertence dá-lo, mas é para aqueles para quem meu Pai o tem preparado.'),
('acf','mt',20,24,'E, quando os dez ouviram isto, indignaram-se contra os dois irmãos.'),
('acf','mt',20,25,'Então Jesus, chamando-os para junto de si, disse: Bem sabeis que pelos príncipes dos gentios são estes dominados, e que os grandes exercem autoridade sobre eles.'),
('acf','mt',20,26,'Não será assim entre vós; mas todo aquele que quiser entre vós fazer-se grande seja vosso serviçal;'),
('acf','mt',20,27,'E, qualquer que entre vós quiser ser o primeiro, seja vosso servo;'),
('acf','mt',20,28,'Bem como o Filho do homem não veio para ser servido, mas para servir, e para dar a sua vida em resgate de muitos.'),
('acf','mt',20,29,'E, saindo eles de Jericó, seguiu-o grande multidão.'),
('acf','mt',20,30,'E eis que dois cegos, assentados junto do caminho, ouvindo que Jesus passava, clamaram, dizendo: Senhor, Filho de Davi, tem misericórdia de nós!'),
('acf','mt',20,31,'E a multidão os repreendia, para que se calassem; eles, porém, cada vez clamavam mais, dizendo: Senhor, Filho de Davi, tem misericórdia de nós!'),
('acf','mt',20,32,'E Jesus, parando, chamou-os, e disse: Que quereis que vos faça?'),
('acf','mt',20,33,'Disseram-lhe eles: Senhor, que os nossos olhos sejam abertos.'),
('acf','mt',20,34,'Então Jesus, movido de íntima compaixão, tocou-lhes nos olhos, e logo seus olhos viram; e eles o seguiram.'),
('acf','mt',21,1,'E, quando se aproximaram de Jerusalém, e chegaram a Betfagé, ao Monte das Oliveiras, enviou, então, Jesus dois discípulos, dizendo-lhes:'),
('acf','mt',21,2,'Ide à aldeia que está defronte de vós, e logo encontrareis uma jumenta presa, e um jumentinho com ela; desprendei-a, e trazei-mos.'),
('acf','mt',21,3,'E, se alguém vos disser alguma coisa, direis que o Senhor os há de mister; e logo os enviará.'),
('acf','mt',21,4,'Ora, tudo isto aconteceu para que se cumprisse o que foi dito pelo profeta, que diz:'),
('acf','mt',21,5,'Dizei à filha de Sião: Eis que o teu Rei aí te vem,Manso, e assentado sobre uma jumenta,E sobre um jumentinho, filho de animal de carga.'),
('acf','mt',21,6,'E, indo os discípulos, e fazendo como Jesus lhes ordenara,'),
('acf','mt',21,7,'Trouxeram a jumenta e o jumentinho, e sobre eles puseram as suas vestes, e fizeram-no assentar em cima.'),
('acf','mt',21,8,'E muitíssima gente estendia as suas vestes pelo caminho, e outros cortavam ramos de árvores, e os espalhavam pelo caminho.'),
('acf','mt',21,9,'E a multidão que ia adiante, e a que seguia, clamava, dizendo: Hosana ao Filho de Davi; bendito o que vem em nome do Senhor. Hosana nas alturas!'),
('acf','mt',21,10,'E, entrando ele em Jerusalém, toda a cidade se alvoroçou, dizendo: Quem é este?'),
('acf','mt',21,11,'E a multidão dizia: Este é Jesus, o profeta de Nazaré da Galiléia.'),
('acf','mt',21,12,'E entrou Jesus no templo de Deus, e expulsou todos os que vendiam e compravam no templo, e derribou as mesas dos cambistas e as cadeiras dos que vendiam pombas;'),
('acf','mt',21,13,'E disse-lhes: Está escrito: A minha casa será chamada casa de oração; mas vós a tendes convertido em covil de ladrões.'),
('acf','mt',21,14,'E foram ter com ele no templo cegos e coxos, e curou-os.'),
('acf','mt',21,15,'Vendo, então, os principais dos sacerdotes e os escribas as maravilhas que fazia, e os meninos clamando no templo: Hosana ao Filho de Davi, indignaram-se,'),
('acf','mt',21,16,'E disseram-lhe: Ouves o que estes dizem? E Jesus lhes disse: Sim; nunca lestes: Pela boca dos meninos e das criancinhas de peito tiraste o perfeito louvor?'),
('acf','mt',21,17,'E, deixando-os, saiu da cidade para Betânia, e ali passou a noite.'),
('acf','mt',21,18,'E, de manhã, voltando para a cidade, teve fome;'),
('acf','mt',21,19,'E, avistando uma figueira perto do caminho, dirigiu-se a ela, e não achou nela senão folhas. E disse-lhe: Nunca mais nasça fruto de ti! E a figueira secou imediatamente.'),
('acf','mt',21,20,'E os discípulos, vendo isto, maravilharam-se, dizendo: Como secou imediatamente a figueira?'),
('acf','mt',21,21,'Jesus, porém, respondendo, disse-lhes: Em verdade vos digo que, se tiverdes fé e não duvidardes, não só fareis o que foi feito à figueira, mas até se a este monte disserdes: Ergue-te, e precipita-te no mar, assim será feito;'),
('acf','mt',21,22,'E, tudo o que pedirdes em oração, crendo, o recebereis.'),
('acf','mt',21,23,'E, chegando ao templo, acercaram-se dele, estando já ensinando, os príncipes dos sacerdotes e os anciãos do povo, dizendo: Com que autoridade fazes isto? e quem te deu tal autoridade?'),
('acf','mt',21,24,'E Jesus, respondendo, disse-lhes: Eu também vos perguntarei uma coisa; se ma disserdes, também eu vos direi com que autoridade faço isto.'),
('acf','mt',21,25,'O batismo de João, de onde era? Do céu, ou dos homens? E pensavam entre si, dizendo: Se dissermos: Do céu, ele nos dirá: Então por que não o crestes?'),
('acf','mt',21,26,'E, se dissermos: Dos homens, tememos o povo, porque todos consideram João como profeta.'),
('acf','mt',21,27,'E, respondendo a Jesus, disseram: Não sabemos. Ele disse-lhes: Nem eu vos digo com que autoridade faço isto.'),
('acf','mt',21,28,'Mas, que vos parece? Um homem tinha dois filhos, e, dirigindo-se ao primeiro, disse: Filho, vai trabalhar hoje na minha vinha.'),
('acf','mt',21,29,'Ele, porém, respondendo, disse: Não quero. Mas depois, arrependendo-se, foi.'),
('acf','mt',21,30,'E, dirigindo-se ao segundo, falou-lhe de igual modo; e, respondendo ele, disse: Eu vou, senhor; e não foi.'),
('acf','mt',21,31,'Qual dos dois fez a vontade do pai? Disseram-lhe eles: O primeiro. Disse-lhes Jesus: Em verdade vos digo que os publicanos e as meretrizes entram adiante de vós no reino de Deus.'),
('acf','mt',21,32,'Porque João veio a vós no caminho da justiça, e não o crestes, mas os publicanos e as meretrizes o creram; vós, porém, vendo isto, nem depois vos arrependestes para o crer.'),
('acf','mt',21,33,'Ouvi, ainda, outra parábola: Houve um homem, pai de família, que plantou uma vinha, e circundou-a de um valado, e construiu nela um lagar, e edificou uma torre, e arrendou-a a uns lavradores, e ausentou-se para longe.'),
('acf','mt',21,34,'E, chegando o tempo dos frutos, enviou os seus servos aos lavradores, para receber os seus frutos.'),
('acf','mt',21,35,'E os lavradores, apoderando-se dos servos, feriram um, mataram outro, e apedrejaram outro.'),
('acf','mt',21,36,'Depois enviou outros servos, em maior número do que os primeiros; e eles fizeram-lhes o mesmo.'),
('acf','mt',21,37,'E, por último, enviou-lhes seu filho, dizendo: Terão respeito a meu filho.'),
('acf','mt',21,38,'Mas os lavradores, vendo o filho, disseram entre si: Este é o herdeiro; vinde, matemo-lo, e apoderemo-nos da sua herança.'),
('acf','mt',21,39,'E, lançando mão dele, o arrastaram para fora da vinha, e o mataram.'),
('acf','mt',21,40,'Quando, pois, vier o senhor da vinha, que fará àqueles lavradores?'),
('acf','mt',21,41,'Dizem-lhe eles: Dará afrontosa morte aos maus, e arrendará a vinha a outros lavradores, que a seu tempo lhe dêem os frutos.'),
('acf','mt',21,42,'Diz-lhes Jesus: Nunca lestes nas Escrituras:A pedra, que os edificadores rejeitaram,essa foi posta por cabeça do ângulo;pelo Senhor foi feito isto,E é maravilhoso aos nossos olhos?'),
('acf','mt',21,43,'Portanto, eu vos digo que o reino de Deus vos será tirado, e será dado a uma nação que dê os seus frutos.'),
('acf','mt',21,44,'E, quem cair sobre esta pedra, despedaçar-se-á; e aquele sobre quem ela cair ficará reduzido a pó.'),
('acf','mt',21,45,'E os príncipes dos sacerdotes e os fariseus, ouvindo estas palavras, entenderam que falava deles;'),
('acf','mt',21,46,'E, pretendendo prendê-lo, recearam o povo, porquanto o tinham por profeta.'),
('acf','mt',22,1,'Então Jesus, tomando a palavra, tornou a falar-lhes em parábolas, dizendo:'),
('acf','mt',22,2,'O reino dos céus é semelhante a um certo rei que celebrou as bodas de seu filho;'),
('acf','mt',22,3,'E enviou os seus servos a chamar os convidados para as bodas, e estes não quiseram vir.'),
('acf','mt',22,4,'Depois, enviou outros servos, dizendo: Dizei aos convidados: Eis que tenho o meu jantar preparado, os meus bois e cevados já mortos, e tudo já pronto; vinde às bodas.'),
('acf','mt',22,5,'Eles, porém, não fazendo caso, foram, um para o seu campo, outro para o seu negócio;'),
('acf','mt',22,6,'E os outros, apoderando-se dos servos, os ultrajaram e mataram.'),
('acf','mt',22,7,'E o rei, tendo notícia disto, encolerizou-se e, enviando os seus exércitos, destruiu aqueles homicidas, e incendiou a sua cidade.'),
('acf','mt',22,8,'Então diz aos servos: As bodas, na verdade, estão preparadas, mas os convidados não eram dignos.'),
('acf','mt',22,9,'Ide, pois, às saídas dos caminhos, e convidai para as bodas a todos os que encontrardes.'),
('acf','mt',22,10,'E os servos, saindo pelos caminhos, ajuntaram todos quantos encontraram, tanto maus como bons; e a festa nupcial foi cheia de convidados.'),
('acf','mt',22,11,'E o rei, entrando para ver os convidados, viu ali um homem que não estava trajado com veste de núpcias.'),
('acf','mt',22,12,'E disse-lhe: Amigo, como entraste aqui, não tendo veste nupcial? E ele emudeceu.'),
('acf','mt',22,13,'Disse, então, o rei aos servos: Amarrai-o de pés e mãos, levai-o, e lançai-o nas trevas exteriores; ali haverá pranto e ranger de dentes.'),
('acf','mt',22,14,'Porque muitos são chamados, mas poucos escolhidos.'),
('acf','mt',22,15,'Então, retirando-se os fariseus, consultaram entre si como o surpreenderiam nalguma palavra;'),
('acf','mt',22,16,'E enviaram-lhe os seus discípulos, com os herodianos, dizendo: Mestre, bem sabemos que és verdadeiro, e ensinas o caminho de Deus segundo a verdade, e de ninguém se te dá, porque não olhas a aparência dos homens.'),
('acf','mt',22,17,'Dize-nos, pois, que te parece? É lícito pagar o tributo a César, ou não?'),
('acf','mt',22,18,'Jesus, porém, conhecendo a sua malícia, disse: Por que me experimentais, hipócritas?'),
('acf','mt',22,19,'Mostrai-me a moeda do tributo. E eles lhe apresentaram um dinheiro.'),
('acf','mt',22,20,'E ele diz-lhes: De quem é esta efígie e esta inscrição?'),
('acf','mt',22,21,'Dizem-lhe eles: De César. Então ele lhes disse: Dai pois a César o que é de César, e a Deus o que é de Deus.'),
('acf','mt',22,22,'E eles, ouvindo isto, maravilharam-se, e, deixando-o, se retiraram.'),
('acf','mt',22,23,'No mesmo dia chegaram junto dele os saduceus, que dizem não haver ressurreição, e o interrogaram,'),
('acf','mt',22,24,'Dizendo: Mestre, Moisés disse: Se morrer alguém, não tendo filhos, casará o seu irmão com a mulher dele, e suscitará descendência a seu irmão.'),
('acf','mt',22,25,'Ora, houve entre nós sete irmãos; e o primeiro, tendo casado, morreu e, não tendo descendência, deixou sua mulher a seu irmão.'),
('acf','mt',22,26,'Da mesma sorte o segundo, e o terceiro, até ao sétimo;'),
('acf','mt',22,27,'Por fim, depois de todos, morreu também a mulher.'),
('acf','mt',22,28,'Portanto, na ressurreição, de qual dos sete será a mulher, visto que todos a possuíram?'),
('acf','mt',22,29,'Jesus, porém, respondendo, disse-lhes: Errais, não conhecendo as Escrituras, nem o poder de Deus.'),
('acf','mt',22,30,'Porque na ressurreição nem casam nem são dados em casamento; mas serão como os anjos de Deus no céu.'),
('acf','mt',22,31,'E, acerca da ressurreição dos mortos, não tendes lido o que Deus vos declarou, dizendo:'),
('acf','mt',22,32,'Eu sou o Deus de Abraão, o Deus de Isaque, e o Deus de Jacó? Ora, Deus não é Deus dos mortos, mas dos vivos.'),
('acf','mt',22,33,'E, as turbas, ouvindo isto, ficaram maravilhadas da sua doutrina.'),
('acf','mt',22,34,'E os fariseus, ouvindo que ele fizera emudecer os saduceus, reuniram-se no mesmo lugar.'),
('acf','mt',22,35,'E um deles, doutor da lei, interrogou-o para o experimentar, dizendo:'),
('acf','mt',22,36,'Mestre, qual é o grande mandamento na lei?'),
('acf','mt',22,37,'E Jesus disse-lhe: Amarás o Senhor teu Deus de todo o teu coração, e de toda a tua alma, e de todo o teu pensamento.'),
('acf','mt',22,38,'Este é o primeiro e grande mandamento.'),
('acf','mt',22,39,'E o segundo, semelhante a este, é: Amarás o teu próximo como a ti mesmo.'),
('acf','mt',22,40,'Destes dois mandamentos dependem toda a lei e os profetas.'),
('acf','mt',22,41,'E, estando reunidos os fariseus, interrogou-os Jesus,'),
('acf','mt',22,42,'Dizendo: Que pensais vós do Cristo? De quem é filho? Eles disseram-lhe: De Davi.'),
('acf','mt',22,43,'Disse-lhes ele: Como é então que Davi, em espírito, lhe chama Senhor, dizendo:'),
('acf','mt',22,44,'Disse o Senhor ao meu Senhor:Assenta-te à minha direita,Até que eu ponha os teus inimigos por escabelo de teus pés?'),
('acf','mt',22,45,'Se Davi, pois, lhe chama Senhor, como é seu filho?'),
('acf','mt',22,46,'E ninguém podia responder-lhe uma palavra; nem desde aquele dia ousou mais alguém interrogá-lo.'),
('acf','mt',23,1,'Então falou Jesus à multidão, e aos seus discípulos,'),
('acf','mt',23,2,'Dizendo: Na cadeira de Moisés estão assentados os escribas e fariseus.'),
('acf','mt',23,3,'Todas as coisas, pois, que vos disserem que observeis, observai-as e fazei-as; mas não procedais em conformidade com as suas obras, porque dizem e não fazem;'),
('acf','mt',23,4,'Pois atam fardos pesados e difíceis de suportar, e os põem aos ombros dos homens; eles, porém, nem com seu dedo querem movê-los;'),
('acf','mt',23,5,'E fazem todas as obras a fim de serem vistos pelos homens; pois trazem largos filactérios, e alargam as franjas das suas vestes,'),
('acf','mt',23,6,'E amam os primeiros lugares nas ceias e as primeiras cadeiras nas sinagogas,'),
('acf','mt',23,7,'E as saudações nas praças, e o serem chamados pelos homens; Rabi, Rabi.'),
('acf','mt',23,8,'Vós, porém, não queirais ser chamados Rabi, porque um só é o vosso Mestre, a saber, o Cristo, e todos vós sois irmãos.'),
('acf','mt',23,9,'E a ninguém na terra chameis vosso pai, porque um só é o vosso Pai, o qual está nos céus.'),
('acf','mt',23,10,'Nem vos chameis mestres, porque um só é o vosso Mestre, que é o Cristo.'),
('acf','mt',23,11,'O maior dentre vós será vosso servo.'),
('acf','mt',23,12,'E o que a si mesmo se exaltar será humilhado; e o que a si mesmo se humilhar será exaltado.'),
('acf','mt',23,13,'Mas ai de vós, escribas e fariseus, hipócritas! pois que fechais aos homens o reino dos céus; e nem vós entrais nem deixais entrar aos que estão entrando.'),
('acf','mt',23,14,'Ai de vós, escribas e fariseus, hipócritas! pois que devorais as casas das viúvas, sob pretexto de prolongadas orações; por isso sofrereis mais rigoroso juízo.'),
('acf','mt',23,15,'Ai de vós, escribas e fariseus, hipócritas! pois que percorreis o mar e a terra para fazer um prosélito; e, depois de o terdes feito, o fazeis filho do inferno duas vezes mais do que vós.'),
('acf','mt',23,16,'Ai de vós, condutores cegos! pois que dizeis: Qualquer que jurar pelo templo, isso nada é; mas o que jurar pelo ouro do templo, esse é devedor.'),
('acf','mt',23,17,'Insensatos e cegos! Pois qual é maior: o ouro, ou o templo, que santifica o ouro?'),
('acf','mt',23,18,'E aquele que jurar pelo altar isso nada é; mas aquele que jurar pela oferta que está sobre o altar, esse é devedor.'),
('acf','mt',23,19,'Insensatos e cegos! Pois qual é maior: a oferta, ou o altar, que santifica a oferta?'),
('acf','mt',23,20,'Portanto, o que jurar pelo altar, jura por ele e por tudo o que sobre ele está;'),
('acf','mt',23,21,'E, o que jurar pelo templo, jura por ele e por aquele que nele habita;'),
('acf','mt',23,22,'E, o que jurar pelo céu, jura pelo trono de Deus e por aquele que está assentado nele.'),
('acf','mt',23,23,'Ai de vós, escribas e fariseus, hipócritas! pois que dizimais a hortelã, o endro e o cominho, e desprezais o mais importante da lei, o juízo, a misericórdia e a fé; deveis, porém, fazer estas coisas, e não omitir aquelas.'),
('acf','mt',23,24,'Condutores cegos! que coais um mosquito e engulis um camelo.'),
('acf','mt',23,25,'Ai de vós, escribas e fariseus, hipócritas! pois que limpais o exterior do copo e do prato, mas o interior está cheio de rapina e de intemperança.'),
('acf','mt',23,26,'Fariseu cego! limpa primeiro o interior do copo e do prato, para que também o exterior fique limpo.'),
('acf','mt',23,27,'Ai de vós, escribas e fariseus, hipócritas! pois que sois semelhantes aos sepulcros caiados, que por fora realmente parecem formosos, mas interiormente estão cheios de ossos de mortos e de toda a imundícia.'),
('acf','mt',23,28,'Assim também vós exteriormente pareceis justos aos homens, mas interiormente estais cheios de hipocrisia e de iniqüidade.'),
('acf','mt',23,29,'Ai de vós, escribas e fariseus, hipócritas! pois que edificais os sepulcros dos profetas e adornais os monumentos dos justos,'),
('acf','mt',23,30,'E dizeis: Se existíssemos no tempo de nossos pais, nunca nos associaríamos com eles para derramar o sangue dos profetas.'),
('acf','mt',23,31,'Assim, vós mesmos testificais que sois filhos dos que mataram os profetas.'),
('acf','mt',23,32,'Enchei vós, pois, a medida de vossos pais.'),
('acf','mt',23,33,'Serpentes, raça de víboras! como escapareis da condenação do inferno?'),
('acf','mt',23,34,'Portanto, eis que eu vos envio profetas, sábios e escribas; a uns deles matareis e crucificareis; e a outros deles açoitareis nas vossas sinagogas e os perseguireis de cidade em cidade;'),
('acf','mt',23,35,'Para que sobre vós caia todo o sangue justo, que foi derramado sobre a terra, desde o sangue de Abel, o justo, até ao sangue de Zacarias, filho de Baraquias, que matastes entre o santuário e o altar.'),
('acf','mt',23,36,'Em verdade vos digo que todas estas coisas hão de vir sobre esta geração.'),
('acf','mt',23,37,'Jerusalém, Jerusalém, que matas os profetas, e apedrejas os que te são enviados! quantas vezes quis eu ajuntar os teus filhos, como a galinha ajunta os seus pintos debaixo das asas, e tu não quiseste!'),
('acf','mt',23,38,'Eis que a vossa casa vai ficar-vos deserta;'),
('acf','mt',23,39,'Porque eu vos digo que desde agora me não vereis mais, até que digais: Bendito o que vem em nome do Senhor.'),
('acf','mt',24,1,'E, quando Jesus ia saindo do templo, aproximaram-se dele os seus discípulos para lhe mostrarem a estrutura do templo.'),
('acf','mt',24,2,'Jesus, porém, lhes disse: Não vedes tudo isto? Em verdade vos digo que não ficará aqui pedra sobre pedra que não seja derrubada.'),
('acf','mt',24,3,'E, estando assentado no Monte das Oliveiras, chegaram-se a ele os seus discípulos em particular, dizendo: Dize-nos, quando serão essas coisas, e que sinal haverá da tua vinda e do fim do mundo?'),
('acf','mt',24,4,'E Jesus, respondendo, disse-lhes: Acautelai-vos, que ninguém vos engane;'),
('acf','mt',24,5,'Porque muitos virão em meu nome, dizendo: Eu sou o Cristo; e enganarão a muitos.'),
('acf','mt',24,6,'E ouvireis de guerras e de rumores de guerras; olhai, não vos assusteis, porque é mister que isso tudo aconteça, mas ainda não é o fim.'),
('acf','mt',24,7,'Porquanto se levantará nação contra nação, e reino contra reino, e haverá fomes, e pestes, e terremotos, em vários lugares.'),
('acf','mt',24,8,'Mas todas estas coisas são o princípio de dores.'),
('acf','mt',24,9,'Então vos hão de entregar para serdes atormentados, e matar-vosão; e sereis odiados de todas as nações por causa do meu nome.'),
('acf','mt',24,10,'Nesse tempo muitos serão escandalizados, e trair-se-ão uns aos outros, e uns aos outros se odiarào.'),
('acf','mt',24,11,'E surgirão muitos falsos profetas, e enganarão a muitos.'),
('acf','mt',24,12,'E, por se multiplicar a iniqüidade, o amor de muitos esfriará.'),
('acf','mt',24,13,'Mas aquele que perseverar até ao fim, esse será salvo.'),
('acf','mt',24,14,'E este evangelho do reino será pregado em todo o mundo, em testemunho a todas as nações, e então virá o fim.'),
('acf','mt',24,15,'Quando, pois, virdes que a abominação da desolação, de que falou o profeta Daniel, está no lugar santo; quem lê, entenda;'),
('acf','mt',24,16,'Então, os que estiverem na Judéia, fujam para os montes;'),
('acf','mt',24,17,'E quem estiver sobre o telhado não desça a tirar alguma coisa de sua casa;'),
('acf','mt',24,18,'E quem estiver no campo não volte atrás a buscar as suas vestes.'),
('acf','mt',24,19,'Mas ai das grávidas e das que amamentarem naqueles dias!'),
('acf','mt',24,20,'E orai para que a vossa fuga não aconteça no inverno nem no sábado;'),
('acf','mt',24,21,'Porque haverá então grande aflição, como nunca houve desde o princípio do mundo até agora, nem tampouco há de haver.'),
('acf','mt',24,22,'E, se aqueles dias não fossem abreviados, nenhuma carne se salvaria; mas por causa dos escolhidos serão abreviados aqueles dias.'),
('acf','mt',24,23,'Então, se alguém vos disser: Eis que o Cristo está aqui, ou ali, não lhe deis crédito;'),
('acf','mt',24,24,'Porque surgirão falsos cristos e falsos profetas, e farão tão grandes sinais e prodígios que, se possível fora, enganariam até os escolhidos.'),
('acf','mt',24,25,'Eis que eu vo-lo tenho predito.'),
('acf','mt',24,26,'Portanto, se vos disserem: Eis que ele está no deserto, não saiais. Eis que ele está no interior da casa; não acrediteis.'),
('acf','mt',24,27,'Porque, assim como o relâmpago sai do oriente e se mostra até ao ocidente, assim será também a vinda do Filho do homem.'),
('acf','mt',24,28,'Pois onde estiver o cadáver, aí se ajuntarão as águias.'),
('acf','mt',24,29,'E, logo depois da aflição daqueles dias, o sol escurecerá, e a lua não dará a sua luz, e as estrelas cairão do céu, e as potências dos céus serão abaladas.'),
('acf','mt',24,30,'Então aparecerá no céu o sinal do Filho do homem; e todas as tribos da terra se lamentarão, e verão o Filho do homem, vindo sobre as nuvens do céu, com poder e grande glória.'),
('acf','mt',24,31,'E ele enviará os seus anjos com rijo clamor de trombeta, os quais ajuntarão os seus escolhidos desde os quatro ventos, de uma à outra extremidade dos céus.'),
('acf','mt',24,32,'Aprendei, pois, esta parábola da figueira: Quando já os seus ramos se tornam tenros e brotam folhas, sabeis que está próximo o verão.'),
('acf','mt',24,33,'Igualmente, quando virdes todas estas coisas, sabei que ele está próximo, às portas.'),
('acf','mt',24,34,'Em verdade vos digo que não passará esta geração sem que todas estas coisas aconteçam.'),
('acf','mt',24,35,'O céu e a terra passarão, mas as minhas palavras não hão de passar.'),
('acf','mt',24,36,'Mas daquele dia e hora ninguém sabe, nem os anjos do céu, mas unicamente meu Pai.'),
('acf','mt',24,37,'E, como foi nos dias de Noé, assim será também a vinda do Filho do homem.'),
('acf','mt',24,38,'Porquanto, assim como, nos dias anteriores ao dilúvio, comiam, bebiam, casavam e davam-se em casamento, até ao dia em que Noé entrou na arca,'),
('acf','mt',24,39,'E não o perceberam, até que veio o dilúvio, e os levou a todos, assim será também a vinda do Filho do homem.'),
('acf','mt',24,40,'Então, estando dois no campo, será levado um, e deixado o outro;'),
('acf','mt',24,41,'Estando duas moendo no moinho, será levada uma, e deixada outra.'),
('acf','mt',24,42,'Vigiai, pois, porque não sabeis a que hora há de vir o vosso Senhor.'),
('acf','mt',24,43,'Mas considerai isto: se o pai de família soubesse a que vigília da noite havia de vir o ladrão, vigiaria e não deixaria minar a sua casa.'),
('acf','mt',24,44,'Por isso, estai vós apercebidos também; porque o Filho do homem há de vir à hora em que não penseis.'),
('acf','mt',24,45,'Quem é, pois, o servo fiel e prudente, que o seu senhor constituiu sobre a sua casa, para dar o sustento a seu tempo?'),
('acf','mt',24,46,'Bem-aventurado aquele servo que o seu senhor, quando vier, achar servindo assim.'),
('acf','mt',24,47,'Em verdade vos digo que o porá sobre todos os seus bens.'),
('acf','mt',24,48,'Mas se aquele mau servo disser no seu coração: O meu senhor tarde virá;'),
('acf','mt',24,49,'E começar a espancar os seus conservos, e a comer e a beber com os ébrios,'),
('acf','mt',24,50,'Virá o senhor daquele servo num dia em que o não espera, e à hora em que ele não sabe,'),
('acf','mt',24,51,'E separá-lo-á, e destinará a sua parte com os hipócritas; ali haverá pranto e ranger de dentes.'),
('acf','mt',25,1,'Então o reino dos céus será semelhante a dez virgens que, tomando as suas lâmpadas, saíram ao encontro do esposo.'),
('acf','mt',25,2,'E cinco delas eram prudentes, e cinco loucas.'),
('acf','mt',25,3,'As loucas, tomando as suas lâmpadas, não levaram azeite consigo.'),
('acf','mt',25,4,'Mas as prudentes levaram azeite em suas vasilhas, com as suas lâmpadas.'),
('acf','mt',25,5,'E, tardando o esposo, tosquenejaram todas, e adormeceram.'),
('acf','mt',25,6,'Mas à meia-noite ouviu-se um clamor: Aí vem o esposo, saí-lhe ao encontro.'),
('acf','mt',25,7,'Então todas aquelas virgens se levantaram, e prepararam as suas lâmpadas.'),
('acf','mt',25,8,'E as loucas disseram às prudentes: Dai-nos do vosso azeite, porque as nossas lâmpadas se apagam.'),
('acf','mt',25,9,'Mas as prudentes responderam, dizendo: Não seja caso que nos falte a nós e a vós, ide antes aos que o vendem, e comprai-o para vós.'),
('acf','mt',25,10,'E, tendo elas ido comprá-lo, chegou o esposo, e as que estavam preparadas entraram com ele para as bodas, e fechou-se a porta.'),
('acf','mt',25,11,'E depois chegaram também as outras virgens, dizendo: Senhor, Senhor, abre-nos.'),
('acf','mt',25,12,'E ele, respondendo, disse: Em verdade vos digo que vos não conheço.'),
('acf','mt',25,13,'Vigiai, pois, porque não sabeis o dia nem a hora em que o Filho do homem há de vir.'),
('acf','mt',25,14,'Porque isto é também como um homem que, partindo para fora da terra, chamou os seus servos, e entregou-lhes os seus bens.'),
('acf','mt',25,15,'E a um deu cinco talentos, e a outro dois, e a outro um, a cada um segundo a sua capacidade, e ausentou-se logo para longe.'),
('acf','mt',25,16,'E, tendo ele partido, o que recebera cinco talentos negociou com eles, e granjeou outros cinco talentos.'),
('acf','mt',25,17,'Da mesma sorte, o que recebera dois, granjeou também outros dois.'),
('acf','mt',25,18,'Mas o que recebera um, foi e cavou na terra e escondeu o dinheiro do seu senhor.'),
('acf','mt',25,19,'E muito tempo depois veio o senhor daqueles servos, e fez contas com eles.'),
('acf','mt',25,20,'Então aproximou-se o que recebera cinco talentos, e trouxe-lhe outros cinco talentos, dizendo: Senhor, entregaste-me cinco talentos; eis aqui outros cinco talentos que granjeei com eles.'),
('acf','mt',25,21,'E o seu senhor lhe disse: Bem está, servo bom e fiel. Sobre o pouco foste fiel, sobre muito te colocarei; entra no gozo do teu senhor.'),
('acf','mt',25,22,'E, chegando também o que tinha recebido dois talentos, disse: Senhor, entregaste-me dois talentos; eis que com eles granjeei outros dois talentos.'),
('acf','mt',25,23,'Disse-lhe o seu senhor: Bem está, bom e fiel servo. Sobre o pouco foste fiel, sobre muito te colocarei; entra no gozo do teu senhor.'),
('acf','mt',25,24,'Mas, chegando também o que recebera um talento, disse: Senhor, eu conhecia-te, que és um homem duro, que ceifas onde não semeaste e ajuntas onde não espalhaste;'),
('acf','mt',25,25,'E, atemorizado, escondi na terra o teu talento; aqui tens o que é teu.'),
('acf','mt',25,26,'Respondendo, porém, o seu senhor, disse-lhe: Mau e negligente servo; sabias que ceifo onde não semeei e ajunto onde não espalhei?'),
('acf','mt',25,27,'Devias então ter dado o meu dinheiro aos banqueiros e, quando eu viesse, receberia o meu com os juros.'),
('acf','mt',25,28,'Tirai-lhe pois o talento, e dai-o ao que tem os dez talentos.'),
('acf','mt',25,29,'Porque a qualquer que tiver será dado, e terá em abundância; mas ao que não tiver até o que tem ser-lhe-á tirado.'),
('acf','mt',25,30,'Lançai, pois, o servo inútil nas trevas exteriores; ali haverá pranto e ranger de dentes.'),
('acf','mt',25,31,'E quando o Filho do homem vier em sua glória, e todos os santos anjos com ele, então se assentará no trono da sua glória;'),
('acf','mt',25,32,'E todas as nações serão reunidas diante dele, e apartará uns dos outros, como o pastor aparta dos bodes as ovelhas;'),
('acf','mt',25,33,'E porá as ovelhas à sua direita, mas os bodes à esquerda.'),
('acf','mt',25,34,'Então dirá o Rei aos que estiverem à sua direita: Vinde, benditos de meu Pai, possuí por herança o reino que vos está preparado desde a fundação do mundo;'),
('acf','mt',25,35,'Porque tive fome, e destes-me de comer; tive sede, e destes-me de beber; era estrangeiro, e hospedastes-me;'),
('acf','mt',25,36,'Estava nu, e vestistes-me; adoeci, e visitastes-me; estive na prisão, e foste me ver.'),
('acf','mt',25,37,'Então os justos lhe responderão, dizendo: Senhor, quando te vimos com fome, e te demos de comer? ou com sede, e te demos de beber?'),
('acf','mt',25,38,'E quando te vimos estrangeiro, e te hospedamos? ou nu, e te vestimos?'),
('acf','mt',25,39,'E quando te vimos enfermo, ou na prisão, e fomos ver-te?'),
('acf','mt',25,40,'E, respondendo o Rei, lhes dirá: Em verdade vos digo que quando o fizestes a um destes meus pequeninos irmãos, a mim o fizestes.'),
('acf','mt',25,41,'Então dirá também aos que estiverem à sua esquerda: Apartai-vos de mim, malditos, para o fogo eterno, preparado para o diabo e seus anjos;'),
('acf','mt',25,42,'Porque tive fome, e não me destes de comer; tive sede, e não me destes de beber;'),
('acf','mt',25,43,'Sendo estrangeiro, não me recolhestes; estando nu, não me vestistes; e enfermo, e na prisão, não me visitastes.'),
('acf','mt',25,44,'Então eles também lhe responderão, dizendo: Senhor, quando te vimos com fome, ou com sede, ou estrangeiro, ou nu, ou enfermo, ou na prisão, e não te servimos?'),
('acf','mt',25,45,'Então lhes responderá, dizendo: Em verdade vos digo que, quando a um destes pequeninos o não fizestes, não o fizestes a mim.'),
('acf','mt',25,46,'E irão estes para o tormento eterno, mas os justos para a vida eterna.'),
('acf','mt',26,1,'E aconteceu que, quando Jesus concluiu todos estes discursos, disse aos seus discípulos:'),
('acf','mt',26,2,'Bem sabeis que daqui a dois dias é a páscoa; e o Filho do homem será entregue para ser crucificado.'),
('acf','mt',26,3,'Depois os príncipes dos sacerdotes, e os escribas, e os anciãos do povo reuniram-se na sala do sumo sacerdote, o qual se chamava Caifás.'),
('acf','mt',26,4,'E consultaram-se mutuamente para prenderem Jesus com dolo e o matarem.'),
('acf','mt',26,5,'Mas diziam: Não durante a festa, para que não haja alvoroço entre o povo.'),
('acf','mt',26,6,'E, estando Jesus em Betânia, em casa de Simão, o leproso,'),
('acf','mt',26,7,'Aproximou-se dele uma mulher com um vaso de alabastro, com ungüento de grande valor, e derramou-lho sobre a cabeça, quando ele estava assentado à mesa.'),
('acf','mt',26,8,'E os seus discípulos, vendo isto, indignaram-se, dizendo: Por que é este desperdício?'),
('acf','mt',26,9,'Pois este ungüento podia vender-se por grande preço, e dar-se o dinheiro aos pobres.'),
('acf','mt',26,10,'Jesus, porém, conhecendo isto, disse-lhes: Por que afligis esta mulher? pois praticou uma boa ação para comigo.'),
('acf','mt',26,11,'Porquanto sempre tendes convosco os pobres, mas a mim não me haveis de ter sempre.'),
('acf','mt',26,12,'Ora, derramando ela este ungüento sobre o meu corpo, fê-lo preparando-me para o meu sepultamento.'),
('acf','mt',26,13,'Em verdade vos digo que, onde quer que este evangelho for pregado em todo o mundo, também será referido o que ela fez, para memória sua.'),
('acf','mt',26,14,'Então um dos doze, chamado Judas Iscariotes, foi ter com os príncipes dos sacerdotes,'),
('acf','mt',26,15,'E disse: Que me quereis dar, e eu vo-lo entregarei? E eles lhe pesaram trinta moedas de prata,'),
('acf','mt',26,16,'E desde então buscava oportunidade para o entregar.'),
('acf','mt',26,17,'E, no primeiro dia da festa dos pães ázimos, chegaram os discípulos junto de Jesus, dizendo: Onde queres que façamos os preparativos para comeres a páscoa?'),
('acf','mt',26,18,'E ele disse: Ide à cidade, a um certo homem, e dizei-lhe: O Mestre diz: O meu tempo está próximo; em tua casa celebrarei a páscoa com os meus discípulos.'),
('acf','mt',26,19,'E os discípulos fizeram como Jesus lhes ordenara, e prepararam a páscoa.'),
('acf','mt',26,20,'E, chegada a tarde, assentou-se à mesa com os doze.'),
('acf','mt',26,21,'E, comendo eles, disse: Em verdade vos digo que um de vós me há de trair.'),
('acf','mt',26,22,'E eles, entristecendo-se muito, começaram cada um a dizer-lhe: Porventura sou eu, Senhor?'),
('acf','mt',26,23,'E ele, respondendo, disse: O que põe comigo a mão no prato, esse me há de trair.'),
('acf','mt',26,24,'Em verdade o Filho do homem vai, como acerca dele está escrito, mas ai daquele homem por quem o Filho do homem é traído! Bom seria para esse homem se não houvera nascido.'),
('acf','mt',26,25,'E, respondendo Judas, o que o traía, disse: Porventura sou eu, Rabi? Ele disse: Tu o disseste.'),
('acf','mt',26,26,'E, quando comiam, Jesus tomou o pão, e abençoando-o, o partiu, e o deu aos discípulos, e disse: Tomai, comei, isto é o meu corpo.'),
('acf','mt',26,27,'E, tomando o cálice, e dando graças, deu-lho, dizendo: Bebei dele todos;'),
('acf','mt',26,28,'Porque isto é o meu sangue, o sangue do novo testamento, que é derramado por muitos, para remissão dos pecados.'),
('acf','mt',26,29,'E digo-vos que, desde agora, não beberei deste fruto da vide, até aquele dia em que o beba novo convosco no reino de meu Pai.'),
('acf','mt',26,30,'E, tendo cantado o hino, saíram para o Monte das Oliveiras.'),
('acf','mt',26,31,'Então Jesus lhes disse: Todos vós esta noite vos escandalizareis em mim; porque está escrito: Ferirei o pastor, e as ovelhas do rebanho se dispersarão.'),
('acf','mt',26,32,'Mas, depois de eu ressuscitar, irei adiante de vós para a Galiléia.'),
('acf','mt',26,33,'Mas Pedro, respondendo, disse-lhe: Ainda que todos se escandalizem em ti, eu nunca me escandalizarei.'),
('acf','mt',26,34,'Disse-lhe Jesus: Em verdade te digo que, nesta mesma noite, antes que o galo cante, três vezes me negarás.'),
('acf','mt',26,35,'Disse-lhe Pedro: Ainda que me seja mister morrer contigo, não te negarei. E todos os discípulos disseram o mesmo.'),
('acf','mt',26,36,'Então chegou Jesus com eles a um lugar chamado Getsêmani, e disse a seus discípulos: Assentai-vos aqui, enquanto vou além orar.'),
('acf','mt',26,37,'E, levando consigo Pedro e os dois filhos de Zebedeu, começou a entristecer-se e a angustiar-se muito.'),
('acf','mt',26,38,'Então lhes disse: A minha alma está cheia de tristeza até a morte; ficai aqui, e velai comigo.'),
('acf','mt',26,39,'E, indo um pouco mais para diante, prostrou-se sobre o seu rosto, orando e dizendo: Meu Pai, se é possível, passe de mim este cálice; todavia, não seja como eu quero, mas como tu queres.'),
('acf','mt',26,40,'E, voltando para os seus discípulos, achou-os adormecidos; e disse a Pedro: Então nem uma hora pudeste velar comigo?'),
('acf','mt',26,41,'Vigiai e orai, para que não entreis em tentação; na verdade, o espírito está pronto, mas a carne é fraca.'),
('acf','mt',26,42,'E, indo segunda vez, orou, dizendo: Pai meu, se este cálice não pode passar de mim sem eu o beber, faça-se a tua vontade.'),
('acf','mt',26,43,'E, voltando, achou-os outra vez adormecidos; porque os seus olhos estavam pesados.'),
('acf','mt',26,44,'E, deixando-os de novo, foi orar pela terceira vez, dizendo as mesmas palavras.'),
('acf','mt',26,45,'Então chegou junto dos seus discípulos, e disse-lhes: Dormi agora, e repousai; eis que é chegada a hora, e o Filho do homem será entregue nas mãos dos pecadores.'),
('acf','mt',26,46,'Levantai-vos, partamos; eis que é chegado o que me trai.'),
('acf','mt',26,47,'E, estando ele ainda a falar, eis que chegou Judas, um dos doze, e com ele grande multidão com espadas e varapaus, enviada pelos príncipes dos sacerdotes e pelos anciãos do povo.'),
('acf','mt',26,48,'E o que o traía tinha-lhes dado um sinal, dizendo: O que eu beijar é esse; prendei-o.'),
('acf','mt',26,49,'E logo, aproximando-se de Jesus, disse: Eu te saúdo, Rabi; e beijou-o.'),
('acf','mt',26,50,'Jesus, porém, lhe disse: Amigo, a que vieste? Então, aproximando-se eles, lançaram mão de Jesus, e o prenderam.'),
('acf','mt',26,51,'E eis que um dos que estavam com Jesus, estendendo a mão, puxou da espada e, ferindo o servo do sumo sacerdote, cortou-lhe uma orelha.'),
('acf','mt',26,52,'Então Jesus disse-lhe: Embainha a tua espada; porque todos os que lançarem mão da espada, à espada morrerão.'),
('acf','mt',26,53,'Ou pensas tu que eu não poderia agora orar a meu Pai, e que ele não me daria mais de doze legiões de anjos?'),
('acf','mt',26,54,'Como, pois, se cumpririam as Escrituras, que dizem que assim convém que aconteça?'),
('acf','mt',26,55,'Então disse Jesus à multidão: Saístes, como para um salteador, com espadas e varapaus para me prender? Todos os dias me assentava junto de vós, ensinando no templo, e não me prendestes.'),
('acf','mt',26,56,'Mas tudo isto aconteceu para que se cumpram as escrituras dos profetas. Então, todos os discípulos, deixando-o, fugiram.'),
('acf','mt',26,57,'E os que prenderam a Jesus o conduziram à casa do sumo sacerdote Caifás, onde os escribas e os anciãos estavam reunidos.'),
('acf','mt',26,58,'E Pedro o seguiu de longe, até ao pátio do sumo sacerdote e, entrando, assentou-se entre os criados, para ver o fim.'),
('acf','mt',26,59,'Ora, os príncipes dos sacerdotes, e os anciãos, e todo o conselho, buscavam falso testemunho contra Jesus, para poderem dar-lhe a morte;'),
('acf','mt',26,60,'E não o achavam; apesar de se apresentarem muitas testemunhas falsas, nào o achavam. Mas, por fim chegaram duas testemunhas falsas,'),
('acf','mt',26,61,'E disseram: Este disse: Eu posso derrubar o templo de Deus, e reedificá-lo em três dias.'),
('acf','mt',26,62,'E, levantando-se o sumo sacerdote, disse-lhe: Não respondes coisa alguma ao que estes depõem contra ti?'),
('acf','mt',26,63,'Jesus, porém, guardava silêncio. E, insistindo o sumo sacerdote, disse-lhe: Conjuro-te pelo Deus vivo que nos digas se tu és o Cristo, o Filho de Deus.'),
('acf','mt',26,64,'Disse-lhe Jesus: Tu o disseste; digo-vos, porém, que vereis em breve o Filho do homem assentado à direita do Poder, e vindo sobre as nuvens do céu.'),
('acf','mt',26,65,'Então o sumo sacerdote rasgou as suas vestes, dizendo: Blasfemou; para que precisamos ainda de testemunhas? Eis que bem ouvistes agora a sua blasfêmia.'),
('acf','mt',26,66,'Que vos parece? E eles, respondendo, disseram: É réu de morte.'),
('acf','mt',26,67,'Então cuspiram-lhe no rosto e lhe davam punhadas, e outros o esbofeteavam,'),
('acf','mt',26,68,'Dizendo: Profetiza-nos, Cristo, quem é o que te bateu?'),
('acf','mt',26,69,'Ora, Pedro estava assentado fora, no pátio; e, aproximando-se dele uma criada, disse: Tu também estavas com Jesus, o galileu.'),
('acf','mt',26,70,'Mas ele negou diante de todos, dizendo: Não sei o que dizes.'),
('acf','mt',26,71,'E, saindo para o vestíbulo, outra criada o viu, e disse aos que ali estavam: Este também estava com Jesus, o Nazareno.'),
('acf','mt',26,72,'E ele negou outra vez com juramento: Não conheço tal homem.'),
('acf','mt',26,73,'E, daí a pouco, aproximando-se os que ali estavam, disseram a Pedro: Verdadeiramente também tu és deles, pois a tua fala te denuncia.'),
('acf','mt',26,74,'Então começou ele a praguejar e a jurar, dizendo: Não conheço esse homem. E imediatamente o galo cantou.'),
('acf','mt',26,75,'E lembrou-se Pedro das palavras de Jesus, que lhe dissera: Antes que o galo cante, três vezes me negarás. E, saindo dali, chorou amargamente.'),
('acf','mt',27,1,'E, chegando a manhã, todos os príncipes dos sacerdotes, e os anciãos do povo, formavam juntamente conselho contra Jesus, para o matarem;'),
('acf','mt',27,2,'E maniatando-o, o levaram e entregaram ao presidente Pôncio Pilatos.'),
('acf','mt',27,3,'Então Judas, o que o traíra, vendo que fora condenado, trouxe, arrependido, as trinta moedas de prata aos príncipes dos sacerdotes e aos anciãos,'),
('acf','mt',27,4,'Dizendo: Pequei, traindo o sangue inocente. Eles, porém, disseram: Que nos importa? Isso é contigo.'),
('acf','mt',27,5,'E ele, atirando para o templo as moedas de prata, retirou-se e foi-se enforcar.'),
('acf','mt',27,6,'E os príncipes dos sacerdotes, tomando as moedas de prata, disseram: Não é lícito colocá-las no cofre das ofertas, porque são preço de sangue.'),
('acf','mt',27,7,'E, tendo deliberado em conselho, compraram com elas o campo de um oleiro, para sepultura dos estrangeiros.'),
('acf','mt',27,8,'Por isso foi chamado aquele campo, até ao dia de hoje, Campo de Sangue.'),
('acf','mt',27,9,'Então se realizou o que vaticinara o profeta Jeremias: Tomaram as trinta moedas de prata, preço do que foi avaliado, que certos filhos de Israel avaliaram,'),
('acf','mt',27,10,'E deram-nas pelo campo do oleiro, segundo o que o Senhor me determinou.'),
('acf','mt',27,11,'E foi Jesus apresentado ao presidente, e o presidente o interrogou, dizendo: És tu o Rei dos Judeus? E disse-lhe Jesus: Tu o dizes.'),
('acf','mt',27,12,'E, sendo acusado pelos príncipes dos sacerdotes e pelos anciãos, nada respondeu.'),
('acf','mt',27,13,'Disse-lhe então Pilatos: Não ouves quanto testificam contra ti?'),
('acf','mt',27,14,'E nem uma palavra lhe respondeu, de sorte que o presidente estava muito maravilhado.'),
('acf','mt',27,15,'Ora, por ocasião da festa, costumava o presidente soltar um preso, escolhendo o povo aquele que quisesse.'),
('acf','mt',27,16,'E tinham então um preso bem conhecido, chamado Barrabás.'),
('acf','mt',27,17,'Portanto, estando eles reunidos, disse-lhes Pilatos: Qual quereis que vos solte? Barrabás, ou Jesus, chamado Cristo?'),
('acf','mt',27,18,'Porque sabia que por inveja o haviam entregado.'),
('acf','mt',27,19,'E, estando ele assentado no tribunal, sua mulher mandou-lhe dizer: Não entres na questão desse justo, porque num sonho muito sofri por causa dele.'),
('acf','mt',27,20,'Mas os príncipes dos sacerdotes e os anciãos persuadiram à multidão que pedisse Barrabás e matasse Jesus.'),
('acf','mt',27,21,'E, respondendo o presidente, disse-lhes: Qual desses dois quereis vós que eu solte? E eles disseram: Barrabás.'),
('acf','mt',27,22,'Disse-lhes Pilatos: Que farei então de Jesus, chamado Cristo? Disseram-lhe todos: Seja crucificado.'),
('acf','mt',27,23,'O presidente, porém, disse: Mas que mal fez ele? E eles mais clamavam, dizendo: Seja crucificado.'),
('acf','mt',27,24,'Então Pilatos, vendo que nada aproveitava, antes o tumulto crescia, tomando água, lavou as mãos diante da multidão, dizendo: Estou inocente do sangue deste justo. Considerai isso.'),
('acf','mt',27,25,'E, respondendo todo o povo, disse: O seu sangue caia sobre nós e sobre nossos filhos.'),
('acf','mt',27,26,'Então soltou-lhes Barrabás, e, tendo mandado açoitar a Jesus, entregou-o para ser crucificado.'),
('acf','mt',27,27,'E logo os soldados do presidente, conduzindo Jesus à audiência, reuniram junto dele toda a coorte.'),
('acf','mt',27,28,'E, despindo-o, o cobriram com uma capa de escarlate;'),
('acf','mt',27,29,'E, tecendo uma coroa de espinhos, puseram-lha na cabeça, e em sua mão direita uma cana; e, ajoelhando diante dele, o escarneciam, dizendo: Salve, Rei dos judeus.'),
('acf','mt',27,30,'E, cuspindo nele, tiraram-lhe a cana, e batiam-lhe com ela na cabeça.'),
('acf','mt',27,31,'E, depois de o haverem escarnecido, tiraram-lhe a capa, vestiram-lhe as suas vestes e o levaram para ser crucificado.'),
('acf','mt',27,32,'E, quando saíam, encontraram um homem cireneu, chamado Simão, a quem constrangeram a levar a sua cruz.'),
('acf','mt',27,33,'E, chegando ao lugar chamado Gólgota, que se diz: Lugar da Caveira,'),
('acf','mt',27,34,'Deram-lhe a beber vinagre misturado com fel; mas ele, provando-o, não quis beber.'),
('acf','mt',27,35,'E, havendo-o crucificado, repartiram as suas vestes, lançando sortes, para que se cumprisse o que foi dito pelo profeta: Repartiram entre si as minhas vestes, e sobre a minha túnica lançaram sortes.'),
('acf','mt',27,36,'E, assentados, o guardavam ali.'),
('acf','mt',27,37,'E por cima da sua cabeça puseram escrita a sua acusação: este e³ jesus, o rei dos judeus.'),
('acf','mt',27,38,'E foram crucificados com ele dois salteadores, um à direita, e outro à esquerda.'),
('acf','mt',27,39,'E os que passavam blasfemavam dele, meneando as cabeças,'),
('acf','mt',27,40,'E dizendo: Tu, que destróis o templo, e em três dias o reedificas, salva-te a ti mesmo. Se és Filho de Deus, desce da cruz.'),
('acf','mt',27,41,'E da mesma maneira também os príncipes dos sacerdotes, com os escribas, e anciãos, e fariseus, escarnecendo, diziam:'),
('acf','mt',27,42,'Salvou os outros, e a si mesmo não pode salvar-se. Se é o Rei de Israel, desça agora da cruz, e creremos nele.'),
('acf','mt',27,43,'Confiou em Deus; livre-o agora, se o ama; porque disse: Sou Filho de Deus.'),
('acf','mt',27,44,'E o mesmo lhe lançaram também em rosto os salteadores que com ele estavam crucificados.'),
('acf','mt',27,45,'E desde a hora sexta houve trevas sobre toda a terra, até à hora nona.'),
('acf','mt',27,46,'E perto da hora nona exclamou Jesus em alta voz, dizendo: Eli, Eli, lamá sabactâni; isto é, Deus meu, Deus meu, por que me desamparaste?'),
('acf','mt',27,47,'E alguns dos que ali estavam, ouvindo isto, diziam: Este chama por Elias,'),
('acf','mt',27,48,'E logo um deles, correndo, tomou uma esponja, e embebeu-a em vinagre, e, pondo-a numa cana, dava-lhe de beber.'),
('acf','mt',27,49,'Os outros, porém, diziam: Deixa, vejamos se Elias vem livrá-lo.'),
('acf','mt',27,50,'E Jesus, clamando outra vez com grande voz, rendeu o espírito.'),
('acf','mt',27,51,'E eis que o véu do templo se rasgou em dois, de alto a baixo; e tremeu a terra, e fenderam-se as pedras;'),
('acf','mt',27,52,'E abriram-se os sepulcros, e muitos corpos de santos que dormiam foram ressuscitados;'),
('acf','mt',27,53,'E, saindo dos sepulcros, depois da ressurreição dele, entraram na cidade santa, e apareceram a muitos.'),
('acf','mt',27,54,'E o centurião e os que com ele guardavam a Jesus, vendo o terremoto, e as coisas que haviam sucedido, tiveram grande temor, e disseram: Verdadeiramente este era o Filho de Deus.'),
('acf','mt',27,55,'E estavam ali, olhando de longe, muitas mulheres que tinham seguido Jesus desde a Galiléia, para o servir;'),
('acf','mt',27,56,'Entre as quais estavam Maria Madalena, e Maria, mãe de Tiago e de José, e a mãe dos filhos de Zebedeu.'),
('acf','mt',27,57,'E, vinda já a tarde, chegou um homem rico, de Arimatéia, por nome José, que também era discípulo de Jesus.'),
('acf','mt',27,58,'Este foi ter com Pilatos, e pediu-lhe o corpo de Jesus. Então Pilatos mandou que o corpo lhe fosse dado.'),
('acf','mt',27,59,'E José, tomando o corpo, envolveu-o num fino e limpo lençol,'),
('acf','mt',27,60,'E o pôs no seu sepulcro novo, que havia aberto em rocha, e, rodando uma grande pedra para a porta do sepulcro, retirou-se.'),
('acf','mt',27,61,'E estavam ali Maria Madalena e a outra Maria, assentadas defronte do sepulcro.'),
('acf','mt',27,62,'E no dia seguinte, que é o dia depois da Preparação, reuniram-se os príncipes dos sacerdotes e os fariseus em casa de Pilatos,'),
('acf','mt',27,63,'Dizendo: Senhor, lembramo-nos de que aquele enganador, vivendo ainda, disse: Depois de três dias ressuscitarei.'),
('acf','mt',27,64,'Manda, pois, que o sepulcro seja guardado com segurança até ao terceiro dia, não se dê o caso que os seus discípulos vão de noite, e o furtem, e digam ao povo: Ressuscitou dentre os mortos; e assim o último erro será pior do que o primeiro.'),
('acf','mt',27,65,'E disse-lhes Pilatos: Tendes a guarda; ide, guardai-o como entenderdes.'),
('acf','mt',27,66,'E, indo eles, seguraram o sepulcro com a guarda, selando a pedra.'),
('acf','mt',28,1,'E, no fim do sábado, quando já despontava o primeiro dia da semana, Maria Madalena e a outra Maria foram ver o sepulcro.'),
('acf','mt',28,2,'E eis que houvera um grande terremoto, porque um anjo do Senhor, descendo do céu, chegou, removendo a pedra da porta, e sentou-se sobre ela.'),
('acf','mt',28,3,'E o seu aspecto era como um relâmpago, e as suas vestes brancas como neve.'),
('acf','mt',28,4,'E os guardas, com medo dele, ficaram muito assombrados, e como mortos.'),
('acf','mt',28,5,'Mas o anjo, respondendo, disse às mulheres: Não tenhais medo; pois eu sei que buscais a Jesus, que foi crucificado.'),
('acf','mt',28,6,'Ele não está aqui, porque já ressuscitou, como havia dito. Vinde, vede o lugar onde o Senhor jazia.'),
('acf','mt',28,7,'Ide pois, imediatamente, e dizei aos seus discípulos que já ressuscitou dentre os mortos. E eis que ele vai adiante de vós para a Galiléia; ali o vereis. Eis que eu vo-lo tenho dito.'),
('acf','mt',28,8,'E, saindo elas pressurosamente do sepulcro, com temor e grande alegria, correram a anunciá-lo aos seus discípulos.'),
('acf','mt',28,9,'E, indo elas a dar as novas aos seus discípulos, eis que Jesus lhes sai ao encontro, dizendo: Eu vos saúdo. E elas, chegando, abraçaram os seus pés, e o adoraram.'),
('acf','mt',28,10,'Então Jesus disse-lhes: Não temais; ide dizer a meus irmãos que vão à Galiléia, e lá me verão.'),
('acf','mt',28,11,'E, quando iam, eis que alguns da guarda, chegando à cidade, anunciaram aos príncipes dos sacerdotes todas as coisas que haviam acontecido.'),
('acf','mt',28,12,'E, congregados eles com os anciãos, e tomando conselho entre si, deram muito dinheiro aos soldados,'),
('acf','mt',28,13,'Dizendo: Dizei: Vieram de noite os seus discípulos e, dormindo nós, o furtaram.'),
('acf','mt',28,14,'E, se isto chegar a ser ouvido pelo presidente, nós o persuadiremos, e vos poremos em segurança.'),
('acf','mt',28,15,'E eles, recebendo o dinheiro, fizeram como estavam instruídos. E foi divulgado este dito entre os judeus, até ao dia de hoje.'),
('acf','mt',28,16,'E os onze discípulos partiram para a Galiléia, para o monte que Jesus lhes tinha designado.'),
('acf','mt',28,17,'E, quando o viram, o adoraram; mas alguns duvidaram.'),
('acf','mt',28,18,'E, chegando-se Jesus, falou-lhes, dizendo: É-me dado todo o poder no céu e na terra.'),
('acf','mt',28,19,'Portanto ide, fazei discípulos de todas as nações, batizando-os em nome do Pai, e do Filho, e do Espírito Santo;'),
('acf','mt',28,20,'Ensinando-os a guardar todas as coisas que eu vos tenho mandado; e eis que eu estou convosco todos os dias, até a consumação dos séculos. Amém.')
insert into public.bible_verses (version, book_abbrev, chapter, verse, text) values
('acf','mc',1,1,'Princípio do Evangelho de Jesus Cristo, Filho de Deus;'),
('acf','mc',1,2,'Como está escrito nos profetas: Eis que eu envio o meu anjo ante a tua face, o qual preparará o teu caminho diante de ti.'),
('acf','mc',1,3,'Voz do que clama no deserto: Preparai o caminho do Senhor, Endireitai as suas veredas.'),
('acf','mc',1,4,'Apareceu João batizando no deserto, e pregando o batismo de arrependimento, para remissão dos pecados.'),
('acf','mc',1,5,'E toda a província da Judéia e os de Jerusalém iam ter com ele; e todos eram batizados por ele no rio Jordão, confessando os seus pecados.'),
('acf','mc',1,6,'E João andava vestido de pêlos de camelo, e com um cinto de couro em redor de seus lombos, e comia gafanhotos e mel silvestre.'),
('acf','mc',1,7,'E pregava, dizendo: Após mim vem aquele que é mais forte do que eu, do qual não sou digno de, abaixando-me, desatar a correia das suas alparcas.'),
('acf','mc',1,8,'Eu, em verdade, tenho-vos batizado com água; ele, porém, vos batizará com o Espírito Santo.'),
('acf','mc',1,9,'E aconteceu naqueles dias que Jesus, tendo ido de Nazaré da Galiléia, foi batizado por João, no Jordão.'),
('acf','mc',1,10,'E, logo que saiu da água, viu os céus abertos, e o Espírito, que como pomba descia sobre ele.'),
('acf','mc',1,11,'E ouviu-se uma voz dos céus, que dizia: Tu és o meu Filho amado em quem me comprazo.'),
('acf','mc',1,12,'E logo o Espírito o impeliu para o deserto.'),
('acf','mc',1,13,'E ali esteve no deserto quarenta dias, tentado por Satanás. E vivia entre as feras, e os anjos o serviam.'),
('acf','mc',1,14,'E, depois que João foi entregue à prisão, veio Jesus para a Galiléia, pregando o evangelho do reino de Deus,'),
('acf','mc',1,15,'E dizendo: O tempo está cumprido, e o reino de Deus está próximo. Arrependei-vos, e crede no evangelho.'),
('acf','mc',1,16,'E, andando junto do mar da Galiléia, viu Simão, e André, seu irmão, que lançavam a rede ao mar, pois eram pescadores.'),
('acf','mc',1,17,'E Jesus lhes disse: Vinde após mim, e eu farei que sejais pescadores de homens.'),
('acf','mc',1,18,'E, deixando logo as suas redes, o seguiram.'),
('acf','mc',1,19,'E, passando dali um pouco mais adiante, viu Tiago, filho de Zebedeu, e João, seu irmão, que estavam no barco consertando as redes,'),
('acf','mc',1,20,'E logo os chamou. E eles, deixando o seu pai Zebedeu no barco com os jornaleiros, foram após ele.'),
('acf','mc',1,21,'Entraram em Cafarnaum e, logo no sábado, indo ele à sinagoga, ali ensinava.'),
('acf','mc',1,22,'E maravilharam-se da sua doutrina, porque os ensinava como tendo autoridade, e não como os escribas.'),
('acf','mc',1,23,'E estava na sinagoga deles um homem com um espírito imundo, o qual exclamou,'),
('acf','mc',1,24,'Dizendo: Ah! que temos contigo, Jesus Nazareno? Vieste destruir-nos? Bem sei quem és: o Santo de Deus.'),
('acf','mc',1,25,'E repreendeu-o Jesus, dizendo: Cala-te, e sai dele.'),
('acf','mc',1,26,'Então o espírito imundo, convulsionando-o, e clamando com grande voz, saiu dele.'),
('acf','mc',1,27,'E todos se admiraram, a ponto de perguntarem entre si, dizendo: Que é isto? Que nova doutrina é esta? Pois com autoridade ordena aos espíritos imundos, e eles lhe obedecem!'),
('acf','mc',1,28,'E logo correu a sua fama por toda a província da Galiléia.'),
('acf','mc',1,29,'E logo, saindo da sinagoga, foram à casa de Simão e de André com Tiago e João.'),
('acf','mc',1,30,'E a sogra de Simão estava deitada com febre; e logo lhe falaram dela.'),
('acf','mc',1,31,'Então, chegando-se a ela, tomou-a pela mão, e levantou-a; e imediatamente a febre a deixou, e servia-os.'),
('acf','mc',1,32,'E, tendo chegado a tarde, quando já se estava pondo o sol, trouxeram-lhe todos os que se achavam enfermos, e os endemoninhados.'),
('acf','mc',1,33,'E toda a cidade se ajuntou à porta.'),
('acf','mc',1,34,'E curou muitos que se achavam enfermos de diversas enfermidades, e expulsou muitos demônios, porém não deixava falar os demônios, porque o conheciam.'),
('acf','mc',1,35,'E, levantando-se de manhã, muito cedo, fazendo ainda escuro, saiu, e foi para um lugar deserto, e ali orava.'),
('acf','mc',1,36,'E seguiram-no Simão e os que com ele estavam.'),
('acf','mc',1,37,'E, achando-o, lhe disseram: Todos te buscam.'),
('acf','mc',1,38,'E ele lhes disse: Vamos às aldeias vizinhas, para que eu ali também pregue; porque para isso vim.'),
('acf','mc',1,39,'E pregava nas sinagogas deles, por toda a Galiléia, e expulsava os demônios.'),
('acf','mc',1,40,'E aproximou-se dele um leproso que, rogando-lhe, e pondo-se de joelhos diante dele, lhe dizia: Se queres, bem podes limpar-me.'),
('acf','mc',1,41,'E Jesus, movido de grande compaixão, estendeu a mão, e tocou-o, e disse-lhe: Quero, sê limpo.'),
('acf','mc',1,42,'E, tendo ele dito isto, logo a lepra desapareceu, e ficou limpo.'),
('acf','mc',1,43,'E, advertindo-o severamente, logo o despediu.'),
('acf','mc',1,44,'E disse-lhe: Olha, não digas nada a ninguém; porém vai, mostra-te ao sacerdote, e oferece pela tua purificação o que Moisés determinou, para lhes servir de testemunho.'),
('acf','mc',1,45,'Mas, tendo ele saído, começou a apregoar muitas coisas, e a divulgar o que acontecera; de sorte que Jesus já não podia entrar publicamente na cidade, mas conservava-se fora em lugares desertos; e de todas as partes iam ter com ele.'),
('acf','mc',2,1,'E alguns dias depois entrou outra vez em Cafarnaum, e soube-se que estava em casa.'),
('acf','mc',2,2,'E logo se ajuntaram tantos, que nem ainda nos lugares junto à porta cabiam; e anunciava-lhes a palavra.'),
('acf','mc',2,3,'E vieram ter com ele conduzindo um paralítico, trazido por quatro.'),
('acf','mc',2,4,'E, não podendo aproximar-se dele, por causa da multidão, descobriram o telhado onde estava, e, fazendo um buraco, baixaram o leito em que jazia o paralítico.'),
('acf','mc',2,5,'E Jesus, vendo a fé deles, disse ao paralítico: Filho, perdoados estão os teus pecados.'),
('acf','mc',2,6,'E estavam ali assentados alguns dos escribas, que arrazoavam em seus corações, dizendo:'),
('acf','mc',2,7,'Por que diz este assim blasfêmias? Quem pode perdoar pecados, senão Deus?'),
('acf','mc',2,8,'E Jesus, conhecendo logo em seu espírito que assim arrazoavam entre si, lhes disse: Por que arrazoais sobre estas coisas em vossos corações?'),
('acf','mc',2,9,'Qual é mais fácil? dizer ao paralítico: Estão perdoados os teus pecados; ou dizer-lhe: Levanta-te, e toma o teu leito, e anda?'),
('acf','mc',2,10,'Ora, para que saibais que o Filho do homem tem na terra poder para perdoar pecados (disse ao paralítico),'),
('acf','mc',2,11,'A ti te digo: Levanta-te, toma o teu leito, e vai para tua casa.'),
('acf','mc',2,12,'E levantou-se e, tomando logo o leito, saiu em presença de todos, de sorte que todos se admiraram e glorificaram a Deus, dizendo: Nunca tal vimos.'),
('acf','mc',2,13,'E tornou a sair para o mar, e toda a multidão ia ter com ele, e ele os ensinava.'),
('acf','mc',2,14,'E, passando, viu Levi, filho de Alfeu, sentado na alfândega, e disse-lhe: Segue-me. E, levantando-se, o seguiu.'),
('acf','mc',2,15,'E aconteceu que, estando sentado à mesa em casa deste, também estavam sentados à mesa com Jesus e seus discípulos muitos publicanos e pecadores; porque eram muitos, e o tinham seguido.'),
('acf','mc',2,16,'E os escribas e fariseus, vendo-o comer com os publicanos e pecadores, disseram aos seus discípulos: Por que come e bebe ele com os publicanos e pecadores?'),
('acf','mc',2,17,'E Jesus, tendo ouvido isto, disse-lhes: Os sãos não necessitam de médico, mas, sim, os que estão doentes; eu não vim chamar os justos, mas, sim, os pecadores ao arrependimento.'),
('acf','mc',2,18,'Ora, os discípulos de João e os fariseus jejuavam; e foram e disseram-lhe: Por que jejuam os discípulos de João e os dos fariseus, e não jejuam os teus discípulos?'),
('acf','mc',2,19,'E Jesus disse-lhes: Podem porventura os filhos das bodas jejuar enquanto está com eles o esposo? Enquanto têm consigo o esposo, não podem jejuar;'),
('acf','mc',2,20,'Mas dias virão em que lhes será tirado o esposo, e então jejuarão naqueles dias.'),
('acf','mc',2,21,'Ninguém deita remendo de pano novo em roupa velha; doutra sorte o mesmo remendo novo rompe o velho, e a rotura fica maior.'),
('acf','mc',2,22,'E ninguém deita vinho novo em odres velhos; doutra sorte, o vinho novo rompe os odres e entorna-se o vinho, e os odres estragam-se; o vinho novo deve ser deitado em odres novos.'),
('acf','mc',2,23,'E aconteceu que, passando ele num sábado pelas searas, os seus discípulos, caminhando, começaram a colher espigas.'),
('acf','mc',2,24,'E os fariseus lhe disseram: Vês? Por que fazem no sábado o que não é lícito?'),
('acf','mc',2,25,'Mas ele disse-lhes: Nunca lestes o que fez Davi, quando estava em necessidade e teve fome, ele e os que com ele estavam?'),
('acf','mc',2,26,'Como entrou na casa de Deus, no tempo de Abiatar, sumo sacerdote, e comeu os pães da proposição, dos quais não era lícito comer senão aos sacerdotes, dando também aos que com ele estavam?'),
('acf','mc',2,27,'E disse-lhes: O sábado foi feito por causa do homem, e não o homem por causa do sábado.'),
('acf','mc',2,28,'Assim o Filho do homem até do sábado é Senhor.'),
('acf','mc',3,1,'E outra vez entrou na sinagoga, e estava ali um homem que tinha uma das mãos mirrada.'),
('acf','mc',3,2,'E estavam observando-o securaria no sábado, para o acusarem.'),
('acf','mc',3,3,'E disse ao homem que tinha a mão mirrada: Levanta-te e vem para o meio.'),
('acf','mc',3,4,'E perguntou-lhes: É lícito no sábado fazer bem, ou fazer mal? salvar a vida, ou matar? E eles calaram-se.'),
('acf','mc',3,5,'E, olhando para eles em redor com indignação, condoendo-se da dureza do seu coração, disse ao homem: Estende a tua mão. E ele a estendeu, e foi-lhe restituída a sua mão, sã como a outra.'),
('acf','mc',3,6,'E, tendo saído os fariseus, tomaram logo conselho com os herodianos contra ele, procurando ver como o matariam.'),
('acf','mc',3,7,'E retirou-se Jesus com os seus discípulos para o mar, e seguia-o uma grande multidão da Galiléia e da Judéia,'),
('acf','mc',3,8,'E de Jerusalém, e da Iduméia, e de além do Jordão, e de perto de Tiro e de Sidom; uma grande multidão que, ouvindo quão grandes coisas fazia, vinha ter com ele.'),
('acf','mc',3,9,'E ele disse aos seus discípulos que lhe tivessem sempre pronto um barquinho junto dele, por causa da multidão, para que o não oprimisse,'),
('acf','mc',3,10,'Porque tinha curado a muitos, de tal maneira que todos quantos tinham algum mal se arrojavam sobre ele, para lhe tocarem.'),
('acf','mc',3,11,'E os espíritos imundos vendo-o, prostravam-se diante dele, e clamavam, dizendo: Tu és o Filho de Deus.'),
('acf','mc',3,12,'E ele os ameaçava muito, para que não o manifestassem.'),
('acf','mc',3,13,'E subiu ao monte, e chamou para si os que ele quis; e vieram a ele.'),
('acf','mc',3,14,'E nomeou doze para que estivessem com ele e os mandasse a pregar,'),
('acf','mc',3,15,'E para que tivessem o poderde curar as enfermidades e expulsar os demônios:'),
('acf','mc',3,16,'A Simão, a quem pôs o nome de Pedro,'),
('acf','mc',3,17,'E a Tiago, filho de Zebedeu, e a João, irmão de Tiago, aos quais pôs o nome de Boanerges, que significa: Filhos do trovão;'),
('acf','mc',3,18,'E a André, e a Filipe, e a Bartolomeu, e a Mateus, e a Tomé, e a Tiago, filho de Alfeu, e a Tadeu, e a Simão, o Cananita,'),
('acf','mc',3,19,'E a Judas Iscariotes, o que o entregou.'),
('acf','mc',3,20,'E foram para uma casa. E afluiu outra vez a multidão, de tal maneira que nem sequer podiam comer pão.'),
('acf','mc',3,21,'E, quando os seus ouviram isto, saíram para o prender; porque diziam: Está fora de si.'),
('acf','mc',3,22,'E os escribas, que tinham descido de Jerusalém, diziam: Tem Belzebu, e pelo príncipe dos demônios expulsa os demônios.'),
('acf','mc',3,23,'E, chamando-os a si, disse-lhes por parábolas: Como pode Satanás expulsar Satanás?'),
('acf','mc',3,24,'E, se um reino se dividir contra si mesmo, tal reino não pode subsistir;'),
('acf','mc',3,25,'E, se uma casa se dividir contra si mesma, tal casa não pode subsistir.'),
('acf','mc',3,26,'E, se Satanás se levantar contra si mesmo, e for dividido, não pode subsistir; antes tem fim.'),
('acf','mc',3,27,'Ninguém pode roubar os bens do valente, entrando-lhe em sua casa, se primeiro não maniatar o valente; e então roubará a sua casa.'),
('acf','mc',3,28,'Na verdade vos digo que todos os pecados serão perdoados aos filhos dos homens, e toda a sorte de blasfêmias, com que blasfemarem;'),
('acf','mc',3,29,'Qualquer, porém, que blasfemar contra o Espírito Santo, nunca obterá perdão, mas será réu do eterno juízo'),
('acf','mc',3,30,'(Porque diziam: Tem espírito imundo).'),
('acf','mc',3,31,'Chegaram, então, seus irmãos e sua mãe; e, estando fora, mandaram-no chamar.'),
('acf','mc',3,32,'E a multidão estava assentada ao redor dele, e disseram-lhe: Eis que tua mãe e teus irmãos te procuram, e estão lá fora.'),
('acf','mc',3,33,'E ele lhes respondeu, dizendo: Quem é minha mãe e meus irmãos?'),
('acf','mc',3,34,'E, olhando em redor para os que estavam assentados junto dele, disse: Eis aqui minha mãe e meus irmãos.'),
('acf','mc',3,35,'Porquanto, qualquer que fizer a vontade de Deus, esse é meu irmão, e minha irmã, e minha mãe.'),
('acf','mc',4,1,'E outra vez começou a ensinar junto do mar, e ajuntou-se a ele grande multidão, de sorte que ele entrou e assentou-se num barco, sobre o mar; e toda a multidão estava em terra junto do mar.'),
('acf','mc',4,2,'E ensinava-lhes muitas coisas por parábolas, e lhes dizia na sua doutrina:'),
('acf','mc',4,3,'Ouvi: Eis que saiu o semeador a semear.'),
('acf','mc',4,4,'E aconteceu que semeando ele, uma parte da semente caiu junto do caminho, e vieram as aves do céu, e a comeram;'),
('acf','mc',4,5,'E outra caiu sobre pedregais, onde não havia muita terra, e nasceu logo, porque não tinha terra profunda;'),
('acf','mc',4,6,'Mas, saindo o sol, queimou-se; e, porque não tinha raiz, secou-se.'),
('acf','mc',4,7,'E outra caiu entre espinhos e, crescendo os espinhos, a sufocaram e não deu fruto.'),
('acf','mc',4,8,'E outra caiu em boa terra e deu fruto, que vingou e cresceu; e um produziu trinta, outro sessenta, e outro cem.'),
('acf','mc',4,9,'E disse-lhes: Quem tem ouvidos para ouvir, ouça.'),
('acf','mc',4,10,'E, quando se achou só, osque estavam junto dele com os doze interrogaram-no acerca da parábola.'),
('acf','mc',4,11,'E ele disse-lhes: A vós vos é dado saber os mistérios do reino de Deus, mas aos que estão de fora todas estas coisas se dizem por parábolas,'),
('acf','mc',4,12,'Para que, vendo, vejam, e não percebam; e, ouvindo, ouçam, e não entendam; para que não se convertam, e lhes sejam perdoados os pecados.'),
('acf','mc',4,13,'E disse-lhes: Não percebeis esta parábola? Como, pois, entendereis todas as parábolas?'),
('acf','mc',4,14,'O que semeia, semeia a palavra;'),
('acf','mc',4,15,'E, os que estão junto do caminho são aqueles em quem a palavra é semeada; mas, tendo-a eles ouvido, vem logo Satanás e tira a palavra que foi semeada nos seus corações.'),
('acf','mc',4,16,'E da mesma forma os que recebem a semente sobre pedregais; os quais, ouvindo a palavra, logo com prazer a recebem;'),
('acf','mc',4,17,'Mas não têm raiz em si mesmos, antes são temporãos; depois, sobrevindo tribulação ou perseguição, por causa da palavra, logo se escandalizam.'),
('acf','mc',4,18,'E outros são os que recebem a semente entre espinhos, os quais ouvem a palavra;'),
('acf','mc',4,19,'Mas os cuidados deste mundo, e os enganos das riquezas e as ambições de outras coisas, entrando, sufocam a palavra, e fica infrutífera.'),
('acf','mc',4,20,'E estes são os que foram semeados em boa terra, os que ouvem a palavra e a recebem, e dão fruto, um trinta, e outro sessenta, e outro cem.'),
('acf','mc',4,21,'E disse-lhes: Vem porventura a candeia para se meter debaixo do alqueire, ou debaixo da cama? não vem antes para se colocar no velador?'),
('acf','mc',4,22,'Porque nada há encoberto que não haja de ser manifesto; e nada se faz para ficar oculto, mas para ser descoberto.'),
('acf','mc',4,23,'Se alguém tem ouvidos para ouvir, ouça.'),
('acf','mc',4,24,'E disse-lhes: Atendei ao que ides ouvir. Com a medida com que medirdes vos medirão a vós, e ser-vos-á ainda acrescentada a vós que ouvis.'),
('acf','mc',4,25,'Porque ao que tem, ser-lhe-á dado; e, ao que não tem, até o que tem lhe será tirado.'),
('acf','mc',4,26,'E dizia: O reino de Deus é assim como se um homem lançasse semente à terra.'),
('acf','mc',4,27,'E dormisse, e se levantasse de noite ou de dia, e a semente brotasse e crescesse, não sabendo ele como.'),
('acf','mc',4,28,'Porque a terra por si mesma frutifica, primeiro a erva, depois a espiga, por último o grão cheio na espiga.'),
('acf','mc',4,29,'E, quando já o fruto se mostra, mete-se-lhe logo a foice, porque está chegada a ceifa.'),
('acf','mc',4,30,'E dizia: A que assemelhare-mos o reino de Deus? ou com que parábola o representaremos?'),
('acf','mc',4,31,'É como um grão de mostarda, que, quando se semeia na terra, é a menor de todas as sementes que há na terra;'),
('acf','mc',4,32,'Mas, tendo sido semeado, cresce; e faz-se a maior de todas as hortaliças, e cria grandes ramos, de tal maneira que as aves do céu podem aninhar-se debaixo da sua sombra.'),
('acf','mc',4,33,'E com muitas parábolas tais lhes dirigia a palavra, segundo o que podiam compreender.'),
('acf','mc',4,34,'E sem parábolas nunca lhes falava; porém, tudo declarava em particular aos seus discípulos.'),
('acf','mc',4,35,'E, naquele dia, sendo já tarde, disse-lhes: Passemos para o outro lado.'),
('acf','mc',4,36,'E eles, deixando a multidão, o levaram consigo, assim como estava, no barco; e havia também com ele outros barquinhos.'),
('acf','mc',4,37,'E levantou-se grande temporal de vento, e subiam as ondas por cima do barco, de maneira que já se enchia.'),
('acf','mc',4,38,'E ele estava na popa, dormindo sobre uma almofada, e despertaram-no, dizendo-lhe: Mestre, não se te dá que pereçamos?'),
('acf','mc',4,39,'E ele, despertando, repreendeu o vento, e disse ao mar: Cala-te, aquieta-te. E o vento se aquietou, e houve grande bonança.'),
('acf','mc',4,40,'E disse-lhes: Por que sois tão tímidos? Ainda não tendes fé?'),
('acf','mc',4,41,'E sentiram um grande temor, e diziam uns aos outros: Mas quem é este, que até o vento e o mar lhe obedecem?'),
('acf','mc',5,1,'E chegaram ao outro lado do mar, à província dos gadarenos.'),
('acf','mc',5,2,'E, saindo ele do barco, lhe saiu logo ao seu encontro, dos sepulcros, um homem com espírito imundo;'),
('acf','mc',5,3,'O qual tinha a sua morada nos sepulcros, e nem ainda com cadeias o podia alguém prender;'),
('acf','mc',5,4,'Porque, tendo sido muitas vezes preso com grilhões e cadeias, as cadeias foram por ele feitas em pedaços, e os grilhões em migalhas, e ninguém o podia amansar.'),
('acf','mc',5,5,'E andava sempre, de dia e de noite, clamando pelos montes, e pelos sepulcros, e ferindo-se com pedras.'),
('acf','mc',5,6,'E, quando viu Jesus ao longe, correu e adorou-o.'),
('acf','mc',5,7,'E, clamando com grande voz, disse: Que tenho eu contigo, Jesus, Filho do Deus Altíssimo? conjuro-te por Deus que não me atormentes.'),
('acf','mc',5,8,'(Porque lhe dizia: Sai deste homem, espírito imundo.)'),
('acf','mc',5,9,'E perguntou-lhe: Qual é o teu nome? E lhe respondeu, dizendo: Legião é o meu nome, porque somos muitos.'),
('acf','mc',5,10,'E rogava-lhe muito que os não enviasse para fora daquela província.'),
('acf','mc',5,11,'E andava ali pastando no monte uma grande manada de porcos.'),
('acf','mc',5,12,'E todos aqueles demônios lhe rogaram, dizendo: Manda-nos para aqueles porcos, para que entremos neles.'),
('acf','mc',5,13,'E Jesus logo lho permitiu. E, saindo aqueles espíritos imundos, entraram nos porcos; e a manada se precipitou por um despenhadeiro no mar (eram quase dois mil), e afogaram-se no mar.'),
('acf','mc',5,14,'E os que apascentavam os porcos fugiram, e o anunciaram na cidade e nos campos; e saíram muitos a ver o que era aquilo que tinha acontecido.'),
('acf','mc',5,15,'E foram ter com Jesus, e viram o endemoninhado, o que tivera a legião, assentado, vestido e em perfeito juízo, e temeram.'),
('acf','mc',5,16,'E os que aquilo tinham visto contaram-lhes o que acontecera ao endemoninhado, e acerca dos porcos.'),
('acf','mc',5,17,'E começaram a rogar-lhe que saísse dos seus termos.'),
('acf','mc',5,18,'E, entrando ele no barco, rogava-lhe o que fora endemoninhado que o deixasse estar com ele.'),
('acf','mc',5,19,'Jesus, porém, não lho permitiu, mas disse-lhe: Vai para tua casa, para os teus, e anuncia-lhes quão grandes coisas o Senhor te fez, e como teve misericórdia de ti.'),
('acf','mc',5,20,'E ele foi, e começou a anunciar em Decápolis quão grandes coisas Jesus lhe fizera; e todos se maravilharam.'),
('acf','mc',5,21,'E, passando Jesus outra vez num barco para o outro lado, ajuntou-se a ele uma grande multidão; e ele estava junto do mar.'),
('acf','mc',5,22,'E eis que chegou um dos principais da sinagoga, por nome Jairo, e, vendo-o, prostrou-se aos seus pés,'),
('acf','mc',5,23,'E rogava-lhe muito, dizendo: Minha filha está à morte; rogo-te que venhas e lhe imponhas as mãos, para que sare, e viva.'),
('acf','mc',5,24,'E foi com ele, e seguia-o uma grande multidão, que o apertava.'),
('acf','mc',5,25,'E certa mulher que, havia doze anos, tinha um fluxo de sangue,'),
('acf','mc',5,26,'E que havia padecido muito com muitos médicos, e despendido tudo quanto tinha, nada lhe aproveitando isso, antes indo a pior;'),
('acf','mc',5,27,'Ouvindo falar de Jesus, veio por detrás, entre a multidão, e tocou na sua veste.'),
('acf','mc',5,28,'Porque dizia: Se tão-somente tocar nas suas vestes, sararei.'),
('acf','mc',5,29,'E logo se lhe secou a fonte do seu sangue; e sentiu no seu corpo estar já curada daquele mal.'),
('acf','mc',5,30,'E logo Jesus, conhecendo que a virtude de si mesmo saíra, voltou-se para a multidão, e disse: Quem tocou nas minhas vestes?'),
('acf','mc',5,31,'E disseram-lhe os seus discípulos: Vês que a multidão te aperta, e dizes: Quem me tocou?'),
('acf','mc',5,32,'E ele olhava em redor, para ver a que isto fizera.'),
('acf','mc',5,33,'Então a mulher, que sabia o que lhe tinha acontecido, temendo e tremendo, aproximou-se, e prostrou-se diante dele, e disse-lhe toda a verdade.'),
('acf','mc',5,34,'E ele lhe disse: Filha, a tua fé te salvou; vai em paz, e sê curada deste teu mal.'),
('acf','mc',5,35,'Estando ele ainda falando, chegaram alguns do principal da sinagoga, a quem disseram: A tuafilha está morta; para que enfadas mais o Mestre?'),
('acf','mc',5,36,'E Jesus, tendo ouvido estas palavras, disse ao principal da sinagoga: Não temas, crê somente.'),
('acf','mc',5,37,'E não permitiu que alguém o seguisse, a não ser Pedro, Tiago, e João, irmão de Tiago.'),
('acf','mc',5,38,'E, tendo chegado à casa do principal da sinagoga, viu o alvoroço, e os que choravam muito e pranteavam.'),
('acf','mc',5,39,'E, entrando, disse-lhes: Por que vos alvoroçais e chorais? A menina não está morta, mas dorme.'),
('acf','mc',5,40,'E riam-se dele; porém ele, tendo-os feito sair, tomou consigo o pai e a mãe da menina, e os que com ele estavam, e entrou onde a menina estava deitada.'),
('acf','mc',5,41,'E, tomando a mão da menina, disse-lhe: Talita cumi; que, traduzido, é: Menina, a ti te digo, levanta-te.'),
('acf','mc',5,42,'E logo a menina se levantou, e andava, pois já tinha doze anos; e assombraram-se com grande espanto.'),
('acf','mc',5,43,'E mandou-lhes expressamente que ninguém o soubesse; e disse que lhe dessem de comer.'),
('acf','mc',6,1,'E, partindo dali, chegou à sua pátria, e os seus discípulos o seguiram.'),
('acf','mc',6,2,'E, chegando o sábado, começou a ensinar na sinagoga; e muitos, ouvindo-o, se admiravam, dizendo: De onde lhe vêm estas coisas? e que sabedoria é esta que lhe foi dada? e como se fazem tais maravilhas por suas mãos?'),
('acf','mc',6,3,'Não é este o carpinteiro, filho de Maria, e irmão de Tiago, e de José, e de Judas e de Simão? e não estão aqui conosco suas irmãs? E escandalizavam-se nele.'),
('acf','mc',6,4,'E Jesus lhes dizia: Não há profeta sem honra senão na suapátria, entre os seus parentes, e na sua casa.'),
('acf','mc',6,5,'E não podia fazer ali nenhuma obra maravilhosa; somente curou alguns poucos enfermos, impondo-lhes as mãos.'),
('acf','mc',6,6,'E estava admirado da incredulidade deles. E percorreu as aldeias vizinhas, ensinando.'),
('acf','mc',6,7,'Chamou a si os doze, e começou a enviá-los a dois e dois, e deu-lhes poder sobre os espíritos imundos;'),
('acf','mc',6,8,'E ordenou-lhes que nada tomassem para o caminho, senão somente um bordão; nem alforje, nem pão, nem dinheiro no cinto;'),
('acf','mc',6,9,'Mas que calçassem alparcas, e que não vestissem duas túnicas.'),
('acf','mc',6,10,'E dizia-lhes: Na casa em que entrardes, ficai nela até partirdes dali.'),
('acf','mc',6,11,'E tantos quantos vos não receberem, nem vos ouvirem, saindo dali, sacudi o pó que estiver debaixo dos vossos pés, em testemunho contra eles. Em verdade vos digo que haverá mais tolerância no dia de juízo para Sodoma e Gomorra, do que para os daquela cidade.'),
('acf','mc',6,12,'E, saindo eles, pregavam que se arrependessem.'),
('acf','mc',6,13,'E expulsavam muitos demônios, e ungiam muitos enfermos com óleo, e os curavam.'),
('acf','mc',6,14,'E ouviu isto o rei Herodes (porque o nome de Jesus se tornara notório), e disse: João, o que batizava, ressuscitou dentre os mortos, e por isso estas maravilhas operam nele.'),
('acf','mc',6,15,'Outros diziam: É Elias. E diziam outros: É um profeta, ou como um dos profetas.'),
('acf','mc',6,16,'Herodes, porém, ouvindo isto, disse: Este é João, que mandei degolar; ressuscitou dentre os mortos.'),
('acf','mc',6,17,'Porquanto o mesmo Herodes mandara prender a João, e encerrá-lo maniatado no cárcere, por causa de Herodias, mulher de Filipe, seu irmão, porquanto tinha casado com ela.'),
('acf','mc',6,18,'Pois João dizia a Herodes: Não te é lícito possuir a mulher de teu irmão.'),
('acf','mc',6,19,'E Herodias o espiava, e queria matá-lo, mas não podia.'),
('acf','mc',6,20,'Porque Herodes temia a João, sabendo que era homem justo e santo; e guardava-o com segurança, e fazia muitas coisas, atendendo-o, e de boa mente o ouvia.'),
('acf','mc',6,21,'E, chegando uma ocasião favorável em que Herodes, no dia dos seus anos, dava uma ceia aos grandes, e tribunos, e príncipes da Galiléia,'),
('acf','mc',6,22,'Entrou a filha da mesma Herodias, e dançou, e agradou a Herodes e aos que estavam com ele à mesa. Disse então o rei à menina: Pede-me o que quiseres, e eu to darei.'),
('acf','mc',6,23,'E jurou-lhe, dizendo: Tudo o que me pedires te darei, até metade do meu reino.'),
('acf','mc',6,24,'E, saindo ela, perguntou a sua mãe: Que pedirei? E ela disse: A cabeça de João o Batista.'),
('acf','mc',6,25,'E, entrando logo, apressadamente, pediu ao rei, dizendo: Quero que imediatamente me dês num prato a cabeça de João o Batista.'),
('acf','mc',6,26,'E o rei entristeceu-se muito; todavia, por causa do juramento e dos que estavam com ele à mesa, não lha quis negar.'),
('acf','mc',6,27,'E, enviando logo o rei o executor, mandou que lhe trouxessem ali a cabeça de João. E ele foi, e degolou-o na prisão;'),
('acf','mc',6,28,'E trouxe a cabeça num prato, e deu-a à menina, e a menina a deu a sua mãe.'),
('acf','mc',6,29,'E os seus discípulos, tendo ouvido isto, foram, tomaram o seu corpo, e o puseram num sepulcro.'),
('acf','mc',6,30,'E os apóstolos ajuntaram-se a Jesus, e contaram-lhe tudo, tanto o que tinham feito como o que tinham ensinado.'),
('acf','mc',6,31,'E ele disse-lhes: Vinde vós, aqui à parte, a um lugar deserto, e repousai um pouco. Porque havia muitos que iam e vinham, e não tinham tempo para comer.'),
('acf','mc',6,32,'E foram sós num barco para um lugar deserto.'),
('acf','mc',6,33,'E a multidão viu-os partir, e muitos o conheceram; e correram para lá, a pé, de todas as cidades, e ali chegaram primeiro do que eles, e aproximavam-se dele.'),
('acf','mc',6,34,'E Jesus, saindo, viu uma grande multidão, e teve compaixão deles, porque eram como ovelhas que não têm pastor; e começou a ensinar-lhes muitas coisas.'),
('acf','mc',6,35,'E, como o dia fosse já muito adiantado, os seus discípulos se aproximaram dele, e lhe disseram: O lugar é deserto, e o dia está já muito adiantado.'),
('acf','mc',6,36,'Despede-os, para que vão aos lugares e aldeias circunvizinhas, e comprem pão para si; porque não têm que comer.'),
('acf','mc',6,37,'Ele, porém, respondendo, lhes disse: Dai-lhes vós de comer. E eles disseram-lhe: Iremos nós, e compraremos duzentos dinheiros de pão para lhes darmos de comer?'),
('acf','mc',6,38,'E ele disse-lhes: Quantos pães tendes? Ide ver. E, sabendo-o eles, disseram: Cinco pães e dois peixes.'),
('acf','mc',6,39,'E ordenou-lhes que fizessem assentar a todos, em ranchos, sobre a erva verde.'),
('acf','mc',6,40,'E assentaram-se repartidos de cem em cem, e de cinqüenta em cinqüenta.'),
('acf','mc',6,41,'E, tomando ele os cinco pães e os dois peixes, levantou os olhos ao céu, abençoou e partiu os pães, e deu-os aos seus discípulos para que os pusessem diante deles. E repartiu os dois peixes por todos.'),
('acf','mc',6,42,'E todos comeram, e ficaram fartos;'),
('acf','mc',6,43,'E levantaram doze alcofas cheias de pedaços de pão e de peixe.'),
('acf','mc',6,44,'E os que comeram os pães eram quase cinco mil homens.'),
('acf','mc',6,45,'E logo obrigou os seus discípulos a subir para o barco, e passar adiante, para o outro lado, a Betsaida, enquanto ele despedia a multidão.'),
('acf','mc',6,46,'E, tendo-os despedido, foi ao monte a orar.'),
('acf','mc',6,47,'E, sobrevindo a tarde, estava o barco no meio do mar e ele, sozinho, em terra.'),
('acf','mc',6,48,'E vendo que se fatigavam a remar, porque o vento lhes era contrário, perto da quarta vigília da noite aproximou-se deles, andando sobre o mar, e queria passar-lhes adiante.'),
('acf','mc',6,49,'Mas, quando eles o viram andar sobre o mar, cuidaram que era um fantasma, e deram grandes gritos.'),
('acf','mc',6,50,'Porque todos o viam, e perturbaram-se; mas logo falou com eles, e disse-lhes: Tende bom ânimo; sou eu, não temais.'),
('acf','mc',6,51,'E subiu para o barco, para estar com eles, e o vento se aquietou; e entre si ficaram muito assombrados e maravilhados;'),
('acf','mc',6,52,'Pois não tinham compreendido o milagre dos pães; antes o seu coração estava endurecido.'),
('acf','mc',6,53,'E, quando já estavam no outro lado, dirigiram-se à terra de Genesaré, e ali atracaram.'),
('acf','mc',6,54,'E, saindo eles do barco, logo o conheceram;'),
('acf','mc',6,55,'E, correndo toda a terra em redor, começaram a trazer em leitos, aonde quer que sabiam que ele estava, os que se achavam enfermos.'),
('acf','mc',6,56,'E, onde quer que entrava, ou em cidade, ou aldeias, ou no campo, apresentavam os enfermos nas praças, e rogavam-lhe que os deixasse tocar ao menos na orla da sua roupa; e todos os que lhe tocavam saravam.'),
('acf','mc',7,1,'E ajuntaram-se a ele os fariseus, e alguns dos escribas que tinham vindo de Jerusalém.'),
('acf','mc',7,2,'E, vendo que alguns dos seus discípulos comiam pão com as mãos impuras, isto é, por lavar, os repreendiam.'),
('acf','mc',7,3,'Porque os fariseus, e todos os judeus, conservando a tradição dos antigos, não comem sem lavar as mãos muitas vezes;'),
('acf','mc',7,4,'E, quando voltam do mercado, se não se lavarem, não comem. E muitas outras coisas há que receberam para observar, como lavar os copos, e os jarros, e os vasos de metal e as camas.'),
('acf','mc',7,5,'Depois perguntaram-lhe os fariseus e os escribas: Por que não andam os teus discípulos conforme a tradição dos antigos, mas comem o pão com as mãos por lavar?'),
('acf','mc',7,6,'E ele, respondendo, disse-lhes: Bem profetizou Isaías acerca de vós, hipócritas, como está escrito:Este povo honra-me com os lábios,Mas o seu coração está longe de mim;'),
('acf','mc',7,7,'Em vão, porém, me honram,Ensinando doutrinas que são mandamentos de homens.'),
('acf','mc',7,8,'Porque, deixando o mandamento de Deus, retendes a tradição dos homens; como o lavar dos jarros e dos copos; e fazeis muitas outras coisas semelhantes a estas.'),
('acf','mc',7,9,'E dizia-lhes: Bem invalidais o mandamento de Deus para guardardes a vossa tradição.'),
('acf','mc',7,10,'Porque Moisés disse: Honra a teu pai e a tua mãe; e quem maldisser, ou o pai ou a mãe, certamente morrerá.'),
('acf','mc',7,11,'Vós, porém, dizeis: Se um homem disser ao pai ou à mãe: Aquilo que poderias aproveitar de mim é Corbã, isto é, oferta ao Senhor;'),
('acf','mc',7,12,'Nada mais lhe deixais fazer por seu pai ou por sua mãe,'),
('acf','mc',7,13,'Invalidando assim a palavra de Deus pela vossa tradição, que vós ordenastes. E muitas coisas fazeis semelhantes a estas.'),
('acf','mc',7,14,'E, chamando outra vez a multidão, disse-lhes: Ouvi-me vós, todos, e compreendei.'),
('acf','mc',7,15,'Nada há, fora do homem, que, entrando nele, o possa contaminar; mas o que sai dele isso é que contamina o homem.'),
('acf','mc',7,16,'Se alguém tem ouvidos para ouvir, ouça.'),
('acf','mc',7,17,'Depois, quando deixou a multidão, e entrou em casa, os seus discípulos o interrogavam acerca desta parábola.'),
('acf','mc',7,18,'E ele disse-lhes: Assim também vós estais sem entendimento? Não compreendeis que tudo o que de fora entra no homem não o pode contaminar,'),
('acf','mc',7,19,'Porque não entra no seu coração, mas no ventre, e é lançado fora, ficando puras todas as comidas?'),
('acf','mc',7,20,'E dizia: O que sai do homem isso contamina o homem.'),
('acf','mc',7,21,'Porque do interior do coração dos homens saem os maus pensamentos, os adultérios, as fornicações, os homicídios,'),
('acf','mc',7,22,'Os furtos, a avareza, as maldades, o engano, a dissolução, a inveja, a blasfêmia, a soberba, a loucura.'),
('acf','mc',7,23,'Todos estes males procedem de dentro e contaminam o homem.'),
('acf','mc',7,24,'E, levantando-se dali, foi para os termos de Tiro e de Sidom. E, entrando numa casa, não queria que alguém o soubesse, mas não pôde esconder-se;'),
('acf','mc',7,25,'Porque uma mulher, cuja filha tinha um espírito imundo, ouvindo falar dele, foi e lançou-se aos seus pés.'),
('acf','mc',7,26,'E esta mulher era grega, siro-fenícia de nação, e rogava-lhe que expulsasse de sua filha o demônio.'),
('acf','mc',7,27,'Mas Jesus disse-lhe: Deixa primeiro saciar os filhos; porque não convém tomar o pão dos filhos e lançá-lo aos cachorrinhos.'),
('acf','mc',7,28,'Ela, porém, respondeu, e disse-lhe: Sim, Senhor; mas também os cachorrinhos comem, debaixo da mesa, as migalhas dos filhos.'),
('acf','mc',7,29,'Então ele disse-lhe: Por essa palavra, vai; o demônio já saiu de tua filha.'),
('acf','mc',7,30,'E, indo ela para sua casa, achou a filha deitada sobre a cama, e que o demônio já tinha saído.'),
('acf','mc',7,31,'E ele, tornando a sair dos termos de Tiro e de Sidom, foi até ao mar da Galiléia, pelos confins de Decápolis.'),
('acf','mc',7,32,'E trouxeram-lhe um surdo, que falava dificilmente; e rogaram-lhe que pusesse a mão sobre ele.'),
('acf','mc',7,33,'E, tirando-o à parte, de entre a multidão, pôs-lhe os dedos nos ouvidos; e, cuspindo, tocou-lhe na língua.'),
('acf','mc',7,34,'E, levantando os olhos ao céu, suspirou, e disse: Efatá; isto é, Abre-te.'),
('acf','mc',7,35,'E logo se abriram os seus ouvidos, e a prisão da língua se desfez, e falava perfeitamente.'),
('acf','mc',7,36,'E ordenou-lhes que a ninguém o dissessem; mas, quanto mais lhos proibia, tanto mais o divulgavam.'),
('acf','mc',7,37,'E, admirando-se sobremaneira, diziam: Tudo faz bem; faz ouvir os surdos e falar os mudos.'),
('acf','mc',8,1,'Naqueles dias, havendo uma grande multidão, e não tendo o que comer, Jesus chamou a si os seus discípulos, e disse-lhes:'),
('acf','mc',8,2,'Tenho compaixão da multidão, porque há já três dias que estão comigo, e não têm o que comer.'),
('acf','mc',8,3,'E, se os deixar ir em jejum, para suas casas, desfalecerão no caminho, porque alguns deles vieram de longe.'),
('acf','mc',8,4,'E os seus discípulos responderam-lhe: De onde poderá alguém satisfazê-los de pão aqui no deserto?'),
('acf','mc',8,5,'E perguntou-lhes: Quantos pães tendes? E disseram-lhe: Sete.'),
('acf','mc',8,6,'E ordenou à multidão que se assentasse no chão. E, tomando os sete pães, e tendo dado graças, partiu-os, e deu-os aos seus discípulos, para que os pusessem diante deles, e puseram-nos diante da multidão.'),
('acf','mc',8,7,'Tinham também alguns peixinhos; e, tendo dado graças, ordenou que também lhos pusessem diante.'),
('acf','mc',8,8,'E comeram, e saciaram-se; e dos pedaços que sobejaram levantaram sete cestos.'),
('acf','mc',8,9,'E os que comeram eram quase quatro mil; e despediu-os.'),
('acf','mc',8,10,'E, entrando logo no barco, com os seus discípulos, foi para as partes de Dalmanuta.'),
('acf','mc',8,11,'E saíram os fariseus, e começaram a disputar com ele, pedindolhe, para o tentarem, um sinal do céu.'),
('acf','mc',8,12,'E, suspirando profundamente em seu espírito, disse: Por que pede esta geração um sinal? Em verdade vos digo que a esta geração não se dará sinal algum.'),
('acf','mc',8,13,'E, deixando-os, tornou a entrar no barco, e foi para o outro lado.'),
('acf','mc',8,14,'E eles se esqueceram de levar pão e, no barco, não tinham consigo senão um pão.'),
('acf','mc',8,15,'E ordenou-lhes, dizendo: Olhai, guardai-vos do fermento dos fariseus e do fermento de Herodes.'),
('acf','mc',8,16,'E arrazoavam entre si, dizendo: É porque não temos pão.'),
('acf','mc',8,17,'E Jesus, conhecendo isto, disse-lhes: Para que arrazoais, que não tendes pão? não considerastes, nem compreendestes ainda? tendes ainda o vosso coração endurecido?'),
('acf','mc',8,18,'Tendo olhos, não vedes? e tendo ouvidos, não ouvis? e não vos lembrais,'),
('acf','mc',8,19,'Quando parti os cinco pães entre os cinco mil, quantas alcofas cheias de pedaços levantastes? Disseram-lhe: Doze.'),
('acf','mc',8,20,'E, quando parti os sete entre os quatro mil, quantos cestos cheios de pedaços levantastes? E disseram-lhe: Sete.'),
('acf','mc',8,21,'E ele lhes disse: Como não entendeis ainda?'),
('acf','mc',8,22,'E chegou a Betsaida; e trouxeram-lhe um cego, e rogaram-lhe que o tocasse.'),
('acf','mc',8,23,'E, tomando o cego pela mão, levou-o para fora da aldeia; e, cuspindo-lhe nos olhos, e impondo-lhe as mãos, perguntou-lhe se via alguma coisa.'),
('acf','mc',8,24,'E, levantando ele os olhos, disse: Vejo os homens; pois os vejo como árvores que andam.'),
('acf','mc',8,25,'Depois disto, tornou a pôr-lhe as mãos sobre os olhos, e o fez olhar para cima: e ele ficou restaurado, e viu a todos claramente.'),
('acf','mc',8,26,'E mandou-o para sua casa, dizendo: Nem entres na aldeia, nem o digas a ninguém na aldeia.'),
('acf','mc',8,27,'E saiu Jesus, e os seus discípulos, para as aldeias de Cesaréia de Filipe; e no caminho perguntou aos seus discípulos, dizendo: Quem dizem os homens que eu sou?'),
('acf','mc',8,28,'E eles responderam: João o Batista; e outros: Elias; mas outros: Um dos profetas.'),
('acf','mc',8,29,'E ele lhes disse: Mas vós, quem dizeis que eu sou? E, respondendo Pedro, lhe disse: Tu és o Cristo.'),
('acf','mc',8,30,'E admoestou-os, para que a ninguém dissessem aquilo dele.'),
('acf','mc',8,31,'E começou a ensinar-lhes que importava que o Filho do homem padecesse muito, e que fosse rejeitado pelos anciãos e príncipes dos sacerdotes, e pelos escribas, e que fosse morto, mas que depois de três dias ressuscitaria.'),
('acf','mc',8,32,'E dizia abertamente estas palavras. E Pedro o tomou à parte, e começou a repreendê-lo.'),
('acf','mc',8,33,'Mas ele, virando-se, e olhando para os seus discípulos, repreendeu a Pedro, dizendo: Retira-te de diante de mim, Satanás; porque não compreendes as coisas que são de Deus, mas as que são dos homens.'),
('acf','mc',8,34,'E chamando a si a multidão, com os seus discípulos, disse-lhes: Se alguém quiser vir após mim, negue-se a si mesmo, e tome a sua cruz, e siga-me.'),
('acf','mc',8,35,'Porque qualquer que quiser salvar a sua vida, perdê-la-á, mas, qualquer que perder a sua vida por amor de mim e do evangelho, esse a salvará.'),
('acf','mc',8,36,'Pois, que aproveitaria ao homem ganhar todo o mundo e perder a sua alma?'),
('acf','mc',8,37,'Ou, que daria o homem pelo resgate da sua alma?'),
('acf','mc',8,38,'Porquanto, qualquer que, entre esta geração adúltera e pecadora, se envergonhar de mim e das minhas palavras, também o Filho do homem se envergonhará dele, quando vier na glória de seu Pai, com os santos anjos.'),
('acf','mc',9,1,'Dizia-lhes também: Em verdade vos digo que, dos que aqui estão, alguns há que não provarão a morte sem que vejam chegado o reino de Deus com poder.'),
('acf','mc',9,2,'E seis dias depois Jesus tomou consigo a Pedro, a Tiago, e a João, e os levou sós, em particular, a um alto monte; e transfigurou-se diante deles;'),
('acf','mc',9,3,'E as suas vestes tornaram- se resplandecentes, extremamente brancas como a neve, tais como nenhum lavadeiro sobre a terra as poderia branquear.'),
('acf','mc',9,4,'E apareceu-lhes Elias, com Moisés, e falavam com Jesus.'),
('acf','mc',9,5,'E Pedro, tomando a palavra, disse a Jesus: Mestre, é bom que estejamos aqui; e façamos três cabanas, uma para ti, outra para Moisés, e outra para Elias.'),
('acf','mc',9,6,'Pois não sabia o que dizia, porque estavam assombrados.'),
('acf','mc',9,7,'E desceu uma nuvem que os cobriu com a sua sombra, e saiu da nuvem uma voz que dizia: Este é o meu filho amado; a ele ouvi.'),
('acf','mc',9,8,'E, tendo olhado em redor, ninguém mais viram, senão só Jesus com eles.'),
('acf','mc',9,9,'E, descendo eles do monte, ordenou-lhes que a ninguém contassem o que tinham visto, até que o Filho do homem ressuscitasse dentre os mortos.'),
('acf','mc',9,10,'E eles retiveram o caso entre si, perguntando uns aos outros que seria aquilo, ressuscitar dentre os mortos.'),
('acf','mc',9,11,'E interrogaram-no, dizendo: Por que dizem os escribas que é necessário que Elias venha primeiro?'),
('acf','mc',9,12,'E, respondendo ele, disse-lhes: Em verdade Elias virá primeiro, e todas as coisas restaurará; e, como está escrito do Filho do homem, que ele deva padecer muito e ser aviltado.'),
('acf','mc',9,13,'Digo-vos, porém, que Elias já veio, e fizeram-lhe tudo o que quiseram, como dele está escrito.'),
('acf','mc',9,14,'E, quando se aproximou dos discípulos, viu ao redor deles grande multidão, e alguns escribas que disputavam com eles.'),
('acf','mc',9,15,'E logo toda a multidão, vendo-o, ficou espantada e, correndo para ele, o saudaram.'),
('acf','mc',9,16,'E perguntou aos escribas: Que é que discutis com eles?'),
('acf','mc',9,17,'E um da multidão, respondendo, disse: Mestre, trouxe-te o meu filho, que tem um espírito mudo;'),
('acf','mc',9,18,'E este, onde quer que o apanhe, despedaça-o, e ele espuma, e range os dentes, e vai definhando; e eu disse aos teus discípulos que o expulsassem, e não puderam.'),
('acf','mc',9,19,'E ele, respondendo-lhes, disse: Ó geração incrédula! até quando estarei convosco? até quando vos sofrerei ainda? Trazei-mo.'),
('acf','mc',9,20,'E trouxeram-lho; e quando ele o viu, logo o espírito o agitou com violência, e, caindo o endemoninhado por terra, revolvia-se, escumando.'),
('acf','mc',9,21,'E perguntou ao pai dele: Quanto tempo há que lhe sucede isto? E ele disse-lhe: Desde a infância.'),
('acf','mc',9,22,'E muitas vezes o tem lançado no fogo, e na água, para o destruir; mas, se tu podes fazer alguma coisa, tem compaixão de nós, e ajuda-nos.'),
('acf','mc',9,23,'E Jesus disse-lhe: Se tu podes crer, tudo é possível ao que crê.'),
('acf','mc',9,24,'E logo o pai do menino, clamando, com lágrimas, disse: Eu creio, Senhor! ajuda a minha incredulidade.'),
('acf','mc',9,25,'E Jesus, vendo que a multidão concorria, repreendeu o espírito imundo, dizendo-lhe: Espírito mudo e surdo, eu te ordeno: Sai dele, e não entres mais nele.'),
('acf','mc',9,26,'E ele, clamando, e agitando-o com violência, saiu; e ficou o menino como morto, de tal maneira que muitos diziam que estava morto.'),
('acf','mc',9,27,'Mas Jesus, tomando-o pela mão, o ergueu, e ele se levantou.'),
('acf','mc',9,28,'E, quando entrou em casa, os seus discípulos lhe perguntaram à parte: Por que o não pudemos nós expulsar?'),
('acf','mc',9,29,'E disse-lhes: Esta casta não pode sair com coisa alguma, a não ser com oração e jejum.'),
('acf','mc',9,30,'E, tendo partido dali, caminharam pela Galiléia, e não queria que alguém o soubesse;'),
('acf','mc',9,31,'Porque ensinava os seus discípulos, e lhes dizia: O Filho do homem será entregue nas mãos dos homens, e matá-lo-ão; e, morto ele, ressuscitará ao terceiro dia.'),
('acf','mc',9,32,'Mas eles não entendiam esta palavra, e receavam interrogá-lo.'),
('acf','mc',9,33,'E chegou a Cafarnaum e, entrando em casa, perguntou-lhes: Que estáveis vós discutindo pelo caminho?'),
('acf','mc',9,34,'Mas eles calaram-se; porque pelo caminho tinham disputado entre si qual era o maior.'),
('acf','mc',9,35,'E ele, assentando-se, chamou os doze, e disse-lhes: Se alguém quiser ser o primeiro, será o derradeiro de todos e o servo de todos.'),
('acf','mc',9,36,'E, lançando mão de um menino, pô-lo no meio deles e, tomando-o nos seus braços, disse-lhes:'),
('acf','mc',9,37,'Qualquer que receber um destes meninos em meu nome, a mim me recebe; e qualquer que a mim me receber, recebe, não a mim, mas ao que me enviou.'),
('acf','mc',9,38,'E João lhe respondeu, dizendo: Mestre, vimos um que em teu nome expulsava demônios, o qual não nos segue; e nós lho proibimos, porque não nos segue.'),
('acf','mc',9,39,'Jesus, porém, disse: Não lho proibais; porque ninguém há que faça milagre em meu nome e possa logo falar mal de mim.'),
('acf','mc',9,40,'Porque quem não é contra nós, é por nós.'),
('acf','mc',9,41,'Porquanto, qualquer que vos der a beber um copo de água em meu nome, porque sois discípulos de Cristo, em verdade vos digo que não perderá o seu galardão.'),
('acf','mc',9,42,'E qualquer que escandalizar um destes pequeninos que crêem em mim, melhor lhe fora que lhe pusessem ao pescoço uma mó de atafona, e que fosse lançado no mar.'),
('acf','mc',9,43,'E, se a tua mão te escandalizar, corta-a; melhor é para ti entrares na vida aleijado do que, tendo duas mãos, ires para o inferno, para o fogo que nunca se apaga,'),
('acf','mc',9,44,'Onde o seu bicho não morre, e o fogo nunca se apaga.'),
('acf','mc',9,45,'E, se o teu pé te escandalizar, corta-o; melhor é para ti entrares coxo na vida do que, tendo dois pés, seres lançado no inferno, no fogo que nunca se apaga,'),
('acf','mc',9,46,'Onde o seu bicho não morre, e o fogo nunca se apaga.'),
('acf','mc',9,47,'E, se o teu olho te escandalizar, lança-o fora; melhor é para ti entrares no reino de Deus com um só olho do que, tendo dois olhos, seres lançado no fogo do inferno,'),
('acf','mc',9,48,'Onde o seu bicho não morre, e o fogo nunca se apaga.'),
('acf','mc',9,49,'Porque cada um será salgado com fogo, e cada sacrifício será salgado com sal.'),
('acf','mc',9,50,'Bom é o sal; mas, se o sal se tornar insípido, com que o temperareis? Tende sal em vós mesmos, e paz uns com os outros.'),
('acf','mc',10,1,'E, levantando-se dali, foi para os termos da Judéia, além do Jordão, e a multidão se reuniu em torno dele; e tornou a ensiná-los, como tinha por costume.'),
('acf','mc',10,2,'E, aproximando-se dele os fariseus, perguntaram-lhe, tentando-o: É lícito ao homem repudiar sua mulher?'),
('acf','mc',10,3,'Mas ele, respondendo, disse-lhes: Que vos mandou Moisés?'),
('acf','mc',10,4,'E eles disseram: Moisés permitiu escrever carta de divórcio e repudiar.'),
('acf','mc',10,5,'E Jesus, respondendo, disse-lhes: Pela dureza dos vossos corações vos deixou ele escrito esse mandamento;'),
('acf','mc',10,6,'Porém, desde o princípio da criação, Deus os fez macho e fêmea.'),
('acf','mc',10,7,'Por isso deixará o homem a seu pai e a sua mãe, e unir-se-á a sua mulher,'),
('acf','mc',10,8,'E serão os dois uma só carne; e assim já não serão dois, mas uma só carne.'),
('acf','mc',10,9,'Portanto, o que Deus ajuntou não o separe o homem.'),
('acf','mc',10,10,'E em casa tornaram os discípulos a interrogá-lo acerca disto mesmo.'),
('acf','mc',10,11,'E ele lhes disse: Qualquer que deixar a sua mulher e casar com outra, adultera contra ela.'),
('acf','mc',10,12,'E, se a mulher deixar a seu marido, e casar com outro, adultera.'),
('acf','mc',10,13,'E traziam-lhe meninos para que lhes tocasse, mas os discípulos repreendiam aos que lhos traziam.'),
('acf','mc',10,14,'Jesus, porém, vendo isto, indignou-se, e disse-lhes: Deixai vir os meninos a mim, e não os impeçais; porque dos tais é o reino de Deus.'),
('acf','mc',10,15,'Em verdade vos digo que qualquer que não receber o reino de Deus como menino, de maneira nenhuma entrará nele.'),
('acf','mc',10,16,'E, tomando-os nos seus braços, e impondo-lhes as mãos, os abençoou.'),
('acf','mc',10,17,'E, pondo-se a caminho, correu para ele um homem, o qual se ajoelhou diante dele, e lhe perguntou: Bom Mestre, que farei para herdar a vida eterna?'),
('acf','mc',10,18,'E Jesus lhe disse: Por que me chamas bom? Ninguém há bom senão um, que é Deus.'),
('acf','mc',10,19,'Tu sabes os mandamentos: Não adulterarás; não matarás; não furtarás; não dirás falso testemunho; não defraudarás alguém; honra a teu pai e a tua mãe.'),
('acf','mc',10,20,'Ele, porém, respondendo, lhe disse: Mestre, tudo isso guardei desde a minha mocidade.'),
('acf','mc',10,21,'E Jesus, olhando para ele, o amou e lhe disse: Falta-te uma coisa: vai, vende tudo quanto tens, e dá-o aos pobres, e terás um tesouro no céu; e vem, toma a cruz, e segue-me.'),
('acf','mc',10,22,'Mas ele, pesaroso desta palavra, retirou-se triste; porque possuía muitas propriedades.'),
('acf','mc',10,23,'Então Jesus, olhando em redor, disse aos seus discípulos: Quão dificilmente entrarão no reino de Deus os que têm riquezas!'),
('acf','mc',10,24,'E os discípulos se admiraram destas suas palavras; mas Jesus, tornando a falar, disse-lhes: Filhos, quão difícil é, para os que confiam nas riquezas, entrar no reino de Deus!'),
('acf','mc',10,25,'É mais fácil passar um camelo pelo fundo de uma agulha, do que entrar um rico no reino de Deus.'),
('acf','mc',10,26,'E eles se admiravam ainda mais, dizendo entre si: Quem poderá, pois, salvar-se?'),
('acf','mc',10,27,'Jesus, porém, olhando para eles, disse: Para os homens é impossível, mas não para Deus, porque para Deus todas as coisas são possíveis.'),
('acf','mc',10,28,'E Pedro começou a dizer-lhe: Eis que nós tudo deixamos, e te seguimos.'),
('acf','mc',10,29,'E Jesus, respondendo, disse: Em verdade vos digo que ninguém há, que tenha deixado casa, ou irmãos, ou irmãs, ou pai, ou mãe, ou mulher, ou filhos, ou campos, por amor de mim e do evangelho,'),
('acf','mc',10,30,'Que não receba cem vezes tanto, já neste tempo, em casas, e irmãos, e irmãs, e mães, e filhos, e campos, com perseguições; e no século futuro a vida eterna.'),
('acf','mc',10,31,'Porém muitos primeiros serão derradeiros, e muitos derradeiros serão primeiros.'),
('acf','mc',10,32,'E iam no caminho, subindo para Jerusalém; e Jesus ia adiante deles. E eles maravilhavam-se, e seguiam-no atemorizados.  E, tornando a tomar consigo os doze, começou a dizer-lhes as coisas que lhe deviam sobrevir,'),
('acf','mc',10,33,'Dizendo: Eis que nós subimos a Jerusalém, e o Filho do homem será entregue aos príncipes dos sacerdotes, e aos escribas, e o condenarão à morte, e o entregarão aos gentios.'),
('acf','mc',10,34,'E o escarnecerão, e açoitarão, e cuspirão nele, e o matarão; e, ao terceiro dia, ressuscitará.'),
('acf','mc',10,35,'E aproximaram-se dele Tiago e João, filhos de Zebedeu, dizendo: Mestre, queremos que nos faças o que te pedirmos.'),
('acf','mc',10,36,'E ele lhes disse: Que quereis que vos faça?'),
('acf','mc',10,37,'E eles lhe disseram: Concede-nos que na tua glória nos assentemos, um à tua direita, e outro à tua esquerda.'),
('acf','mc',10,38,'Mas Jesus lhes disse: Não sabeis o que pedis; podeis vós beber o cálice que eu bebo, e ser batizados com o batismo com que eu sou batizado?'),
('acf','mc',10,39,'E eles lhe disseram: Podemos. Jesus, porém, disse-lhes: Em verdade, vós bebereis o cálice que eu beber, e sereis batizados com o batismo com que eu sou batizado;'),
('acf','mc',10,40,'Mas, o assentar-se à minha direita, ou à minha esquerda, não me pertence a mim concedê-lo, mas isso é para aqueles a quem está reservado.'),
('acf','mc',10,41,'E os dez, tendo ouvido isto, começaram a indignar-se contra Tiago e João.'),
('acf','mc',10,42,'Mas Jesus, chamando-os a si, disse-lhes: Sabeis que os que julgam ser príncipes dos gentios, deles se assenhoreiam, e os seus grandes usam de autoridade sobre eles;'),
('acf','mc',10,43,'Mas entre vós não será assim; antes, qualquer que entre vós quiser ser grande, será vosso serviçal;'),
('acf','mc',10,44,'E qualquer que dentre vós quiser ser o primeiro, será servo de todos.'),
('acf','mc',10,45,'Porque o Filho do homem também não veio para ser servido, mas para servir e dar a sua vida em resgate de muitos.'),
('acf','mc',10,46,'E depois, foram para Jericó. E, saindo ele de Jericó com seus discípulos e uma grande multidão, Bartimeu, o cego, filho de Timeu, estava assentado junto do caminho, mendigando.'),
('acf','mc',10,47,'E, ouvindo que era Jesus de Nazaré, começou a clamar, e a dizer: Jesus, filho de Davi, tem misericórdia de mim.'),
('acf','mc',10,48,'E muitos o repreendiam, para que se calasse; mas ele clamava cada vez mais: Filho de Davi! tem misericórdia de mim.'),
('acf','mc',10,49,'E Jesus, parando, disse que o chamassem; e chamaram o cego, dizendo-lhe: Tem bom ânimo; levanta-te, que ele te chama.'),
('acf','mc',10,50,'E ele, lançando de si a sua capa, levantou-se, e foi ter com Jesus.'),
('acf','mc',10,51,'E Jesus, falando, disse-lhe: Que queres que te faça? E o cego lhe disse: Mestre, que eu tenha vista.'),
('acf','mc',10,52,'E Jesus lhe disse: Vai, a tua fé te salvou. E logo viu, e seguiu a Jesus pelo caminho.'),
('acf','mc',11,1,'E, logo que se aproximaram de Jerusalém, de Betfagé e de Betânia, junto do Monte das Oliveiras, enviou dois dos seus discípulos,'),
('acf','mc',11,2,'E disse-lhes: Ide à aldeia que está defronte de vós; e, logo que ali entrardes, encontrareis preso um jumentinho, sobre o qual ainda não montou homem algum; soltai-o, e trazei-mo.'),
('acf','mc',11,3,'E, se alguém vos disser: Por que fazeis isso? dizei-lhe que o Senhor precisa dele, e logo o deixará trazer para aqui.'),
('acf','mc',11,4,'E foram, e encontraram o jumentinho preso fora da porta, entre dois caminhos, e o soltaram.'),
('acf','mc',11,5,'E alguns dos que ali estavam lhes disseram: Que fazeis, soltando o jumentinho?'),
('acf','mc',11,6,'Eles, porém, disseram-lhes como Jesus lhes tinha mandado; e deixaram-nos ir.'),
('acf','mc',11,7,'E levaram o jumentinho a Jesus, e lançaram sobre ele as suas vestes, e assentou-se sobre ele.'),
('acf','mc',11,8,'E muitos estendiam as suas vestes pelo caminho, e outros cortavam ramos das árvores, e os espalhavam pelo caminho.'),
('acf','mc',11,9,'E aqueles que iam adiante, e os que seguiam, clamavam, dizendo: Hosana, bendito o que vem em nome do Senhor;'),
('acf','mc',11,10,'Bendito o reino do nosso pai Davi, que vem em nome do Senhor. Hosana nas alturas.'),
('acf','mc',11,11,'E Jesus entrou em Jerusalém, no templo, e, tendo visto tudo em redor, como fosse já tarde, saiu para Betânia com os doze.'),
('acf','mc',11,12,'E, no dia seguinte, quando saíram de Betânia, teve fome.'),
('acf','mc',11,13,'E, vendo de longe uma figueira que tinha folhas, foi ver se nela acharia alguma coisa; e, chegando a ela, não achou senão folhas, porque não era tempo de figos.'),
('acf','mc',11,14,'E Jesus, falando, disse à figueira: Nunca mais coma alguém fruto de ti. E os seus discípulos ouviram isto.'),
('acf','mc',11,15,'E vieram a Jerusalém; e Jesus, entrando no templo, começou a expulsar os que vendiam e compravam no templo; e derrubou as mesas dos cambiadores e as cadeiras dos que vendiam pombas.'),
('acf','mc',11,16,'E não consentia que alguém levasse algum vaso pelo templo.'),
('acf','mc',11,17,'E os ensinava, dizendo: Não está escrito: A minha casa será chamada, por todas as nações, casa de oração? Mas vós a tendes feito covil de ladrões.'),
('acf','mc',11,18,'E os escribas e príncipes dos sacerdotes, tendo ouvido isto, buscavam ocasião para o matar; pois eles o temiam, porque toda a multidão estava admirada acerca da sua doutrina.'),
('acf','mc',11,19,'E, sendo já tarde, saiu para fora da cidade.'),
('acf','mc',11,20,'E eles, passando pela manhã, viram que a figueira se tinha secado desde as raízes.'),
('acf','mc',11,21,'E Pedro, lembrando-se, disse-lhe: Mestre, eis que a figueira, que tu amaldiçoaste, se secou.'),
('acf','mc',11,22,'E Jesus, respondendo, disse-lhes: Tende fé em Deus;'),
('acf','mc',11,23,'Porque em verdade vos digo que qualquer que disser a este monte: Ergue-te e lança-te no mar, e não duvidar em seu coração, mas crer que se fará aquilo que diz, tudo o que disser lhe será feito.'),
('acf','mc',11,24,'Por isso vos digo que todas as coisas que pedirdes, orando, crede receber, e tê-las-eis.'),
('acf','mc',11,25,'E, quando estiverdes orando, perdoai, se tendes alguma coisa contra alguém, para que vosso Pai, que está nos céus, vos perdoe as vossas ofensas.'),
('acf','mc',11,26,'Mas, se vós não perdoardes, também vosso Pai, que está nos céus, vos não perdoará as vossas ofensas.'),
('acf','mc',11,27,'E tornaram a Jerusalém, e, andando ele pelo templo, os principais dos sacerdotes, e os escribas, e os anciãos, se aproximaram dele.'),
('acf','mc',11,28,'E lhe disseram: Com que autoridade fazes tu estas coisas? ou quem te deu tal autoridade para fazer estas coisas?'),
('acf','mc',11,29,'Mas Jesus, respondendo, disse-lhes: Também eu vos perguntarei uma coisa, e respondei-me; e então vos direi com que autoridade faço estas coisas:'),
('acf','mc',11,30,'O batismo de João era do céu ou dos homens? respondei-me.'),
('acf','mc',11,31,'E eles arrazoavam entre si, dizendo: Se dissermos: Do céu, ele nos dirá: Então por que o não crestes?'),
('acf','mc',11,32,'Se, porém, dissermos: Dos homens, tememos o povo. Porque todos sustentavam que João verdadeiramente era profeta.'),
('acf','mc',11,33,'E, respondendo, disseram a Jesus: Não sabemos. E Jesus lhes replicou: Também eu vos não direi com que autoridade faço estas coisas.'),
('acf','mc',12,1,'E começou a falar-lhes por parábolas: Um homem plantou uma vinha, e cercou-a de um valado, e fundou nela um lagar, e edificou uma torre, e arrendou-a a uns lavradores, e partiu para fora da terra.'),
('acf','mc',12,2,'E, chegado o tempo, mandou um servo aos lavradores para que recebesse, dos lavradores, do fruto da vinha.'),
('acf','mc',12,3,'Mas estes, apoderando-se dele, o feriram e o mandaram embora vazio.'),
('acf','mc',12,4,'E tornou a enviar-lhes outro servo; e eles, apedrejando-o, o feriram na cabeça, e o mandaram embora, tendo-o afrontado.'),
('acf','mc',12,5,'E tornou a enviar-lhes outro, e a este mataram; e a outros muitos, dos quais a uns feriram e a outros mataram.'),
('acf','mc',12,6,'Tendo ele, pois, ainda um seu filho amado, enviou-o também a estes por derradeiro, dizendo: Ao menos terão respeito ao meu filho.'),
('acf','mc',12,7,'Mas aqueles lavradores disseram entre si: Este é o herdeiro; vamos, matemo-lo, e a herança será nossa.'),
('acf','mc',12,8,'E, pegando dele, o mataram, e o lançaram fora da vinha.'),
('acf','mc',12,9,'Que fará, pois, o senhor da vinha? Virá, e destruirá os lavradores, e dará a vinha a outros.'),
('acf','mc',12,10,'Ainda não lestes esta Escritura:A pedra, que os edificadores rejeitaram,Esta foi posta por cabeça de esquina;'),
('acf','mc',12,11,'Isto foi feito pelo Senhor E é coisa maravilhosa aos nossos olhos?'),
('acf','mc',12,12,'E buscavam prendê-lo, mas temiam a multidão; porque entendiam que contra eles dizia esta parábola; e, deixando-o, foram-se.'),
('acf','mc',12,13,'E enviaram-lhe alguns dos fariseus e dos herodianos, para que o apanhassem nalguma palavra.'),
('acf','mc',12,14,'E, chegando eles, disseram-lhe: Mestre, sabemos que és homem de verdade, e de ninguém se te dá, porque não olhas à aparência dos homens, antes com verdade ensinas o caminho de Deus; é lícito dar o tributo a César, ou não? Daremos, ou não daremos?'),
('acf','mc',12,15,'Então ele, conhecendo a sua hipocrisia, disse-lhes: Por que me tentais? Trazei-me uma moeda, para que a veja.'),
('acf','mc',12,16,'E eles lha trouxeram. E disse-lhes: De quem é esta imagem e inscrição? E eles lhe disseram: De César.'),
('acf','mc',12,17,'E Jesus, respondendo, disse-lhes: Dai pois a César o que é de César, e a Deus o que é de Deus. E maravilharam-se dele.'),
('acf','mc',12,18,'Então os saduceus, que dizem que não há ressurreição, aproximaram-se dele, e perguntaram-lhe, dizendo:'),
('acf','mc',12,19,'Mestre, Moisés nos escreveu que, se morresse o irmão de alguém, e deixasse a mulher e não deixasse filhos, seu irmão tomasse a mulher dele, e suscitasse descendência a seu irmão.'),
('acf','mc',12,20,'Ora, havia sete irmãos, e o primeiro tomou a mulher, e morreu sem deixar descendência;'),
('acf','mc',12,21,'E o segundo também a tomou e morreu, e nem este deixou descendência; e o terceiro da mesma maneira.'),
('acf','mc',12,22,'E tomaram-na os sete, sem, contudo, terem deixado descendência. Finalmente, depois de todos, morreu também a mulher.'),
('acf','mc',12,23,'Na ressurreição, pois, quando ressuscitarem, de qual destes será a mulher? porque os sete a tiveram por mulher.'),
('acf','mc',12,24,'E Jesus, respondendo, disse-lhes: Porventura não errais vós em razão de não saberdes as Escrituras nem o poder de Deus?'),
('acf','mc',12,25,'Porquanto, quando ressuscitarem dentre os mortos, nem casarão, nem se darão em casamento, mas serão como os anjos que estão nos céus.'),
('acf','mc',12,26,'E, acerca dos mortos que houverem de ressuscitar, não tendes lido no livro de Moisés como Deus lhe falou na sarça, dizendo: Eu sou o Deus de Abraão, e o Deus de Isaque, e o Deus de Jacó?'),
('acf','mc',12,27,'Ora, Deus não é de mortos, mas sim, é Deus de vivos. Por isso vós errais muito.'),
('acf','mc',12,28,'Aproximou-se dele um dos escribas que os tinha ouvido disputar, e sabendo que lhes tinha respondido bem, perguntou-lhe: Qual é o primeiro de todos os mandamentos?'),
('acf','mc',12,29,'E Jesus respondeu-lhe: O primeiro de todos os mandamentos é: Ouve, Israel, o Senhor nosso Deus é o único Senhor.'),
('acf','mc',12,30,'Amarás, pois, ao Senhor teu Deus de todo o teu coração, e de toda a tua alma, e de todo o teu entendimento, e de todas as tuas forças; este é o primeiro mandamento.'),
('acf','mc',12,31,'E o segundo, semelhante a este, é: Amarás o teu próximo como a ti mesmo. Não há outro mandamento maior do que estes.'),
('acf','mc',12,32,'E o escriba lhe disse: Muito bem, Mestre, e com verdade disseste que há um só Deus, e que não há outro além dele;'),
('acf','mc',12,33,'E que amá-lo de todo o coração, e de todo o entendimento, e de toda a alma, e de todas as forças, e amar o próximo como a si mesmo, é mais do que todos os holocaustos e sacrifícios.'),
('acf','mc',12,34,'E Jesus, vendo que havia respondido sabiamente, disse-lhe: Não estás longe do reino de Deus. E já ninguém ousava perguntar-lhe mais nada.'),
('acf','mc',12,35,'E, falando Jesus, dizia, ensinando no templo: Como dizem os escribas que o Cristo é filho de Davi?'),
('acf','mc',12,36,'O próprio Davi disse pelo Espírito Santo:O Senhor disse ao meu Senhor:Assenta-te à minha direita Até que eu ponha os teus inimigos por escabelo dos teus pés.'),
('acf','mc',12,37,'Pois, se Davi mesmo lhe chama Senhor, como é logo seu filho? E a grande multidão o ouvia de boa vontade.'),
('acf','mc',12,38,'E, ensinando-os, dizia-lhes: Guardai-vos dos escribas, que gostam de andar com vestes compridas, e das saudações nas praças,'),
('acf','mc',12,39,'E das primeiras cadeiras nas sinagogas, e dos primeiros assentos nas ceias;'),
('acf','mc',12,40,'Que devoram as casas das viúvas, e isso com pretexto de largas orações. Estes receberão mais grave condenação.'),
('acf','mc',12,41,'E, estando Jesus assentado defronte da arca do tesouro, observava a maneira como a multidão lançava o dinheiro na arca do tesouro; e muitos ricos deitavam muito.'),
('acf','mc',12,42,'Vindo, porém, uma pobre viúva, deitou duas pequenas moedas, que valiam meio centavo.'),
('acf','mc',12,43,'E, chamando os seus discípulos, disse-lhes: Em verdade vos digo que esta pobre viúva deitou mais do que todos os que deitaram na arca do tesouro;'),
('acf','mc',12,44,'Porque todos ali deitaram do que lhes sobejava, mas esta, da sua pobreza, deitou tudo o que tinha, todo o seu sustento.'),
('acf','mc',13,1,'E, saindo ele do templo, disse-lhe um dos seus discípulos: Mestre, olha que pedras, e que edifícios!'),
('acf','mc',13,2,'E, respondendo Jesus, disse-lhe: Vês estes grandes edifícios? Não ficará pedra sobre pedra que não seja derrubada.'),
('acf','mc',13,3,'E, assentando-se ele no Monte das Oliveiras, defronte do templo, Pedro, e Tiago, e João e André lhe perguntaram em particular:'),
('acf','mc',13,4,'Dize-nos, quando serão essas coisas, e que sinal haverá quando todas elas estiverem para se cumprir.'),
('acf','mc',13,5,'E Jesus, respondendo-lhes, começou a dizer: Olhai que ninguém vos engane;'),
('acf','mc',13,6,'Porque muitos virão em meu nome, dizendo: Eu sou o Cristo; e enganarão a muitos.'),
('acf','mc',13,7,'E, quando ouvirdes de guerras e de rumores de guerras, não vos perturbeis; porque assim deve acontecer; mas ainda não será o fim.'),
('acf','mc',13,8,'Porque se levantará nação contra nação, e reino contra reino, e haverá terremotos em diversos lugares, e haverá fomes e tribulações. Estas coisas sào os princípios das dores.'),
('acf','mc',13,9,'Mas olhai por vós mesmos, porque vos entregarão aos concílios e às sinagogas; e sereis açoitados, e sereis apresentados perante presidentes e reis, por amor de mim, para lhes servir de testemunho.'),
('acf','mc',13,10,'Mas importa que o evangelho seja primeiramente pregado entre todas as nações.'),
('acf','mc',13,11,'Quando, pois, vos conduzirem e vos entregarem, não estejais solícitos de antemão pelo que haveis de dizer, nem premediteis; mas, o que vos for dado naquela hora, isso falai, porque não sois vós os que falais, mas o Espírito Santo.'),
('acf','mc',13,12,'E o irmão entregará à morte o irmão, e o pai ao filho; e levantar-se-ão os filhos contra os pais, e os farão morrer.'),
('acf','mc',13,13,'E sereis odiados por todos por amor do meu nome; mas quem perseverar até ao fim, esse será salvo.'),
('acf','mc',13,14,'Ora, quando vós virdes a abominação do assolamento, que foi predita por Daniel o profeta, estar onde não deve estar (quem lê, entenda), então os que estiverem na Judéia fujam para os montes.'),
('acf','mc',13,15,'E o que estiver sobre o telhado não desça para casa, nem entre a tomar coisa alguma de sua casa;'),
('acf','mc',13,16,'E o que estiver no campo não volte atrás, para tomar as suas vestes.'),
('acf','mc',13,17,'Mas ai das grávidas, e das que criarem naqueles dias!'),
('acf','mc',13,18,'Orai, pois, para que a vossa fuga não suceda no inverno.'),
('acf','mc',13,19,'Porque naqueles dias haverá uma aflição tal, qual nunca houve desde o princípio da criação, que Deus criou, até agora, nem jamais haverá.'),
('acf','mc',13,20,'E, se o Senhor não abreviasse aqueles dias, nenhuma carne se salvaria; mas, por causa dos eleitosque escolheu, abreviou aqueles dias.'),
('acf','mc',13,21,'E então, se alguém vos disser: Eis aqui o Cristo; ou: Ei-lo ali; não acrediteis.'),
('acf','mc',13,22,'Porque se levantarão falsos cristos, e falsos profetas, e farão sinais e prodígios, para enganarem, se for possível, até os escolhidos.'),
('acf','mc',13,23,'Mas vós vede; eis que de antemão vos tenho dito tudo.'),
('acf','mc',13,24,'Ora, naqueles dias, depois daquela aflição, o sol se escurecerá, e a lua não dará a sua luz.'),
('acf','mc',13,25,'E as estrelas cairão do céu, e as forças que estão nos céus serão abaladas.'),
('acf','mc',13,26,'E então verão vir o Filho do homem nas nuvens, com grande poder e glória.'),
('acf','mc',13,27,'E ele enviará os seus anjos, e ajuntará os seus escolhidos, desde os quatro ventos, da extremidade da terra até a extremidade do céu.'),
('acf','mc',13,28,'Aprendei, pois, a parábola da figueira: Quando já o seu ramo se torna tenro, e brota folhas, bem sabeis que já está próximo o verão.'),
('acf','mc',13,29,'Assim também vós, quando virdes sucederem estas coisas, sabei que já está perto, às portas.'),
('acf','mc',13,30,'Na verdade vos digo que não passará esta geração, sem que todas estas coisas aconteçam.'),
('acf','mc',13,31,'Passará o céu e a terra, mas as minhas palavras não passarão.'),
('acf','mc',13,32,'Mas daquele dia e hora ninguém sabe, nem os anjos que estão no céu, nem o Filho, senão o Pai.'),
('acf','mc',13,33,'Olhai, vigiai e orai; porque não sabeis quando chegará o tempo.'),
('acf','mc',13,34,'É como se um homem, partindo para fora da terra, deixasse a sua casa, e desse autoridade aos seus servos, e a cada um a sua obra, e mandasse ao porteiro que vigiasse.'),
('acf','mc',13,35,'Vigiai, pois, porque não sabeis quando virá o senhor da casa; se à tarde, se à meia-noite, se ao cantar do galo, se pela manhã,'),
('acf','mc',13,36,'Para que, vindo de improviso, não vos ache dormindo.'),
('acf','mc',13,37,'E as coisas que vos digo, digo-as a todos: Vigiai.'),
('acf','mc',14,1,'E dali a dois dias era a páscoa, e a festa dos pães ázimos; e os principais dos sacerdotes e os escribas buscavam como o prenderiam com dolo, e o matariam.'),
('acf','mc',14,2,'Mas eles diziam: Não na festa, para que porventura não se faça alvoroço entre o povo.'),
('acf','mc',14,3,'E, estando ele em betânia, assentado à mesa, em casa de Simão, o leproso, veio uma mulher, que trazia um vaso de alabastro, com ungüento de nardo puro, de muito preço, e quebrando o vaso, lho derramou sobre a cabeça.'),
('acf','mc',14,4,'E alguns houve que em si mesmos se indignaram, e disseram: Para que se fez este desperdício de ungüento?'),
('acf','mc',14,5,'Porque podia vender-se por mais de trezentos dinheiros, e dá-lo aos pobres. E bramavam contra ela.'),
('acf','mc',14,6,'Jesus, porém, disse: Deixai-a, por que a molestais? Ela fez-me boa obra.'),
('acf','mc',14,7,'Porque sempre tendes os pobres convosco, e podeis fazer-lhes bem, quando quiserdes; mas a mim nem sempre me tendes.'),
('acf','mc',14,8,'Esta fez o que podia; antecipou-se a ungir o meu corpo para a sepultura.'),
('acf','mc',14,9,'Em verdade vos digo que, em todas as partes do mundo onde este evangelho for pregado, também o que ela fez será contado para sua memória.'),
('acf','mc',14,10,'E Judas Iscariotes, um dos doze, foi ter com os principais dos sacerdotes para lho entregar.'),
('acf','mc',14,11,'E eles, ouvindo-o, folgaram, e prometeram dar-lhe dinheiro; e buscava como o entregaria em ocasião oportuna.'),
('acf','mc',14,12,'E, no primeiro dia dos pães ázimos, quando sacrificavam a páscoa, disseram-lhe os discípulos: Aonde queres que vamos fazer os preparativos para comer a páscoa?'),
('acf','mc',14,13,'E enviou dois dos seus discípulos, e disse-lhes: Ide à cidade, e um homem, que leva um cântaro de água, vos encontrará; segui-o.'),
('acf','mc',14,14,'E, onde quer que entrar, dizei ao senhor da casa: O Mestre diz: Onde está o aposento em que hei de comer a páscoa com os meus discípulos?'),
('acf','mc',14,15,'E ele vos mostrará um grande cenáculo mobilado e preparado; preparai-a ali.'),
('acf','mc',14,16,'E, saindo os seus discípulos, foram à cidade, e acharam como lhes tinha dito, e prepararam a páscoa.'),
('acf','mc',14,17,'E, chegada a tarde, foi com os doze.'),
('acf','mc',14,18,'E, quando estavam assentados a comer, disse Jesus: Em verdade vos digo que um de vós, que comigo come, há de trair-me.'),
('acf','mc',14,19,'E eles começaram a entristecer-se e a dizer-lhe um após outro: Sou eu? E outro disse: Sou eu?'),
('acf','mc',14,20,'Mas ele, respondendo, disse-lhes: É um dos doze, que põe comigo a mão no prato.'),
('acf','mc',14,21,'Na verdade o Filho do homem vai, como dele está escrito, mas ai daquele homem por quem o Filho do homem é traído! Bom seria para o tal homem não haver nascido.'),
('acf','mc',14,22,'E, comendo eles, tomou Jesus pão e, abençoando-o, o partiu e deu-lho, e disse: Tomai, comei, isto é o meu corpo.'),
('acf','mc',14,23,'E, tomando o cálice, e dando graças, deu-lho; e todos beberam dele.'),
('acf','mc',14,24,'E disse-lhes: Isto é o meu sangue, o sangue do novo testamento, que por muitos é derramado.'),
('acf','mc',14,25,'Em verdade vos digo que não beberei mais do fruto da vide, até àquele dia em que o beber, novo, no reino de Deus.'),
('acf','mc',14,26,'E, tendo cantado o hino, saíram para o Monte das Oliveiras.'),
('acf','mc',14,27,'E disse-lhes Jesus: Todos vós esta noite vos escandalizareis em mim; porque está escrito: Ferirei o pastor, e as ovelhas se dispersarão.'),
('acf','mc',14,28,'Mas, depois que eu houver ressuscitado, irei adiante de vós para a Galiléia.'),
('acf','mc',14,29,'E disse-lhe Pedro: Ainda que todos se escandalizem, nunca, porém, eu.'),
('acf','mc',14,30,'E disse-lhe Jesus: Em verdade te digo que hoje, nesta noite, antes que o galo cante duas vezes, três vezes me negarás.'),
('acf','mc',14,31,'Mas ele disse com mais veemência: Ainda que me seja necessário morrer contigo, de modo nenhum te negarei. E da mesma maneira diziam todos também.'),
('acf','mc',14,32,'E foram a um lugar chamado Getsêmani, e disse aos seus discípulos: Assentai-vos aqui, enquanto eu oro.'),
('acf','mc',14,33,'E tomou consigo a Pedro, e a Tiago, e a João, e começou a ter pavor, e a angustiar-se.'),
('acf','mc',14,34,'E disse-lhes: A minha alma está profundamente triste até a morte; ficai aqui, e vigiai.'),
('acf','mc',14,35,'E, tendo ido um pouco mais adiante, prostrou-se em terra; e orou para que, se fosse possível, passasse dele aquela hora.'),
('acf','mc',14,36,'E disse: Aba, Pai, todas as coisas te são possíveis; afasta de mim este cálice; não seja, porém, o que eu quero, mas o que tu queres.'),
('acf','mc',14,37,'E, chegando, achou-os dormindo; e disse a Pedro: Simão, dormes? não podes vigiar uma hora?'),
('acf','mc',14,38,'Vigiai e orai, para que não entreis em tentação; o espírito, na verdade, está pronto, mas a carne é fraca.'),
('acf','mc',14,39,'E foi outra vez e orou, dizendo as mesmas palavras.'),
('acf','mc',14,40,'E, voltando, achou-os outra vez dormindo, porque os seus olhos estavam pesados, e não sabiam o que responder-lhe.'),
('acf','mc',14,41,'E voltou terceira vez, e disse-lhes: Dormi agora, e descansai. Basta; é chegada a hora.  Eis que o Filho do homem vai ser entregue nas mãos dos pecadores.'),
('acf','mc',14,42,'Levantai-vos, vamos; eis que está perto o que me trai.'),
('acf','mc',14,43,'E logo, falando ele ainda, veio Judas, que era um dos doze, da parte dos principais dos sacerdotes, e dos escribas e dos anciãos, e com ele uma grande multidão com espadas e varapaus.'),
('acf','mc',14,44,'Ora, o que o traía, tinha-lhes dado um sinal, dizendo: Aquele que eu beijar, esse é; prendei-o, e levai-o com segurança.'),
('acf','mc',14,45,'E, logo que chegou, aproximou-se dele, e disse-lhe: Rabi, Rabi. E beijou-o.'),
('acf','mc',14,46,'E lançaram-lhe as mãos, e o prenderam.'),
('acf','mc',14,47,'E um dos que ali estavam presentes, puxando da espada, feriu o servo do sumo sacerdote, e cortou-lhe uma orelha.'),
('acf','mc',14,48,'E, respondendo Jesus, disse-lhes: Saístes com espadas e varapaus a prender-me, como a um salteador?'),
('acf','mc',14,49,'Todos os dias estava convosco ensinando no templo, e não me prendestes; mas isto é para que as Escrituras se cumpram.'),
('acf','mc',14,50,'Então, deixando-o, todos fugiram.'),
('acf','mc',14,51,'E um certo jovem o seguia, envolto em um lençol sobre o corpo nu. E lançaram-lhe a mão.'),
('acf','mc',14,52,'Mas ele, largando o lençol, fugiu nu. Jesus perante o Sinédrio. Negação de Pedro'),
('acf','mc',14,53,'E levaram Jesus ao sumo sacerdote, e ajuntaram-se todos os principais dos sacerdotes, e os anciãos e os escribas.'),
('acf','mc',14,54,'E Pedro o seguiu de longe até dentro do pátio do sumo sacerdote, e estava assentado com os servidores, aquentando-se ao lume.'),
('acf','mc',14,55,'E os principais dos sacerdotes e todo o concílio buscavam algum testemunho contra Jesus, para o matar, e não o achavam.'),
('acf','mc',14,56,'Porque muitos testificavam falsamente contra ele, mas os testemunhos não eram coerentes.'),
('acf','mc',14,57,'E, levantando-se alguns, testificaram falsamente contra ele, dizendo:'),
('acf','mc',14,58,'Nós ouvimos-lhe dizer: Eu derrubarei este templo, construído por mãos de homens, e em três dias edificarei outro, não feito por mãos de homens.'),
('acf','mc',14,59,'E nem assim o seu testemunho era coerente.'),
('acf','mc',14,60,'E, levantando-se o sumo sacerdote no Sinédrio, perguntou a Jesus, dizendo: Nada respondes? Que testificam estes contra ti?'),
('acf','mc',14,61,'Mas ele calou-se, e nada respondeu. O sumo sacerdote lhe tornou a perguntar, e disse-lhe: És tu o Cristo, Filho do Deus Bendito?'),
('acf','mc',14,62,'E Jesus disse-lhe: Eu o sou, e vereis o Filho do homem assentado à direita do poder de Deus, e vindo sobre as nuvens do céu.'),
('acf','mc',14,63,'E o sumo sacerdote, rasgando as suas vestes, disse: Para que necessitamos de mais testemunhas?'),
('acf','mc',14,64,'Vós ouvistes a blasfêmia; que vos parece? E todos o consideraram culpado de morte.'),
('acf','mc',14,65,'E alguns começaram a cuspir nele, e a cobrir-lhe o rosto, e a dar-lhe punhadas, e a dizer-lhe: Profetiza. E os servidores davam-lhe bofetadas.'),
('acf','mc',14,66,'E, estando Pedro embaixo, noátrio, chegou uma das criadas do sumo sacerdote;'),
('acf','mc',14,67,'E, vendo a Pedro, que se estava aquentando, olhou para ele, e disse: Tu também estavas com Jesus, o Nazareno.'),
('acf','mc',14,68,'Mas ele negou-o, dizendo: Não o conheço, nem sei o que dizes. E saiu fora ao alpendre, e o galo cantou.'),
('acf','mc',14,69,'E a criada, vendo-o outra vez, começou a dizer aos que ali estavam: Este é um dos tais.'),
('acf','mc',14,70,'Mas ele o negou outra vez. E pouco depois os que ali estavam disseram outra vez a Pedro: Verdadeiramente tu és um deles, porque és também galileu, e tua fala é semelhante.'),
('acf','mc',14,71,'E ele começou a praguejar, e a jurar: Não conheço esse homem de quem falais.'),
('acf','mc',14,72,'E o galo cantou segunda vez. E Pedro lembrou-se da palavra que Jesus lhe tinha dito: Antes que o galo cante duas vezes, três vezes me negarás.  E, retirando-se dali, chorou.'),
('acf','mc',15,1,'E, logo ao amanhecer, os principais dos sacerdotes, com os anciãos, e os escribas, e todo o Sinédrio, tiveram conselho; e, ligando Jesus, o levaram e entregaram a Pilatos.'),
('acf','mc',15,2,'E Pilatos lhe perguntou: Tu és o Rei dos Judeus? E ele, respondendo, disse-lhe: Tu o dizes.'),
('acf','mc',15,3,'E os principais dos sacerdotes o acusavam de muitas coisas; porém ele nada respondia.'),
('acf','mc',15,4,'E Pilatos o interrogou outra vez, dizendo: Nada respondes? Vê quantas coisas testificam contra ti.'),
('acf','mc',15,5,'Mas Jesus nada mais respondeu, de maneira que Pilatos se maravilhava.'),
('acf','mc',15,6,'Ora, no dia da festa costumava soltar-lhes um preso qualquer que eles pedissem.'),
('acf','mc',15,7,'E havia um chamado Barrabás, que, preso com outros amotinado- res, tinha num motim cometido uma morte.'),
('acf','mc',15,8,'E a multidão, dando gritos, começou a pedir que fizesse como sempre lhes tinha feito.'),
('acf','mc',15,9,'E Pilatos lhes respondeu, dizendo: Quereis que vos solte o Rei dos Judeus?'),
('acf','mc',15,10,'Porque ele bem sabia que por inveja os principais dos sacerdotes o tinham entregado.'),
('acf','mc',15,11,'Mas os principais dos sacerdotes incitaram a multidão para que fosse solto antes Barrabás.'),
('acf','mc',15,12,'E Pilatos, respondendo, lhes disse outra vez: Que quereis, pois, que faça daquele a quem chamais Rei dos Judeus?'),
('acf','mc',15,13,'E eles tornaram a clamar: Crucifica-o.'),
('acf','mc',15,14,'Mas Pilatos lhes disse: Mas que mal fez? E eles cada vez clamavam mais: Crucifica-o.'),
('acf','mc',15,15,'Então Pilatos, querendo satisfazer a multidão, soltou-lhe Barrabás e, açoitado Jesus, o entregou para ser crucificado.'),
('acf','mc',15,16,'E os soldados o levaram dentro à sala, que é a da audiência, e convocaram toda a coorte.'),
('acf','mc',15,17,'E vestiram-no de púrpura, e tecendo uma coroa de espinhos, lha puseram na cabeça.'),
('acf','mc',15,18,'E começaram a saudá-lo, dizendo: Salve, Rei dos Judeus!'),
('acf','mc',15,19,'E feriram-no na cabeça com uma cana, e cuspiram nele e, postos de joelhos, o adoraram.'),
('acf','mc',15,20,'E, havendo-o escarnecido, despiram-lhe a púrpura, e o vestiram com as suas próprias vestes; e o levaram para fora a fim de o crucificarem.'),
('acf','mc',15,21,'E constrangeram um certo Simão, cireneu, pai de Alexandre e de Rufo, que por ali passava, vindo do campo, a que levasse a cruz.'),
('acf','mc',15,22,'E levaram-no ao lugar doGólgota, que se traduz por lugar da Caveira.'),
('acf','mc',15,23,'E deram-lhe a beber vinho com mirra, mas ele não o tomou.'),
('acf','mc',15,24,'E, havendo-o crucificado, repartiram as suas vestes, lançando sobre elas sortes, para saber o que cada um levaria.'),
('acf','mc',15,25,'E era a hora terceira, e o crucificaram.'),
('acf','mc',15,26,'E por cima dele estava escrita a sua acusação: O REI DOS JUDEUS.'),
('acf','mc',15,27,'E crucificaram com ele dois salteadores, um à sua direita, e outro à esquerda.'),
('acf','mc',15,28,'E cumprindo-se a escritura que diz: E com os malfeitores foi contado.'),
('acf','mc',15,29,'E os que passavam blasfemavam dele, meneando as suas cabeças, e dizendo: Ah! tu que derrubas o templo, e em três dias o edificas,'),
('acf','mc',15,30,'Salva-te a ti mesmo, e desce da cruz.'),
('acf','mc',15,31,'E da mesma maneira também os principais dos sacerdotes, com os escribas, diziam uns para os outros, zombando: Salvou os outros, e não pode salvar-se a si mesmo.'),
('acf','mc',15,32,'O Cristo, o Rei de Israel, desça agora da cruz, para que o vejamos e acreditemos. Também os que com ele foram crucificados o injuriavam.'),
('acf','mc',15,33,'E, chegada a hora sexta, houve trevas sobre toda a terra até a hora nona.'),
('acf','mc',15,34,'E, à hora nona, Jesus exclamou com grande voz, dizendo: Eloí, Eloí, lamá sabactâni? que, traduzido, é: Deus meu, Deus meu, por que me desamparaste?'),
('acf','mc',15,35,'E alguns dos que ali estavam, ouvindo isto, diziam: Eis que chama por Elias.'),
('acf','mc',15,36,'E um deles correu a embeber uma esponja em vinagre e, pondo-a numa cana, deu-lho a beber, dizendo: Deixai, vejamos se virá Elias tirá-lo.'),
('acf','mc',15,37,'E Jesus, dando um grande brado, expirou.'),
('acf','mc',15,38,'E o véu do templo se rasgou em dois, de alto a baixo.'),
('acf','mc',15,39,'E o centurião, que estava defronte dele, vendo que assim clamando expirara, disse: Verdadeiramente este homem era o Filho de Deus.'),
('acf','mc',15,40,'E também ali estavam algumas mulheres, olhando de longe, entre as quais também Maria Madalena, e Maria, mãe de Tiago, o menor, e de José, e Salomé;'),
('acf','mc',15,41,'As quais também o seguiam, e o serviam, quando estava na Galiléia; e muitas outras, que tinham subido com ele a Jerusalém.'),
('acf','mc',15,42,'E, chegada a tarde, porquanto era o dia da preparação, isto é, a véspera do sábado,'),
('acf','mc',15,43,'Chegou José de Arimatéia, senador honrado, que também esperava o reino de Deus, e ousadamente foi a Pilatos, e pediu o corpo de Jesus.'),
('acf','mc',15,44,'E Pilatos se maravilhou de que já estivesse morto. E, chamando o centurião, perguntou-lhe se já havia muito que tinha morrido.'),
('acf','mc',15,45,'E, tendo-se certificado pelo centurião, deu o corpo a José;'),
('acf','mc',15,46,'O qual comprara um lençol fino, e, tirando-o da cruz, o envolveu nele, e o depositou num sepulcro lavrado numa rocha; e revolveu uma pedra para a porta do sepulcro.'),
('acf','mc',15,47,'E Maria Madalena e Maria, mãe de José, observavam onde o punham.'),
('acf','mc',16,1,'E, passado o sábado, Maria Madalena, e Maria, mãe de Tiago, e Salomé, compraram aromas para irem ungi-lo.'),
('acf','mc',16,2,'E, no primeiro dia da semana, foram ao sepulcro, de manhã cedo, ao nascer do sol.'),
('acf','mc',16,3,'E diziam umas às outras: Quemnos revolverá a pedra da porta do sepulcro?'),
('acf','mc',16,4,'E, olhando, viram que já a pedra estava revolvida; e era ela muito grande.'),
('acf','mc',16,5,'E, entrando no sepulcro, viram um jovem assentado à direita, vestido de uma roupa comprida, branca; e ficaram espantadas.'),
('acf','mc',16,6,'Ele, porém, disse-lhes: Não vos assusteis; buscais a Jesus Nazareno, que foi crucificado; já ressuscitou, não está aqui; eis aqui o lugar onde o puseram.'),
('acf','mc',16,7,'Mas ide, dizei a seus discípulos, e a Pedro, que ele vai adiante de vós para a Galiléia; ali o vereis, como ele vos disse.'),
('acf','mc',16,8,'E, saindo elas apressadamente, fugiram do sepulcro, porque estavam possuídas de temor e assombro; e nada diziam a ninguém porque temiam.'),
('acf','mc',16,9,'E Jesus, tendo ressuscitado na manhã do primeiro dia da semana, apareceu primeiramente a Maria Madalena, da qual tinha expulsado sete demônios.'),
('acf','mc',16,10,'E, partindo ela, anunciou-o àqueles que tinham estado com ele, os quais estavam tristes, e chorando.'),
('acf','mc',16,11,'E, ouvindo eles que vivia, e que tinha sido visto por ela, não o creram.'),
('acf','mc',16,12,'E depois manifestou-se de outra forma a dois deles, que iam de caminho para o campo.'),
('acf','mc',16,13,'E, indo estes, anunciaram-no aos outros, mas nem ainda estes creram.'),
('acf','mc',16,14,'Finalmente apareceu aos onze, estando eles assentados juntamente, e lançou-lhes em rosto a sua incredulidade e dureza de coração, por não haverem crido nos que o tinham visto já ressuscitado.'),
('acf','mc',16,15,'E disse-lhes: Ide por todo omundo, pregai o evangelho a toda criatura.'),
('acf','mc',16,16,'Quem crer e for batizado será salvo; mas quem não crer será condenado.'),
('acf','mc',16,17,'E estes sinais seguirão aos que crerem: Em meu nome expulsarão os demônios; falarão novas línguas;'),
('acf','mc',16,18,'Pegarão nas serpentes; e, se beberem alguma coisa mortífera, não lhes fará dano algum; e porãoas mãos sobre os enfermos, e os curarão.'),
('acf','mc',16,19,'Ora, o Senhor, depois de lhes ter falado, foi recebido no céu, e assentou-se à direita de Deus.'),
('acf','mc',16,20,'E eles, tendo partido, pregaram por todas as partes, cooperando com eles o Senhor, e confirmando a palavra com os sinais que se seguiram. Amém.')
